"use client";

import Link from "next/link";
import { useCart } from "@/components/cart/cart-provider";
import { ProductImage } from "@/components/product-image";
import { useToast } from "@/components/ui/toast";
import { formatPrice, visiblePack } from "@/lib/format";
import { LinePrice, SavingsStrip } from "@/components/ui/sale-badge";

export default function CartPage() {
  const { items, subtotal, savings, setQuantity, remove, count, ready } = useCart();
  const toast = useToast();

  function handleRemove(id: string, name: string) {
    remove(id);
    toast.info(`${name} se quitó del carrito`);
  }

  // Cart lives in localStorage — avoid flashing an empty "Bs 0" bag before it loads.
  if (!ready) {
    return (
      <div className="mx-auto max-w-6xl px-5 py-14" aria-busy="true">
        <h1 className="font-display text-4xl font-semibold text-ink">Carrito</h1>
        <div className="mt-10 space-y-4">
          {[0, 1].map((i) => (
            <div key={i} className="h-28 animate-pulse rounded-xl bg-cream-soft" />
          ))}
        </div>
      </div>
    );
  }

  if (items.length === 0) {
    return (
      <div className="mx-auto max-w-2xl px-5 py-24 text-center">
        <h1 className="font-display text-4xl font-semibold text-ink">Tu carrito está vacío</h1>
        <p className="mt-3 text-muted">Encuentra tu próxima pieza en la colección.</p>
        <Link
          href="/shop"
          className="mt-8 inline-block rounded-full bg-gradient-to-r from-accent-soft to-accent px-8 py-3 text-sm font-medium text-brand transition hover:opacity-90"
        >
          Explorar la colección
        </Link>
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-6xl px-5 py-14">
      <h1 className="font-display text-4xl font-semibold text-ink">
        Carrito{ready && count > 0 ? ` (${count})` : ""}
      </h1>

      <div className="mt-10 grid items-start gap-10 lg:grid-cols-[1fr_360px]">
        {/* Items */}
        <ul className="divide-y divide-[var(--line)] border-y border-[var(--line)]">
          {items.map((item) => (
            <li key={item.id} className="flex gap-4 py-5">
              <Link
                href={`/product/${item.slug}`}
                className="h-24 w-24 shrink-0 overflow-hidden rounded-lg border border-[var(--line)] bg-sand"
              >
                <ProductImage src={item.image} alt={item.name} seed={item.slug} />
              </Link>

              <div className="flex flex-1 flex-col">
                <div className="flex justify-between gap-4">
                  <div>
                    <Link
                      href={`/product/${item.slug}`}
                      className="font-display text-lg text-ink hover:text-accent-strong"
                    >
                      {item.name}
                    </Link>
                    {visiblePack(item.material) && (
                      <p className="text-sm text-muted">{visiblePack(item.material)}</p>
                    )}
                  </div>
                  <LinePrice price={item.price} compareAt={item.compareAtPrice} quantity={item.quantity} />
                </div>

                <div className="mt-auto flex items-center justify-between pt-3">
                  <div className="flex items-center rounded-full border border-[var(--line-strong)]">
                    <button
                      onClick={() => setQuantity(item.id, item.quantity - 1)}
                      className="px-3 py-1.5 text-ink transition hover:text-accent-strong"
                      aria-label="Quitar una unidad"
                    >
                      −
                    </button>
                    <span className="w-8 text-center text-sm">{item.quantity}</span>
                    <button
                      onClick={() => setQuantity(item.id, item.quantity + 1)}
                      className="px-3 py-1.5 text-ink transition hover:text-accent-strong"
                      aria-label="Agregar una unidad"
                    >
                      +
                    </button>
                  </div>
                  <button
                    onClick={() => handleRemove(item.id, item.name)}
                    className="text-sm text-muted underline-offset-4 hover:text-red-700 hover:underline"
                  >
                    Quitar
                  </button>
                </div>
              </div>
            </li>
          ))}
        </ul>

        {/* Summary — locked in place while items scroll */}
        <aside className="rounded-xl border border-[var(--line)] bg-surface/70 p-6 lg:sticky lg:top-24 lg:self-start">
          <h2 className="font-display text-xl font-semibold text-ink">Resumen del pedido</h2>
          <dl className="mt-5 space-y-3 text-sm">
            <div className="flex justify-between">
              <dt className="text-muted">Subtotal</dt>
              <dd className="text-ink">{formatPrice(subtotal)}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-muted">Delivery</dt>
              <dd className="text-ink">Calculado al pagar</dd>
            </div>
          </dl>
          <div className="mt-5 flex justify-between border-t border-[var(--line)] pt-5">
            <span className="font-medium text-ink">Total</span>
            <span className="font-display text-xl font-semibold text-ink">
              {formatPrice(subtotal)}
            </span>
          </div>
          {savings > 0 && <SavingsStrip amount={savings} className="mt-5" />}
          {/* Guests are sent to sign in first (checkout needs an account), then back. */}
          <Link
            href="/checkout"
            className="mt-6 block rounded-full bg-gradient-to-r from-accent-soft to-accent px-8 py-3.5 text-center text-sm font-medium text-brand transition hover:opacity-90"
          >
            Proceder al pago
          </Link>
          <Link
            href="/shop"
            className="mt-3 block text-center text-sm text-accent-strong hover:underline"
          >
            Seguir comprando
          </Link>
        </aside>
      </div>
    </div>
  );
}
import type { Metadata } from "next";
import { redirect } from "next/navigation";
import { requireCustomer } from "@/lib/customer-auth";
import { prisma } from "@/lib/prisma";
import { CheckoutForm, type CheckoutDefaults } from "@/components/checkout-form";
import { payfastConfigured, safepayConfigured } from "@/lib/payments";
import { getProductBySlug } from "@/lib/catalog";
import { getSelectedBranch, shippingForBranch } from "@/lib/branch";
import { getStoreSettings } from "@/lib/settings";
import type { CartItem } from "@/components/cart/cart-provider";
import { toCartLine } from "@/lib/cart";

export const metadata: Metadata = {
  title: "Pago",
  robots: { index: false },
};

export const dynamic = "force-dynamic";

export default async function CheckoutPage({ searchParams }: PageProps<"/checkout">) {
  const sp = await searchParams;
  const p = Array.isArray(sp.payment) ? sp.payment[0] : sp.payment;
  const paymentNotice = p === "cancelled" || p === "failed" ? p : null;

  const buySlug = Array.isArray(sp.buy) ? sp.buy[0] : sp.buy;
  const qtyParam = Array.isArray(sp.qty) ? sp.qty[0] : sp.qty;

  // Every order belongs to one store; a branch must be picked before checkout.
  const branch = await getSelectedBranch();
  if (!branch) {
    const qs = new URLSearchParams();
    if (buySlug) qs.set("buy", buySlug);
    if (qtyParam) qs.set("qty", qtyParam);
    redirect(`/sucursal?next=${encodeURIComponent(`/checkout${qs.size ? `?${qs}` : ""}`)}`);
  }

  // Orders need an account: guests go to sign in and come straight back here
  // (the "Buy it now" choice is kept in the URL, the cart lives in the browser).
  const query = new URLSearchParams();
  if (buySlug) query.set("buy", buySlug);
  if (qtyParam) query.set("qty", qtyParam);
  const session = await requireCustomer(`/checkout${query.size ? `?${query}` : ""}`);

  const [product, phone, settings] = await Promise.all([
    buySlug ? getProductBySlug(buySlug, branch.id) : null,
    prisma.customer
      .findUnique({ where: { id: session.id }, select: { phone: true } })
      .then((c) => c?.phone ?? undefined)
      .catch(() => undefined), // phone is optional — ignore lookup failures
    getStoreSettings(),
  ]);

  // "Buy it now": check out a single product instead of the whole cart.
  let buyNow: CartItem | null = null;
  if (product && product.stock > 0) {
    const qtyRaw = Number(qtyParam);
    buyNow = {
      ...toCartLine(product),
      quantity: Math.min(product.stock, Math.max(1, Number.isFinite(qtyRaw) ? Math.floor(qtyRaw) : 1)),
    };
  }

  const defaults: CheckoutDefaults = { name: session.name, email: session.email, phone };

  return (
    <CheckoutForm
      defaults={defaults}
      paymentNotice={paymentNotice}
      buyNow={buyNow}
      branch={branch}
      shippingRules={shippingForBranch(branch, settings)}
      gateways={{ PAYFAST: payfastConfigured(), SAFEPAY: safepayConfigured() }}
    />
  );
}
import type { Metadata } from "next";
