import Link from "next/link";
import { requireAdmin } from "@/lib/admin";
import { getBranchById, getBranches } from "@/lib/branch";
import { getAdminInventory } from "@/lib/admin-data";
import { getStoreSettings } from "@/lib/settings";
import { DbBanner } from "@/components/admin/db-banner";
import { setBranchProductActive, setBranchStock } from "./actions";

export const metadata = { title: "Inventario" };
export const dynamic = "force-dynamic";

const field =
  "w-24 rounded-lg border border-[var(--line-strong)] bg-surface px-2.5 py-1.5 text-sm text-ink outline-none transition focus:border-accent";

export default async function AdminInventoryPage({
  searchParams,
}: {
  searchParams: Promise<{ branch?: string; q?: string }>;
}) {
  const session = await requireAdmin();
  const params = await searchParams;
  const isAdmin = session.role === "ADMIN";

  const branches = isAdmin ? await getBranches() : [];
  const requested = typeof params.branch === "string" ? params.branch : "";
  const branchId = isAdmin
    ? branches.find((b) => b.id === requested)?.id ?? branches[0]?.id ?? ""
    : session.branchId ?? "";
  const q = typeof params.q === "string" ? params.q.trim() : "";

  const [{ dbConnected, rows }, settings, branch] = await Promise.all([
    getAdminInventory(branchId, q),
    getStoreSettings(),
    branchId ? getBranchById(branchId) : Promise.resolve(null),
  ]);
  const lowThreshold = settings.inventory.lowStockThreshold;
  const units = rows.reduce((n, r) => n + r.stock, 0);
  const low = rows.filter((r) => r.available && r.stock <= lowThreshold).length;

  return (
    <div>
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h1 className="font-display text-3xl font-semibold text-ink">Inventario</h1>
          <p className="mt-1 text-sm text-muted">
            El catálogo es compartido; aquí ajustas las existencias de{" "}
            <strong className="text-ink">{branch?.name ?? "la sucursal"}</strong>.
          </p>
        </div>
        {isAdmin && (
          <Link
            href="/admin/branches"
            className="rounded-full border border-[var(--line-strong)] px-4 py-2 text-sm font-medium text-ink transition hover:border-accent hover:text-accent-strong"
          >
            Gestionar sucursales
          </Link>
        )}
      </div>

      {isAdmin && branches.length > 0 && (
        <form method="get" className="mt-5 flex flex-wrap items-end gap-3">
          <div>
            <label htmlFor="inv-branch" className="mb-1.5 block text-xs font-medium uppercase tracking-[0.1em] text-muted">
              Sucursal
            </label>
            <select
              id="inv-branch"
              name="branch"
              defaultValue={branchId}
              className="rounded-lg border border-[var(--line-strong)] bg-surface px-3 py-2 text-sm text-ink outline-none focus:border-accent"
            >
              {branches.map((b) => (
                <option key={b.id} value={b.id}>
                  {b.name} · {b.code}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label htmlFor="inv-q" className="mb-1.5 block text-xs font-medium uppercase tracking-[0.1em] text-muted">
              Buscar
            </label>
            <input
              id="inv-q"
              name="q"
              defaultValue={q}
              placeholder="Nombre, marca o SKU"
              className="rounded-lg border border-[var(--line-strong)] bg-surface px-3 py-2 text-sm text-ink outline-none focus:border-accent"
            />
          </div>
          <button
            type="submit"
            className="rounded-lg bg-brand px-4 py-2 text-sm font-medium text-light transition hover:bg-brand-dark"
          >
            Ver
          </button>
        </form>
      )}

      {!dbConnected && <div className="mt-6"><DbBanner /></div>}

      {!branchId ? (
        <div className="mt-6 rounded-xl border border-dashed border-[var(--line)] bg-cream-soft py-16 text-center">
          <p className="font-display text-xl text-ink">No hay sucursal asignada</p>
          <p className="mt-1 text-sm text-muted">
            {isAdmin
              ? "Crea la primera sucursal para empezar a cargar inventario."
              : "Pide a un administrador que asigne tu usuario a una sucursal."}
          </p>
          {isAdmin && (
            <Link href="/admin/branches/new" className="mt-4 inline-block rounded-full bg-brand px-5 py-2.5 text-sm font-medium text-light">
              + Nueva sucursal
            </Link>
          )}
        </div>
      ) : (
        <>
          <div className="mt-6 grid grid-cols-2 gap-3 sm:grid-cols-3">
            <Stat label="Productos" value={String(rows.length)} />
            <Stat label="Unidades en stock" value={String(units)} />
            <Stat label={`Stock bajo (≤ ${lowThreshold})`} value={String(low)} tone={low > 0 ? "warn" : "ok"} />
          </div>

          {rows.length === 0 ? (
            <div className="mt-6 rounded-xl border border-dashed border-[var(--line)] bg-cream-soft py-16 text-center">
              <p className="font-display text-xl text-ink">Sin productos</p>
              <p className="mt-1 text-sm text-muted">
                {q ? "Ningún producto coincide con la búsqueda." : "Agrega productos al catálogo para cargar existencias."}
              </p>
            </div>
          ) : (
            <div className="mt-6 overflow-x-auto rounded-xl border border-[var(--line)] bg-cream-soft">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-[var(--line)] text-left text-xs uppercase tracking-wider text-muted">
                    <th className="px-4 py-3">Producto</th>
                    <th className="px-4 py-3">Categoría</th>
                    <th className="px-4 py-3">Stock</th>
                    <th className="px-4 py-3">Disponibilidad</th>
                  </tr>
                </thead>
                <tbody>
                  {rows.map((p) => (
                    <tr key={p.id} className="border-b border-[var(--line)] last:border-0">
                      <td className="px-4 py-3">
                        <Link href={`/admin/products/${p.id}`} className="font-medium text-ink hover:text-accent-strong">
                          {p.name}
                        </Link>
                        {p.sku && <p className="text-xs text-muted">SKU {p.sku}</p>}
                        {!p.catalogActive && <p className="text-xs text-amber-700">Oculto en el catálogo</p>}
                      </td>
                      <td className="px-4 py-3 text-muted">{p.category}</td>
                      <td className="px-4 py-3">
                        <form action={setBranchStock} className="flex items-center gap-2">
                          <input type="hidden" name="branchId" value={branchId} />
                          <input type="hidden" name="productId" value={p.id} />
                          <input
                            type="number"
                            name="stock"
                            min={0}
                            step={1}
                            defaultValue={p.stock}
                            aria-label={`Stock de ${p.name}`}
                            className={field}
                          />
                          <button
                            type="submit"
                            className="rounded-lg border border-[var(--line-strong)] px-2.5 py-1.5 text-xs font-medium text-ink transition hover:border-accent hover:text-accent-strong"
                          >
                            Guardar
                          </button>
                        </form>
                        {p.available && p.stock === 0 && (
                          <p className="mt-1 text-xs text-red-600">Sin stock</p>
                        )}
                        {p.available && p.stock > 0 && p.stock <= lowThreshold && (
                          <p className="mt-1 text-xs text-amber-700">Stock bajo</p>
                        )}
                      </td>
                      <td className="px-4 py-3">
                        <form action={setBranchProductActive} className="flex items-center gap-2">
                          <input type="hidden" name="branchId" value={branchId} />
                          <input type="hidden" name="productId" value={p.id} />
                          <input type="hidden" name="active" value={p.available ? "0" : "1"} />
                          <span
                            className={`rounded-full px-2 py-0.5 text-xs ${
                              p.available ? "bg-green-100 text-green-800" : "bg-gray-200 text-gray-600"
                            }`}
                          >
                            {p.available ? "Disponible" : "Oculto aquí"}
                          </span>
                          <button
                            type="submit"
                            className="text-xs text-accent-strong hover:underline"
                          >
                            {p.available ? "Ocultar" : "Mostrar"}
                          </button>
                        </form>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </>
      )}
    </div>
  );
}

function Stat({ label, value, tone }: { label: string; value: string; tone?: "ok" | "warn" }) {
  return (
    <div className="rounded-xl border border-[var(--line)] bg-cream-soft px-4 py-3">
      <p className="text-xs uppercase tracking-wider text-muted">{label}</p>
      <p className={`mt-1 font-display text-2xl font-semibold ${tone === "warn" ? "text-amber-700" : "text-ink"}`}>
        {value}
      </p>
    </div>
  );
}
import { requireAdmin } from "@/lib/admin";
import { getBranchById } from "@/lib/branch";
import type { Metadata } from "next";
import { AdminShell } from "@/components/admin/admin-shell";

export const metadata: Metadata = {
  title: { default: "Panel", template: "%s · Inbramet" },
  robots: { index: false, follow: false },
};

export default async function AdminLayout({ children }: { children: React.ReactNode }) {
  const session = await requireAdmin();
  const branchName = session.branchId
    ? (await getBranchById(session.branchId))?.name ?? null
    : null;

  return (
    <AdminShell email={session.email} role={session.role} branchName={branchName}>
      {children}
    </AdminShell>
  );
}
import { prisma } from "@/lib/prisma";
import { requireAdmin } from "@/lib/admin";
import { getStoreSettings } from "@/lib/settings";
import { getBalances, getHistory } from "@/lib/loyalty";
import { movementLabel, pointRuleLabel, stampCard, stampRuleLabel } from "@/lib/loyalty-shared";
import { formatDate } from "@/lib/format";
import { AdjustForm, LoyaltyRulesForm, RewardForm, type RewardRow } from "@/components/admin/loyalty-forms";
import { setRedemptionStatus, setRewardActive } from "./actions";

export const metadata = { title: "Club" };
export const dynamic = "force-dynamic";

const STATUS_LABEL: Record<string, string> = {
  PENDING: "Pedido",
  READY: "Listo en caja",
  COLLECTED: "Entregado",
  CANCELLED: "Cancelado",
};

const STATUS_CHIP: Record<string, string> = {
  PENDING: "bg-amber-100 text-amber-900",
  READY: "bg-blue-100 text-blue-900",
  COLLECTED: "bg-green-100 text-green-900",
  CANCELLED: "bg-red-100 text-red-800",
};

async function loadRewards(): Promise<RewardRow[]> {
  try {
    return await prisma.reward.findMany({
      orderBy: [{ order: "asc" }, { costPoints: "asc" }],
      select: { id: true, slug: true, name: true, description: true, image: true, costPoints: true, stock: true, active: true, order: true },
    });
  } catch {
    return [];
  }
}

export default async function AdminLoyaltyPage({ searchParams }: PageProps<"/admin/loyalty">) {
  const session = await requireAdmin();
  const canEdit = session.role === "ADMIN";
  const sp = await searchParams;
  const q = (Array.isArray(sp.q) ? sp.q[0] : sp.q ?? "").trim();
  const selected = (Array.isArray(sp.cliente) ? sp.cliente[0] : sp.cliente ?? "").trim();

  const settings = await getStoreSettings();
  const rules = settings.loyalty;

  const [categories, products, rewards, redemptions, counts, customerRows] = await Promise.all([
    prisma.category.findMany({ orderBy: { name: "asc" }, select: { slug: true, name: true } }).catch(() => []),
    prisma.product
      .findMany({ where: { active: true }, orderBy: { name: "asc" }, select: { id: true, slug: true, name: true } })
      .catch(() => []),
    loadRewards(),
    prisma.redemption
      .findMany({
        orderBy: { createdAt: "desc" },
        take: 40,
        select: {
          id: true,
          code: true,
          rewardName: true,
          costPoints: true,
          status: true,
          createdAt: true,
          customer: { select: { name: true, email: true } },
          branch: { select: { name: true } },
        },
      })
      .catch(() => []),
    prisma.redemption
      .groupBy({ by: ["status"], _count: { _all: true } })
      .catch(() => [] as { status: string; _count: { _all: number } }[]),
    prisma.customer
      .findMany({
        where: q
          ? {
              OR: [
                { name: { contains: q, mode: "insensitive" } },
                { email: { contains: q, mode: "insensitive" } },
              ],
            }
          : { loyaltyEntries: { some: {} } },
        orderBy: { updatedAt: "desc" },
        take: 25,
        select: { id: true, name: true, email: true },
      })
      .catch(() => []),
  ]);

  const balanceByCustomer = new Map<string, { stamps: number; points: number }>();
  try {
    const grouped = await prisma.loyaltyEntry.groupBy({
      by: ["customerId"],
      _sum: { stamps: true, points: true },
    });
    for (const g of grouped)
      balanceByCustomer.set(g.customerId, { stamps: g._sum.stamps ?? 0, points: g._sum.points ?? 0 });
  } catch {
    // no table yet (migration pending) — the list simply shows zeros
  }

  const picked = selected ? customerRows.find((c) => c.id === selected) ?? null : null;
  const [pickedBalances, pickedHistory] = picked
    ? await Promise.all([getBalances(picked.id, rules).catch(() => null), getHistory(picked.id, 10).catch(() => [])])
    : [null, []];

  const pendingCount = counts.find((c) => c.status === "PENDING")?._count._all ?? 0;
  const members = balanceByCustomer.size;

  return (
    <div>
      <h1 className="font-display text-3xl font-bold text-ink">{rules.name}</h1>
      <p className="mt-1 text-sm text-muted">
        Sellos, puntos y regalos canjeables. {stampRuleLabel(rules)} · {pointRuleLabel(rules)}.
      </p>

      <nav className="mt-5 flex flex-wrap gap-2" aria-label="Secciones del club">
        {[
          { id: "reglas", label: "Reglas" },
          { id: "regalos", label: "Regalos" },
          { id: "canjes", label: `Canjes (${pendingCount})` },
          { id: "clientes", label: "Clientes" },
        ].map((s) => (
          <a
            key={s.id}
            href={`#${s.id}`}
            className="rounded-full border border-[var(--line-strong)] px-3.5 py-1.5 text-xs font-medium text-ink transition hover:border-accent hover:text-accent-strong"
          >
            {s.label}
          </a>
        ))}
      </nav>

      <div className="mt-6 space-y-6">
        {!canEdit && (
          <p className="rounded-lg border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-900">
            Has iniciado sesión como <strong>personal</strong>: puedes preparar y entregar canjes, pero
            solo un administrador cambia las reglas, los regalos y los saldos.
          </p>
        )}

        <LoyaltyRulesForm
          rules={rules}
          categories={categories}
          products={products.map((p) => ({ slug: p.slug, name: p.name }))}
          canEdit={canEdit}
        />

        {/* Rewards catalogue */}
        <section
          id="regalos"
          className="scroll-mt-24 rounded-2xl border border-[var(--line)] bg-surface p-5 shadow-[0_10px_30px_-22px_rgba(29,58,14,0.4)] sm:p-6"
        >
          <h2 className="font-display text-xl font-semibold text-ink">Regalos canjeables</h2>
          <p className="mt-1 text-sm text-muted">
            {members} cliente{members === 1 ? "" : "s"} con saldos. Un regalo sin stock aparece como
            «Agotado» en la tienda y nadie puede canjearlo.
          </p>
          <div className="mt-4 space-y-3">
            {rewards.map((r) => (
              <div key={r.id} className="flex flex-wrap items-start justify-between gap-2">
                <div className="min-w-0 flex-1">
                  {canEdit ? (
                    <RewardForm reward={r} canEdit={canEdit} />
                  ) : (
                    <p className="text-sm text-ink">
                      {r.name} · {r.costPoints} pts · {r.stock} en stock
                      {!r.active && <span className="text-muted"> · oculto</span>}
                    </p>
                  )}
                </div>
                {canEdit && (
                  <form action={setRewardActive.bind(null, r.id, !r.active)} className="shrink-0">
                    <button
                      type="submit"
                      className="rounded-lg border border-[var(--line-strong)] px-3 py-1.5 text-xs font-medium text-ink transition hover:border-accent hover:text-accent-strong"
                    >
                      {r.active ? "Ocultar de la tienda" : "Volver a mostrar"}
                    </button>
                  </form>
                )}
              </div>
            ))}
            {rewards.length === 0 && (
              <p className="rounded-xl border border-dashed border-[var(--line)] px-4 py-8 text-center text-sm text-muted">
                Todavía no hay regalos.{" "}
                {canEdit ? "Añade el primero abajo." : "Un administrador puede añadirlos."}
              </p>
            )}
            {canEdit && <RewardForm canEdit={canEdit} />}
          </div>
        </section>

        {/* Redemption counter */}
        <section
          id="canjes"
          className="scroll-mt-24 rounded-2xl border border-[var(--line)] bg-surface p-5 shadow-[0_10px_30px_-22px_rgba(29,58,14,0.4)] sm:p-6"
        >
          <h2 className="font-display text-xl font-semibold text-ink">Canjes para entregar</h2>
          <p className="mt-1 text-sm text-muted">
            El cliente muestra el código en caja. «Cancelar» devuelve el regalo al stock y los puntos al
            cliente.
          </p>
          {redemptions.length === 0 ? (
            <p className="mt-4 rounded-xl border border-dashed border-[var(--line)] px-4 py-10 text-center text-sm text-muted">
              Todavía nadie canjeó un regalo.
            </p>
          ) : (
            <ul className="mt-4 space-y-3">
              {redemptions.map((r) => (
                <li
                  key={r.id}
                  className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-[var(--line)] px-4 py-3"
                >
                  <div className="min-w-0">
                    <p className="font-medium text-ink">
                      {r.rewardName}{" "}
                      <span className="font-mono text-xs text-muted">{r.code}</span>
                    </p>
                    <p className="text-xs text-muted">
                      {r.customer.name} · {r.customer.email} · {r.costPoints} pts ·{" "}
                      {r.branch?.name ?? "sin sucursal"} · {formatDate(r.createdAt)}
                    </p>
                  </div>
                  <div className="flex flex-wrap items-center gap-2">
                    <span
                      className={`rounded-full px-2.5 py-0.5 text-xs font-medium ${STATUS_CHIP[r.status] ?? "bg-cream-soft text-ink"}`}
                    >
                      {STATUS_LABEL[r.status] ?? r.status}
                    </span>
                    {(["READY", "COLLECTED", "CANCELLED"] as const)
                      .filter((s) => s !== r.status)
                      .map((s) => (
                        <form key={s} action={setRedemptionStatus.bind(null, r.id, s)}>
                          <button
                            type="submit"
                            className="rounded-lg border border-[var(--line-strong)] px-2.5 py-1 text-xs font-medium text-ink transition hover:border-accent hover:text-accent-strong"
                          >
                            {STATUS_LABEL[s]}
                          </button>
                        </form>
                      ))}
                  </div>
                </li>
              ))}
            </ul>
          )}
        </section>

        {/* Customers */}
        <section
          id="clientes"
          className="scroll-mt-24 rounded-2xl border border-[var(--line)] bg-surface p-5 shadow-[0_10px_30px_-22px_rgba(29,58,14,0.4)] sm:p-6"
        >
          <h2 className="font-display text-xl font-semibold text-ink">Saldos por cliente</h2>
          <p className="mt-1 text-sm text-muted">
            Busca por nombre o correo y elige a alguien para ver sus tarjetas o corregir su saldo.
          </p>
          <form className="mt-4 flex flex-wrap gap-2" action="/admin/loyalty">
            {picked && <input type="hidden" name="cliente" value={picked.id} />}
            <input
              name="q"
              defaultValue={q}
              placeholder="Nombre o correo…"
              className="w-full max-w-xs rounded-lg border border-[var(--line-strong)] bg-surface px-3.5 py-2.5 text-sm text-ink outline-none focus:border-accent"
            />
            <button
              type="submit"
              className="rounded-lg bg-accent px-5 py-2.5 text-sm font-semibold text-brand-deep transition hover:bg-accent-soft"
            >
              Buscar
            </button>
          </form>

          {customerRows.length === 0 ? (
            <p className="mt-4 rounded-xl border border-dashed border-[var(--line)] px-4 py-10 text-center text-sm text-muted">
              {q ? "Ningún cliente coincide con la búsqueda." : "Aún no hay clientes con sellos o puntos."}
            </p>
          ) : (
            <ul className="mt-4 divide-y divide-[var(--line)]">
              {customerRows.map((c) => {
                const b = balanceByCustomer.get(c.id);
                return (
                  <li key={c.id} className="flex flex-wrap items-center justify-between gap-3 py-3">
                    <div className="min-w-0">
                      <p className="truncate font-medium text-ink">{c.name}</p>
                      <p className="truncate text-xs text-muted">{c.email}</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <span className="text-xs text-muted">
                        {b?.stamps ?? 0} sellos · {b?.points ?? 0} pts
                      </span>
                      <a
                        href={`/admin/loyalty?cliente=${c.id}${q ? `&q=${encodeURIComponent(q)}` : ""}`}
                        className="rounded-lg border border-[var(--line-strong)] px-3 py-1.5 text-xs font-medium text-ink transition hover:border-accent hover:text-accent-strong"
                      >
                        Ver y ajustar
                      </a>
                    </div>
                  </li>
                );
              })}
            </ul>
          )}

          {picked && pickedBalances && (
            <div className="mt-6 space-y-4 rounded-2xl border border-[var(--line-strong)] bg-cream-soft/60 p-4">
              <div>
                <p className="font-display text-lg font-semibold text-ink">
                  {picked.name} · {pickedBalances.points} pts
                </p>
                <div className="mt-2 flex flex-wrap gap-2 text-xs">
                  {Object.entries(pickedBalances.stampsByProduct)
                    .filter(([id, n]) => id !== "" && n > 0)
                    .map(([id, n]) => {
                      const p = products.find((x) => x.id === id);
                      const card = stampCard(n, rules);
                      return (
                        <span
                          key={id}
                          className={`rounded-full border px-2.5 py-1 ${
                            card.full
                              ? "border-accent bg-accent/15 text-ink"
                              : "border-[var(--line-strong)] text-muted"
                          }`}
                        >
                          {p?.name ?? "Producto"}: {card.filled}/{card.size}
                          {card.full && " · lista"}
                        </span>
                      );
                    })}
                  {Object.values(pickedBalances.stampsByProduct).filter((n) => n > 0).length === 0 && (
                    <span className="text-muted">Sin sellos activos.</span>
                  )}
                </div>
              </div>

              {pickedHistory.length > 0 && (
                <ul className="max-h-48 space-y-1 overflow-y-auto text-xs text-muted">
                  {pickedHistory.map((h) => (
                    <li key={h.id} className="flex justify-between gap-3">
                      <span className="min-w-0 truncate">
                        {movementLabel(h)}
                      </span>
                      <span className="shrink-0 tabular-nums">
                        {h.stamps !== 0 && `${h.stamps > 0 ? "+" : ""}${h.stamps} sellos`}
                        {h.stamps !== 0 && h.points !== 0 && " · "}
                        {h.points !== 0 && `${h.points > 0 ? "+" : ""}${h.points} pts`}
                      </span>
                    </li>
                  ))}
                </ul>
              )}

              {canEdit && (
                <AdjustForm
                  customerId={picked.id}
                  products={products.map((p) => ({ id: p.id, name: p.name }))}
                  canEdit={canEdit}
                />
              )}
            </div>
          )}
        </section>
      </div>
    </div>
  );
}
import { prisma } from "@/lib/prisma";
import { requireAdmin } from "@/lib/admin";
import { DbBanner } from "@/components/admin/db-banner";
import { toggleMessageHandled } from "./actions";
import { splitReferencePhotos } from "@/lib/custom-request";
import { formatDate } from "@/lib/format";

export const metadata = { title: "Mensajes" };

export const dynamic = "force-dynamic";

async function load() {
  try {
    const [messages, subscribers, subscriberCount] = await Promise.all([
      prisma.contactMessage.findMany({ orderBy: { createdAt: "desc" }, take: 100 }),
      prisma.subscriber.findMany({ orderBy: { createdAt: "desc" }, take: 200 }),
      prisma.subscriber.count(),
    ]);
    return { dbConnected: true, messages, subscribers, subscriberCount };
  } catch {
    return { dbConnected: false, messages: [], subscribers: [], subscriberCount: 0 };
  }
}

// Custom-design requests may end with reference photos — show them as thumbnails.
function MessageBody({ message }: { message: string }) {
  const { text, photos } = splitReferencePhotos(message);
  return (
    <>
      <p className="mt-2 whitespace-pre-wrap text-sm text-ink/85">{text}</p>
      {photos.length > 0 && (
        <div className="mt-3">
          <p className="mb-2 text-[0.65rem] font-medium uppercase tracking-[0.14em] text-accent-strong">
            Fotos de referencia ({photos.length}): haz clic para abrir a tamaño completo
          </p>
          <div className="flex flex-wrap gap-2">
            {photos.map((src, i) => (
              <a
                key={src}
                href={src}
                target="_blank"
                rel="noopener noreferrer"
                className="block h-24 w-24 overflow-hidden rounded-lg border border-[var(--line-strong)] transition hover:border-accent"
              >
                {/* eslint-disable-next-line @next/next/no-img-element -- customer upload, any size */}
                <img src={src} alt={`Foto de referencia ${i + 1}`} className="h-full w-full object-cover" loading="lazy" />
              </a>
            ))}
          </div>
        </div>
      )}
    </>
  );
}

export default async function AdminMessagesPage() {
  await requireAdmin();
  const { dbConnected, messages, subscribers, subscriberCount } = await load();
  const open = messages.filter((m) => !m.handled).length;

  return (
    <div>
      <h1 className="font-display text-3xl font-bold text-ink">Mensajes</h1>
      <p className="mt-1 text-sm text-muted">
        Mensajes del formulario de contacto ({open} abiertos) y suscripciones al newsletter / “avísame”.
      </p>

      <div className="mt-6 space-y-8">
        {!dbConnected && <DbBanner />}

        <section className="rounded-2xl border border-[var(--line)] bg-surface shadow-[0_10px_30px_-22px_rgba(29,58,14,0.4)]">
          <h2 className="border-b border-[var(--line)] px-5 py-4 font-display text-xl font-semibold text-ink">Bandeja de entrada</h2>
          {messages.length === 0 ? (
            <p className="px-5 py-12 text-center text-sm text-muted">Aún no hay mensajes.</p>
          ) : (
            <ul>
              {messages.map((m) => (
                <li key={m.id} className={`border-b border-[var(--line)] px-5 py-4 last:border-0 ${m.handled ? "opacity-60" : ""}`}>
                  <div className="flex flex-wrap items-start justify-between gap-3">
                    <div className="min-w-0">
                      <p className="font-medium text-ink">
                        {m.subject || "Mensaje"}{" "}
                        {m.topic && (
                          <span className="ml-1 rounded-full bg-accent/10 px-2 py-0.5 text-[0.65rem] uppercase tracking-wider text-accent-strong">
                            {m.topic}
                          </span>
                        )}
                      </p>
                      <p className="text-xs text-muted">
                        {m.name} ·{" "}
                        <a href={`mailto:${m.email}`} className="hover:text-accent-strong">
                          {m.email}
                        </a>
                        {m.phone ? ` · ${m.phone}` : ""} · {formatDate(m.createdAt, { time: true })}
                      </p>
                    </div>
                    <form action={toggleMessageHandled.bind(null, m.id, !m.handled)}>
                      <button className="rounded-md border border-[var(--line-strong)] px-3 py-1.5 text-xs text-ink transition hover:border-accent hover:text-accent-strong">
                        {m.handled ? "Reabrir" : "Marcar como atendido"}
                      </button>
                    </form>
                  </div>
                  <MessageBody message={m.message} />
                </li>
              ))}
            </ul>
          )}
        </section>

        <section className="rounded-2xl border border-[var(--line)] bg-surface shadow-[0_10px_30px_-22px_rgba(29,58,14,0.4)]">
          <h2 className="border-b border-[var(--line)] px-5 py-4 font-display text-xl font-semibold text-ink">
            Suscriptores <span className="text-sm font-normal text-muted">({subscriberCount})</span>
          </h2>
          {subscribers.length === 0 ? (
            <p className="px-5 py-12 text-center text-sm text-muted">Aún no hay suscripciones.</p>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-[var(--line)] text-left text-[0.68rem] uppercase tracking-wider text-muted">
                    <th className="px-5 py-3 font-medium">Correo electrónico</th>
                    <th className="px-5 py-3 font-medium">Origen</th>
                    <th className="px-5 py-3 font-medium">Se unió</th>
                  </tr>
                </thead>
                <tbody>
                  {subscribers.map((s) => (
                    <tr key={s.id} className="border-b border-[var(--line)] last:border-0">
                      <td className="px-5 py-2.5 text-ink">{s.email}</td>
                      <td className="px-5 py-2.5 text-muted">{s.source ?? "—"}</td>
                      <td className="whitespace-nowrap px-5 py-2.5 text-muted">{formatDate(s.createdAt, { time: true })}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>
      </div>
    </div>
  );
}
import Link from "next/link";
import { notFound } from "next/navigation";
import { getAdminOrder } from "@/lib/admin-data";
import { formatPrice } from "@/lib/format";
import { StatusBadge } from "@/components/status-badge";
import { ShipmentPanel } from "@/components/admin/shipment-panel";
import { StatusUpdateForm } from "@/components/admin/status-update-form";
import { updateOrderStatus, updatePaymentStatus } from "../actions";
import { ORDER_TRANSITIONS, PAYMENT_TRANSITIONS } from "@/lib/order-status";
import { courierLabel, trackingUrl } from "@/lib/couriers";
import { requireAdmin, scopeBranchId } from "@/lib/admin";

export const metadata = { title: "Detalle del pedido" };

export const dynamic = "force-dynamic";

export default async function AdminOrderDetailPage({
  params,
}: PageProps<"/admin/orders/[id]">) {
  const session = await requireAdmin(); // layouts don't re-run on client navigation
  const { id } = await params;
  const order = await getAdminOrder(id, scopeBranchId(session));
  if (!order) notFound();

  return (
    <div>
      <Link href="/admin/orders" className="text-sm text-muted hover:text-ink">
        ← Volver a pedidos
      </Link>

      <div className="mt-2 flex flex-wrap items-center gap-3">
        <h1 className="font-display text-3xl font-semibold text-ink">{order.orderNumber}</h1>
        <StatusBadge status={order.status} />
        <Link
          href={`/admin/invoice/${order.id}`}
          className="ml-auto rounded-lg border border-[var(--line-strong)] px-4 py-2 text-sm font-medium text-ink transition hover:border-accent hover:text-accent-strong"
        >
          Imprimir factura / hoja de embalaje
        </Link>
      </div>
      <p className="mt-1 text-sm text-muted">
        Realizado el {new Date(order.createdAt).toLocaleString("es-BO")} ·{" "}
        <span className="font-medium text-ink">{order.branch.name}</span> ({order.branch.code}) ·{" "}
        {order.fulfillment === "PICKUP" ? "Retiro en tienda" : "Entrega a domicilio"}
      </p>

      <div className="mt-8 grid gap-6 lg:grid-cols-[1fr_320px]">
        {/* Items + totals */}
        <div className="space-y-6">
          <div className="overflow-hidden rounded-xl border border-[var(--line)] bg-surface">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-[var(--line)] text-left text-xs uppercase tracking-wider text-muted">
                  <th className="px-4 py-3">Producto</th>
                  <th className="px-4 py-3">Precio</th>
                  <th className="px-4 py-3">Cant.</th>
                  <th className="px-4 py-3 text-right">Subtotal</th>
                </tr>
              </thead>
              <tbody>
                {order.items.map((i) => (
                  <tr key={i.id} className="border-b border-[var(--line)] last:border-0">
                    <td className="px-4 py-3 text-ink">{i.name}</td>
                    <td className="px-4 py-3 text-muted">{formatPrice(i.price)}</td>
                    <td className="px-4 py-3 text-muted">{i.quantity}</td>
                    <td className="px-4 py-3 text-right text-ink">
                      {formatPrice(i.price * i.quantity)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            <div className="space-y-1.5 border-t border-[var(--line)] px-4 py-4 text-sm">
              <Line label="Subtotal" value={formatPrice(order.subtotal)} />
              <Line label="Envío" value={order.shipping === 0 ? "Gratis" : formatPrice(order.shipping)} />
              <div className="flex justify-between border-t border-[var(--line)] pt-2 font-medium text-ink">
                <span>Total</span>
                <span>{formatPrice(order.total)}</span>
              </div>
            </div>
          </div>

          {/* Customer */}
          <div className="rounded-xl border border-[var(--line)] bg-surface p-5 text-sm">
            <h2 className="mb-3 font-display text-lg font-semibold text-ink">Cliente</h2>
            <dl className="space-y-1.5">
              <Info label="Nombre" value={order.customerName} />
              <Info label="Correo electrónico" value={order.email} />
              <Info label="Teléfono" value={order.phone} />
              <Info label="Sucursal" value={`${order.branch.name} (${order.branch.code})`} />
              <Info
                label="Entrega"
                value={order.fulfillment === "PICKUP" ? "Retiro en tienda" : "Entrega a domicilio"}
              />
              <Info
                label={order.fulfillment === "PICKUP" ? "Retiro en" : "Dirección"}
                value={
                  order.fulfillment === "PICKUP"
                    ? `${order.branch.address}, ${order.branch.city}`
                    : `${order.address ?? ""}, ${order.city ?? ""}${order.postalCode ? ` ${order.postalCode}` : ""}`
                }
              />
              {order.notes && <Info label="Notas" value={order.notes} />}
            </dl>
          </div>
        </div>

        {/* Status controls */}
        <aside className="space-y-5">
          {order.fulfillment === "DELIVERY" && (
            <ShipmentPanel
              id={order.id}
              booked={!!order.trackingNumber}
              courierName={order.courier ? courierLabel(order.courier) : undefined}
              trackingNumber={order.trackingNumber}
              trackUrl={order.courier && order.trackingNumber ? trackingUrl(order.courier, order.trackingNumber) : undefined}
            />
          )}

          <div className="rounded-xl border border-[var(--line)] bg-surface p-5">
            <h2 className="mb-3 font-display text-lg font-semibold text-ink">Estado del pedido</h2>
            <StatusUpdateForm
              action={updateOrderStatus.bind(null, order.id)}
              name="status"
              defaultValue={order.status}
              options={[order.status, ...ORDER_TRANSITIONS[order.status]]}
              successMessage="Estado del pedido actualizado"
            />
          </div>

          <div className="rounded-xl border border-[var(--line)] bg-surface p-5">
            <h2 className="mb-1 font-display text-lg font-semibold text-ink">Pago</h2>
            <p className="mb-3 text-sm text-muted">Método: {order.paymentMethod}</p>
            <StatusUpdateForm
              action={updatePaymentStatus.bind(null, order.id)}
              name="paymentStatus"
              defaultValue={order.paymentStatus}
              options={[order.paymentStatus, ...PAYMENT_TRANSITIONS[order.paymentStatus]]}
              successMessage="Estado del pago actualizado"
            />
          </div>
        </aside>
      </div>
    </div>
  );
}

function Line({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex justify-between text-muted">
      <span>{label}</span>
      <span className="text-ink">{value}</span>
    </div>
  );
}

function Info({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex gap-2">
      <dt className="w-20 shrink-0 text-muted">{label}</dt>
      <dd className="text-ink">{value}</dd>
    </div>
  );
}
import { getAdminOrders } from "@/lib/admin-data";
import { formatPrice } from "@/lib/format";
import { DbBanner } from "@/components/admin/db-banner";
import { OrdersTable } from "@/components/admin/orders-table";
import { requireAdmin, scopeBranchId } from "@/lib/admin";

export const metadata = { title: "Pedidos" };

export const dynamic = "force-dynamic";

export default async function AdminOrdersPage() {
  const session = await requireAdmin(); // layouts don't re-run on client navigation
  const { dbConnected, orders } = await getAdminOrders(scopeBranchId(session));

  const revenue = orders
    .filter((o) => o.status !== "CANCELLED")
    .reduce((s, o) => s + o.total, 0);
  const pending = orders.filter((o) => o.status === "PENDING").length;

  return (
    <div>
      <div className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <h1 className="font-display text-3xl font-bold text-ink">Pedidos</h1>
          <p className="mt-1 text-sm text-muted">Sigue, revisa y actualiza los pedidos de tus clientes.</p>
        </div>
        {orders.length > 0 && (
          // Plain link (not next/link): it downloads a file.
          <a
            href="/api/admin/orders/export"
            className="inline-flex items-center gap-2 rounded-lg border border-[var(--line-strong)] px-4 py-2 text-sm font-medium text-ink transition hover:border-accent hover:text-accent-strong"
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
              <path d="M12 4v11M7 10l5 5 5-5M5 20h14" />
            </svg>
            Exportar a Excel (CSV)
          </a>
        )}
      </div>

      <div className="mt-6">
        {!dbConnected && <DbBanner />}

        {orders.length === 0 ? (
          <div className="rounded-2xl border border-dashed border-[var(--line)] bg-surface py-16 text-center">
            <p className="font-display text-xl text-ink">Aún no hay pedidos</p>
            <p className="mt-1 text-sm text-muted">
              {dbConnected
                ? "Los pedidos realizados en la tienda aparecerán aquí."
                : "Conecta la base de datos para ver los pedidos reales."}
            </p>
          </div>
        ) : (
          <>
            {/* Quick stats */}
            <div className="mb-5 grid gap-4 sm:grid-cols-3">
              <MiniStat label="Pedidos totales" value={String(orders.length)} />
              <MiniStat label="Pendientes" value={String(pending)} accent />
              <MiniStat label="Ingresos" value={formatPrice(revenue)} />
            </div>

            <OrdersTable orders={orders} />
          </>
        )}
      </div>
    </div>
  );
}

function MiniStat({ label, value, accent }: { label: string; value: string; accent?: boolean }) {
  return (
    <div className="rounded-xl border border-[var(--line)] bg-surface p-4 shadow-[0_10px_30px_-24px_rgba(29,58,14,0.4)]">
      <p className="text-[0.62rem] font-medium uppercase tracking-[0.18em] text-muted">{label}</p>
      <p className={`mt-1.5 font-display text-2xl font-bold ${accent ? "text-accent-strong" : "text-ink"}`}>
        {value}
      </p>
    </div>
  );
}
import Link from "next/link";
import { getStoreSettings } from "@/lib/settings";
import { getAdminStats, getAdminOrders, getAdminProducts } from "@/lib/admin-data";
import { formatPrice, formatDate } from "@/lib/format";
import { DbBanner } from "@/components/admin/db-banner";
import { StatusBadge } from "@/components/status-badge";
import { requireAdmin, scopeBranchId } from "@/lib/admin";
import { TagIcon } from "@/components/icons";

export const metadata = { title: { absolute: "Panel · Inbramet" } };

export const dynamic = "force-dynamic";

export default async function AdminDashboard() {
  const session = await requireAdmin(); // layouts don't re-run on client navigation
  const branchId = scopeBranchId(session);
  const [stats, ordersData, productsData, settings] = await Promise.all([
    getAdminStats(branchId),
    getAdminOrders(branchId),
    getAdminProducts(branchId),
    getStoreSettings(),
  ]);
  const LOW = settings.inventory.lowStockThreshold;
  const recentOrders = ordersData.orders.slice(0, 5);
  const lowStockProducts = productsData.products
    .filter((p) => p.stock <= LOW)
    .sort((a, b) => a.stock - b.stock)
    .slice(0, 6);

  const cards = [
    { label: "Ingresos", value: formatPrice(stats.revenue), icon: <CoinIcon />, hint: "Todos los pedidos confirmados" },
    { label: "Este mes", value: formatPrice(stats.monthRevenue), icon: <TrendIcon />, hint: "Ingresos de este mes" },
    { label: "Pedidos", value: String(stats.orders), icon: <BagIcon />, hint: "Histórico" },
    { label: "Pedidos del mes", value: String(stats.monthOrders), icon: <CalendarIcon />, hint: "Realizados este mes" },
    { label: "Pendientes", value: String(stats.pendingOrders), icon: <ClockIcon />, hint: "En espera de gestión" },
    { label: "Productos", value: String(stats.products), icon: <TagIcon />, hint: "En el catálogo" },
    { label: "Clientes", value: String(stats.customers), icon: <UsersIcon />, hint: "Clientes registrados" },
    { label: "Stock bajo", value: String(stats.lowStock), icon: <AlertIcon />, hint: `${LOW} o menos disponibles` },
  ];

  return (
    <div>
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div>
          <h1 className="font-display text-3xl font-bold text-ink">Panel</h1>
          <p className="mt-1 text-sm text-muted">Bienvenido de nuevo al panel de gestión de Inbramet.</p>
        </div>
        <div className="flex gap-3">
          <Link
            href="/admin/products/new"
            className="rounded-full bg-brand px-5 py-2.5 text-sm font-medium text-light transition hover:bg-brand-dark"
          >
            + Agregar producto
          </Link>
          <Link
            href="/"
            className="rounded-full border border-[var(--line-strong)] px-5 py-2.5 text-sm text-ink transition hover:border-accent hover:text-accent-strong"
          >
            Ver tienda
          </Link>
        </div>
      </div>

      <div className="mt-8">
        {!stats.dbConnected && <DbBanner />}

        {/* Stat cards */}
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {/* KPI grid — 8 cards, 2 rows on desktop */}
          {cards.map((c) => (
            <div
              key={c.label}
              className="group relative overflow-hidden rounded-2xl border border-[var(--line)] bg-surface p-5 shadow-[0_10px_30px_-22px_rgba(29,58,14,0.45)] transition hover:-translate-y-0.5 hover:shadow-[0_20px_44px_-26px_rgba(29,58,14,0.55)]"
            >
              {/* accent top accent */}
              <span className="absolute inset-x-0 top-0 h-1 bg-gradient-to-r from-accent-soft via-accent to-accent-strong" />
              <div className="flex items-center justify-between">
                <span className="flex h-11 w-11 items-center justify-center rounded-xl bg-gradient-to-br from-brand to-brand-deep text-accent shadow-inner">
                  {c.icon}
                </span>
                <span className="text-[0.62rem] font-medium uppercase tracking-[0.18em] text-muted">
                  {c.label}
                </span>
              </div>
              <p className="mt-4 font-display text-3xl font-bold text-ink">{c.value}</p>
              <p className="mt-1 text-xs text-muted">{c.hint}</p>
            </div>
          ))}
        </div>

        {/* Recent orders + quick actions */}
        <div className="mt-8 grid gap-6 lg:grid-cols-[1fr_300px]">
          {/* Recent orders */}
          <section className="min-w-0 rounded-2xl border border-[var(--line)] bg-surface p-6 shadow-[0_10px_30px_-22px_rgba(29,58,14,0.4)]">
            <div className="flex items-center justify-between">
              <h2 className="font-display text-xl font-semibold text-ink">Pedidos recientes</h2>
              <Link href="/admin/orders" className="text-sm text-accent-strong hover:underline">
                Ver todo →
              </Link>
            </div>

            {recentOrders.length === 0 ? (
              <p className="mt-6 rounded-lg border border-dashed border-[var(--line)] py-10 text-center text-sm text-muted">
                {stats.dbConnected
                  ? "Aún no hay pedidos. Aparecerán aquí a medida que lleguen."
                  : "Conecta la base de datos para ver los pedidos."}
              </p>
            ) : (
              <div className="mt-4 overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-[var(--line)] text-left text-xs uppercase tracking-wider text-muted">
                      <th className="py-2 pr-3">Pedido</th>
                      <th className="py-2 pr-3">Cliente</th>
                      <th className="py-2 pr-3">Total</th>
                      <th className="py-2 pr-3">Estado</th>
                      <th className="py-2">Fecha</th>
                    </tr>
                  </thead>
                  <tbody>
                    {recentOrders.map((o) => (
                      <tr key={o.id} className="border-b border-[var(--line)] transition-colors last:border-0 hover:bg-cream-soft">
                        <td className="py-3 pr-3">
                          <Link href={`/admin/orders/${o.id}`} className="font-medium text-accent-strong hover:underline">
                            {o.orderNumber}
                          </Link>
                        </td>
                        <td className="py-3 pr-3 text-ink">{o.customerName}</td>
                        <td className="py-3 pr-3 text-ink">{formatPrice(o.total)}</td>
                        <td className="py-3 pr-3"><StatusBadge status={o.status} /></td>
                        <td className="py-3 text-muted">{formatDate(o.createdAt)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </section>

          {/* Quick actions */}
          <aside className="space-y-3">
            <h2 className="eyebrow mb-1">Acciones rápidas</h2>
            <QuickAction href="/admin/analytics" title="Analíticas" desc="Gráfico de ventas y tendencias" icon={<TrendIcon />} />
            <QuickAction href="/admin/insights" title="Tendencias" desc="Más vendidos y composición" icon={<CoinIcon />} />
            <QuickAction href="/admin/performance" title="Rendimiento" desc="Salud y flujo" icon={<ClockIcon />} />
            <QuickAction href="/admin/products/new" title="Agregar un producto" desc="Crea un producto nuevo" icon={<TagIcon />} />
            <QuickAction href="/admin/orders" title="Gestionar pedidos" desc="Actualiza y envía pedidos" icon={<BagIcon />} />
          </aside>
        </div>

        {/* Low stock */}
        <section className="mt-8 rounded-2xl border border-[var(--line)] bg-surface p-6 shadow-[0_10px_30px_-22px_rgba(29,58,14,0.4)]">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2.5">
              <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-amber-100 text-amber-700 dark:bg-amber-500/15">
                <AlertIcon />
              </span>
              <div>
                <h2 className="font-display text-xl font-semibold text-ink">Alerta de stock bajo</h2>
                <p className="text-xs text-muted">Productos con {LOW} o menos disponibles: repón pronto.</p>
              </div>
            </div>
            <Link href="/admin/products" className="shrink-0 text-sm text-accent-strong hover:underline">
              Todos los productos →
            </Link>
          </div>

          {lowStockProducts.length === 0 ? (
            <p className="mt-6 rounded-lg border border-dashed border-[var(--line)] py-8 text-center text-sm text-muted">
              {stats.dbConnected
                ? "Todo bien: todos los productos tienen stock suficiente. ✓"
                : "Conecta la base de datos para ver los niveles de stock."}
            </p>
          ) : (
            <div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {lowStockProducts.map((p) => (
                <Link
                  key={p.id}
                  href={`/admin/products/${p.id}`}
                  className="group flex items-center justify-between gap-3 rounded-xl border border-[var(--line)] bg-cream-soft px-4 py-3 transition hover:border-accent"
                >
                  <span className="min-w-0">
                    <span className="block truncate text-sm font-medium text-ink group-hover:text-accent-strong">
                      {p.name}
                    </span>
                    <span className="text-xs text-muted">{formatPrice(p.price)}</span>
                  </span>
                  <span
                    className={`shrink-0 rounded-full px-2.5 py-1 text-xs font-semibold ${
                      p.stock === 0
                        ? "bg-red-100 text-red-700 dark:bg-red-500/15"
                        : "bg-amber-100 text-amber-700 dark:bg-amber-500/15"
                    }`}
                  >
                    {p.stock === 0 ? "Agotado" : `${p.stock} disponibles`}
                  </span>
                </Link>
              ))}
            </div>
          )}
        </section>
      </div>
    </div>
  );
}

function QuickAction({
  href,
  title,
  desc,
  icon,
}: {
  href: string;
  title: string;
  desc: string;
  icon: React.ReactNode;
}) {
  return (
    <Link
      href={href}
      className="group flex items-center gap-3 rounded-xl border border-[var(--line)] bg-surface p-4 shadow-[0_10px_30px_-24px_rgba(29,58,14,0.4)] transition hover:border-accent hover:shadow-[0_16px_36px_-26px_rgba(29,58,14,0.5)]"
    >
      <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-brand/8 text-accent-strong transition group-hover:bg-brand group-hover:text-accent">
        {icon}
      </span>
      <span className="min-w-0 flex-1">
        <span className="block font-medium text-ink">{title}</span>
        <span className="block text-xs text-muted">{desc}</span>
      </span>
      <span className="text-accent-strong transition-transform group-hover:translate-x-0.5">→</span>
    </Link>
  );
}

