export const ADMIN_LINKS: { label: string; href: string; icon: ReactNode; adminOnly?: boolean }[] = [
  { label: "Panel", href: "/admin", icon: <GridIcon /> },
  { label: "Analíticas", href: "/admin/analytics", icon: <ChartIcon /> },
  { label: "Tendencias", href: "/admin/insights", icon: <SparkIcon /> },
  { label: "Rendimiento", href: "/admin/performance", icon: <GaugeIcon /> },
  { label: "Pedidos", href: "/admin/orders", icon: <BagIcon /> },
  { label: "Inventario", href: "/admin/inventory", icon: <BoxIcon /> },
  { label: "Productos", href: "/admin/products", icon: <TagIcon size={17} /> },
  { label: "Categorías", href: "/admin/categories", icon: <LayersIcon />, adminOnly: true },
  { label: "Sucursales", href: "/admin/branches", icon: <StoreIcon />, adminOnly: true },
  { label: "Clientes", href: "/admin/customers", icon: <UsersIcon /> },
  { label: "Club", href: "/admin/loyalty", icon: <GiftIcon /> },
  { label: "Mensajes", href: "/admin/messages", icon: <InboxIcon /> },
  { label: "Ajustes", href: "/admin/settings", icon: <GearIcon />, adminOnly: true },
];
const LINKS = ADMIN_LINKS;

export function visibleLinks(role: string) {
  return LINKS.filter((l) => !l.adminOnly || role === "ADMIN");
}

export function AdminNav({ collapsed = false, role = "ADMIN" }: { collapsed?: boolean; role?: string }) {
  const pathname = usePathname();

  const isActive = (href: string) =>
    href === "/admin" ? pathname === "/admin" : pathname.startsWith(href);

  // Fade labels; when expanding, wait for the width to grow before fading in.
  const labelStyle: React.CSSProperties = {
    transition: `opacity 180ms ease ${collapsed ? "0ms" : "130ms"}`,
  };

  return (
    <nav className="flex flex-col gap-1 p-3">
      {visibleLinks(role).map((l) => {
        const active = isActive(l.href);
        return (
          <Link
            key={l.href}
            href={l.href}
            title={collapsed ? l.label : undefined}
            aria-label={l.label}
            className={`flex items-center gap-3 rounded-md px-3 py-2.5 text-sm transition-colors ${
              active ? "bg-accent text-brand" : "text-light/80 hover:bg-brand-dark hover:text-accent"
            }`}
          >
            <span className="shrink-0">{l.icon}</span>
            <span
              style={labelStyle}
              className={`whitespace-nowrap ${collapsed ? "opacity-0" : "opacity-100"}`}
            >
              {l.label}
            </span>
          </Link>
        );
      })}
    </nav>
  );
}
"use client";

import { useEffect, useState, useSyncExternalStore } from "react";
import Link from "next/link";
import { Emblem } from "@/components/brand/emblem";
import { AdminNav } from "./admin-nav";
import { AdminMobileNav } from "./admin-mobile-nav";
import { OrderNotifications } from "./order-notifications";
import { logoutAction } from "@/app/admin/login/actions";

const STORAGE_KEY = "inbramet-admin-collapsed";

// Sidebar collapsed state persisted in localStorage (tiny external store).
const collapseListeners = new Set<() => void>();
function readCollapsed(): boolean {
  try {
    return localStorage.getItem(STORAGE_KEY) === "1";
  } catch {
    return false;
  }
}
function writeCollapsed(v: boolean) {
  try {
    localStorage.setItem(STORAGE_KEY, v ? "1" : "0");
  } catch {
    /* ignore */
  }
  collapseListeners.forEach((l) => l());
}
function subscribeCollapsed(l: () => void) {
  collapseListeners.add(l);
  return () => collapseListeners.delete(l);
}

export function AdminShell({
  email,
  role = "ADMIN",
  branchName = null,
  children,
}: {
  email: string;
  role?: string;
  branchName?: string | null;
  children: React.ReactNode;
}) {
  const collapsed = useSyncExternalStore(subscribeCollapsed, readCollapsed, () => false);
  // `ready` gates the width transition so the saved state applies instantly on
  // load (no animate-on-refresh); transitions only kick in for real toggles.
  const [ready, setReady] = useState(false);

  useEffect(() => {
    // enable transitions on the next frames, after the saved width is applied
    const r = requestAnimationFrame(() => requestAnimationFrame(() => setReady(true)));
    return () => cancelAnimationFrame(r);
  }, []);

  const toggle = () => writeCollapsed(!collapsed);

  // Fade labels; when expanding, delay so they appear after the width has grown.
  const labelStyle: React.CSSProperties = {
    transition: `opacity 180ms ease ${collapsed ? "0ms" : "130ms"}`,
  };
  const labelCls = `whitespace-nowrap ${collapsed ? "opacity-0" : "opacity-100"}`;

  return (
    // Full-height app frame — nothing scrolls here; the two panes scroll on their own.
    <div style={{ height: "100dvh" }} className="flex overflow-hidden bg-cream">
      {/* ── Sidebar (desktop) ── */}
      <aside
        style={{
          width: collapsed ? 76 : 240,
          transition: ready ? "width 300ms cubic-bezier(0.4, 0, 0.2, 1)" : undefined,
        }}
        className="hidden h-full shrink-0 flex-col overflow-hidden border-r border-[var(--line)] bg-brand text-light md:flex"
      >
        {/* Brand — full logo; the square emblem is only for the collapsed rail. */}
        <Link
          href="/admin"
          aria-label="Inbramet — panel"
          className="flex h-16 shrink-0 items-center justify-center border-b border-[rgba(163,212,120,0.2)] px-4 md:h-20"
        >
          {collapsed ? (
            <Emblem size={34} className="shrink-0 text-accent" />
          ) : (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src="/images/inbramet-logo.png"
              alt="Inbramet"
              width={228}
              height={169}
              className="h-[68px] w-auto drop-shadow-[0_6px_16px_rgba(0,0,0,0.45)]"
            />
          )}
        </Link>

        {/* Nav — scrolls vertically, clips labels horizontally */}
        <div className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden">
          <AdminNav collapsed={collapsed} role={role} />
        </div>

        {/* Footer — consistent icon+label rows so nothing jumps on collapse */}
        <div className="shrink-0 border-t border-[rgba(163,212,120,0.2)] p-3">
          <p
            style={labelStyle}
            className={`truncate px-3 pb-1 text-xs text-light/70 ${collapsed ? "opacity-0" : "opacity-100"}`}
          >
            {role === "ADMIN"
              ? "Todas las sucursales"
              : branchName
                ? `Sucursal: ${branchName}`
                : "Sin sucursal asignada"}
          </p>
          <p
            style={labelStyle}
            className={`truncate px-3 pb-1.5 text-xs text-light/50 ${collapsed ? "opacity-0" : "opacity-100"}`}
          >
            {email}
          </p>
          <form action={logoutAction}>
            <button
              title={collapsed ? "Cerrar sesión" : undefined}
              className="flex w-full items-center gap-3 rounded-md px-3 py-2.5 text-sm text-light/80 transition-colors hover:bg-brand-dark hover:text-accent"
            >
              <svg className="shrink-0" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7">
                <path d="M15 12H4M9 7l-5 5 5 5" strokeLinecap="round" strokeLinejoin="round" />
                <path d="M13 4h6a1 1 0 0 1 1 1v14a1 1 0 0 1-1 1h-6" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
              <span style={labelStyle} className={labelCls}>
                Cerrar sesión
              </span>
            </button>
          </form>
          <Link
            href="/"
            title={collapsed ? "Ver tienda" : undefined}
            className="flex items-center gap-3 rounded-md px-3 py-2.5 text-sm text-light/60 transition-colors hover:text-accent"
          >
            <svg className="shrink-0" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7">
              <path d="M3 11l9-7 9 7M5 10v9h14v-9" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
            <span style={labelStyle} className={labelCls}>
              Ver tienda
            </span>
          </Link>
        </div>
      </aside>

      {/* ── Content column ── */}
      <div className="flex h-full min-w-0 flex-1 flex-col">
        {/* Top bar (fixed height) */}
        <header className="flex h-16 shrink-0 items-center justify-between gap-3 border-b border-[var(--line)] bg-brand px-4 text-light md:h-20">
          <div className="flex items-center gap-2">
            {/* Desktop sidebar toggle — clear, always visible */}
            <button
              onClick={toggle}
              aria-label={collapsed ? "Expandir barra lateral" : "Contraer barra lateral"}
              title={collapsed ? "Expandir colección" : "Contraer colección"}
              className="hidden h-9 w-9 items-center justify-center rounded-md text-light/85 transition-colors hover:bg-brand-dark hover:text-accent md:flex"
            >
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7">
                <rect x="3" y="4" width="18" height="16" rx="2" />
                <line x1="9" y1="4" x2="9" y2="20" />
                <path
                  d={collapsed ? "M13.5 9.5l2.5 2.5-2.5 2.5" : "M16.5 9.5L14 12l2.5 2.5"}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </button>
            {/* Mobile brand */}
            <Link href="/admin" aria-label="Inbramet — panel" className="md:hidden">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src="/images/inbramet-logo.png"
                alt="Inbramet"
                width={228}
                height={169}
                className="h-8 w-auto"
              />
            </Link>
          </div>

          <div className="flex items-center gap-3 text-sm sm:gap-4">
            <OrderNotifications />
            <Link href="/" className="text-light/70 transition-colors hover:text-accent md:hidden">
              Ver tienda
            </Link>
            <form action={logoutAction} className="md:hidden">
              <button className="text-light/80 transition-colors hover:text-accent">Cerrar sesión</button>
            </form>
          </div>
        </header>

        {/* Mobile nav (fixed height) */}
        <div className="shrink-0">
          <AdminMobileNav role={role} />
        </div>

        {/* Scrollable content — this pane scrolls, the sidebar does not */}
        <main className="min-h-0 flex-1 overflow-y-auto">
          <div style={{ maxWidth: 1600 }} className="mx-auto w-full px-5 py-8 sm:px-8">
            {children}
          </div>
        </main>
      </div>
    </div>
  );
}
"use client";

import Link from "next/link";
import { useActionState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { useToast } from "@/components/ui/toast";
import type { AdminBranchRow } from "@/lib/admin-data";
import { createBranch, updateBranch } from "@/app/admin/(dashboard)/branches/actions";

const input =
  "w-full rounded-lg border border-[var(--line-strong)] bg-surface px-3.5 py-2.5 text-sm text-ink outline-none transition focus:border-accent focus:ring-2 focus:ring-[rgba(255,204,4,0.2)] disabled:opacity-60";
const labelCls = "mb-1.5 block text-xs font-medium uppercase tracking-[0.1em] text-muted";

function Field({
  name,
  label,
  hint,
  placeholder,
  required,
  defaultValue,
  type = "text",
  step,
  span,
}: {
  name: string;
  label: string;
  hint?: string;
  placeholder?: string;
  required?: boolean;
  defaultValue?: string | number;
  type?: string;
  step?: string;
  span?: boolean;
}) {
  return (
    <div className={span ? "sm:col-span-2" : undefined}>
      <label htmlFor={`br-${name}`} className={labelCls}>
        {label}
      </label>
      <input
        id={`br-${name}`}
        name={name}
        type={type}
        step={step}
        defaultValue={defaultValue}
        placeholder={placeholder}
        required={required}
        className={input}
      />
      {hint && <p className="mt-1 text-xs text-muted">{hint}</p>}
    </div>
  );
}

function Check({
  name,
  label,
  hint,
  defaultChecked,
}: {
  name: string;
  label: string;
  hint?: string;
  defaultChecked: boolean;
}) {
  return (
    <label className="flex items-start gap-2.5 rounded-lg border border-[var(--line)] bg-cream-soft px-3.5 py-2.5">
      <input type="checkbox" name={name} defaultChecked={defaultChecked} className="mt-0.5 h-4 w-4 accent-[var(--accent)]" />
      <span>
        <span className="block text-sm font-medium text-ink">{label}</span>
        {hint && <span className="block text-xs text-muted">{hint}</span>}
      </span>
    </label>
  );
}

export function BranchForm({ branch, mode }: { branch?: AdminBranchRow; mode: "create" | "edit" }) {
  const action =
    mode === "edit" && branch ? updateBranch.bind(null, branch.id) : createBranch;
  const [state, formAction, pending] = useActionState(action, {});
  const toast = useToast();
  const router = useRouter();

  useEffect(() => {
    if (state.ok) {
      if (mode === "create") {
        toast.success("Sucursal creada", { title: "Guardado" });
        router.push("/admin/branches");
      } else {
        toast.success("Cambios guardados", { title: "Guardado" });
        router.refresh();
      }
    } else if (state.error) {
      toast.error(state.error);
    }
  }, [state, toast, mode, router]);

  const text = (key: keyof AdminBranchRow, fallback = "") => {
    const saved = state.values?.[key];
    if (typeof saved === "string") return saved;
    const value = branch?.[key];
    return value == null ? fallback : String(value);
  };
  const flag = (key: "deliveryEnabled" | "pickupEnabled" | "active", fallback: boolean) => {
    const saved = state.values?.[key];
    return typeof saved === "boolean" ? saved : branch?.[key] ?? fallback;
  };

  return (
    <form
      key={state.values ? "error" : "initial"}
      action={formAction}
      className="space-y-6 rounded-2xl border border-[var(--line)] bg-surface p-5 shadow-[0_10px_30px_-22px_rgba(29,58,14,0.4)] sm:p-6"
    >
      <section>
        <h2 className="font-display text-lg font-semibold text-ink">Identificación</h2>
        <div className="mt-4 grid gap-4 sm:grid-cols-2">
          <Field name="name" label="Nombre de la sucursal" required defaultValue={text("name")} placeholder="Inbramet · Equipetrol" />
          <Field
            name="code"
            label="Código"
            required
            defaultValue={text("code")}
            placeholder="CC09"
            hint="Se usa al inicio del número de pedido (p. ej. CC01-241105-A1B2C3D4)."
          />
          <Field name="slug" label="Slug (opcional)" defaultValue={text("slug")} placeholder="automático" />
          <Field name="sortOrder" label="Orden en la lista" type="number" defaultValue={text("sortOrder", "0")} hint="Menor número = aparece primero." />
        </div>
      </section>

      <section className="border-t border-[var(--line)] pt-6">
        <h2 className="font-display text-lg font-semibold text-ink">Ubicación y contacto</h2>
        <div className="mt-4 grid gap-4 sm:grid-cols-2">
          <Field name="address" label="Dirección" required defaultValue={text("address")} placeholder="Avenida Cristóbal de Mendoza #1365" />
          <Field name="city" label="Ciudad" required defaultValue={text("city")} placeholder="Brasil" />
          <Field name="phone" label="Teléfono" defaultValue={text("phone")} placeholder="+591 700 00000" />
          <Field
            name="whatsapp"
            label="WhatsApp"
            defaultValue={text("whatsapp")}
            placeholder="59170000000"
            hint="Solo dígitos, formato internacional."
          />
          <Field name="hours" label="Horario" defaultValue={text("hours")} placeholder="Lunes a domingo · 11:00 a 23:00" span />
          <Field
            name="image"
            label="Foto de la sucursal"
            defaultValue={text("image")}
            placeholder="https://…"
            hint="Enlace https:// o ruta local que empiece por /."
            span
          />
          <Field
            name="mapsUrl"
            label="Enlace de Google Maps"
            defaultValue={text("mapsUrl")}
            placeholder="https://maps.app.goo.gl/…"
            span
          />
          <Field
            name="latitude"
            label="Latitud"
            type="number"
            step="any"
            defaultValue={text("latitude")}
            placeholder="-17.7833"
            hint="Opcional. Permite sugerir esta sucursal por geolocalización."
          />
          <Field
            name="longitude"
            label="Longitud"
            type="number"
            step="any"
            defaultValue={text("longitude")}
            placeholder="-63.1821"
            hint="Cópialas desde Google Maps (clic derecho → coordenadas)."
          />
        </div>
      </section>

      <section className="border-t border-[var(--line)] pt-6">
        <h2 className="font-display text-lg font-semibold text-ink">Entrega</h2>
        <p className="mt-1 text-sm text-muted">
          El costo y el umbral vacíos usan los ajustes generales de la tienda.
        </p>
        <div className="mt-4 grid gap-4 sm:grid-cols-2">
          <Field
            name="flatFee"
            label="Costo de envío (Bs)"
            type="number"
            defaultValue={text("flatFee")}
            placeholder="General"
          />
          <Field
            name="freeThreshold"
            label="Envío gratis desde (Bs)"
            type="number"
            defaultValue={text("freeThreshold")}
            placeholder="General"
          />
          <Check
            name="deliveryEnabled"
            label="Entrega a domicilio"
            hint="El cliente puede pedir envío en esta sucursal."
            defaultChecked={flag("deliveryEnabled", true)}
          />
          <Check
            name="pickupEnabled"
            label="Retiro en tienda"
            hint="El cliente recoge su pedido en esta dirección."
            defaultChecked={flag("pickupEnabled", true)}
          />
          <div className="sm:col-span-2">
            <Check
              name="active"
              label="Sucursal activa"
              hint="Desactívala para ocultarla de la tienda y del selector de sucursal (conserva pedidos e inventario)."
              defaultChecked={flag("active", true)}
            />
          </div>
        </div>
      </section>

      {state.error && (
        <p className="rounded-md border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">{state.error}</p>
      )}

      <div className="flex flex-wrap items-center justify-end gap-3 border-t border-[var(--line)] pt-5">
        <Link
          href="/admin/branches"
          className="rounded-lg border border-[var(--line-strong)] px-4 py-2.5 text-sm font-medium text-ink transition hover:border-accent hover:text-accent-strong"
        >
          Cancelar
        </Link>
        <button
          type="submit"
          disabled={pending}
          className="rounded-lg bg-accent px-5 py-2.5 text-sm font-semibold text-brand-deep transition hover:bg-accent-soft disabled:opacity-60"
        >
          {pending ? "Guardando…" : mode === "create" ? "Crear sucursal" : "Guardar cambios"}
        </button>
      </div>
    </form>
  );
}
