"use client";

import { useActionState } from "react";
import Link from "next/link";
import { loginAction, type AuthState } from "@/app/(store)/auth-actions";
import { AuthShell } from "@/components/auth/auth-shell";
import { AuthAlert, AuthField, AuthSubmit, SecureNote, useAuthForm } from "@/components/auth/auth-field";
import { emailError } from "@/lib/auth-rules";

const initial: AuthState = {};

const VALIDATE = {
  email: emailError,
  password: (v: string) => (v ? null : "Ingresa tu contraseña"),
};

export function LoginForm({ next }: { next?: string }) {
  const [state, formAction, pending] = useActionState(loginAction, initial);
  const [formRef, f] = useAuthForm(formAction, state, VALIDATE, { clearOnError: ["password"] });
  const email = f.field("email");
  const password = f.field("password", { positive: false });

  return (
    <AuthShell>
      <div className="text-center">
        <h1 className="font-display text-3xl font-bold text-ink">Hola de nuevo</h1>
        <p className="mt-1 text-sm text-muted">Inicia sesión para seguir comprando.</p>
      </div>

      {next?.startsWith("/checkout") && (
        <p className="mt-5 rounded-xl border border-accent/50 bg-accent/10 px-3.5 py-3 text-center text-sm text-ink">
          Inicia sesión o crea una cuenta gratis para realizar tu pedido — tu carrito se guarda.
        </p>
      )}

      <form ref={formRef} action={formAction} onSubmit={f.onSubmit} noValidate className="mt-7 space-y-5">
        {next && <input type="hidden" name="next" value={next} />}
        <AuthField
          name="email"
          label="Correo electrónico"
          icon="mail"
          type="email"
          autoComplete="email"
          placeholder="tu@ejemplo.com"
          {...f.bind("email")}
          {...email}
        />
        <AuthField
          name="password"
          label="Contraseña"
          icon="lock"
          password
          autoComplete="current-password"
          placeholder="Tu contraseña"
          {...f.bind("password")}
          labelAside={
            <Link href="/forgot-password" className="text-xs font-medium text-accent-strong hover:underline">
              ¿Olvidaste tu contraseña?
            </Link>
          }
          {...password}
        />

        {state.error && <AuthAlert>{state.error}</AuthAlert>}

        <div>
          <AuthSubmit pending={pending} label="Iniciar sesión" pendingLabel="Iniciando sesión…" />
          <SecureNote />
        </div>
      </form>

      <div className="mt-6 flex items-center gap-3 text-[0.65rem] uppercase tracking-[0.2em] text-muted">
        <span className="h-px flex-1 bg-[var(--line)]" />
        ¿Primera vez en Inbramet?
        <span className="h-px flex-1 bg-[var(--line)]" />
      </div>
      <Link
        href={next ? `/register?next=${encodeURIComponent(next)}` : "/register"}
        className="mt-4 block rounded-full border border-accent/60 py-3 text-center text-sm font-semibold uppercase tracking-[0.14em] text-accent-strong transition hover:border-accent hover:bg-accent/10"
      >
        Crear una cuenta
      </Link>
    </AuthShell>
  );
}
"use client";

import { useActionState, useEffect, useRef, useState, type ClipboardEvent, type KeyboardEvent } from "react";
import Link from "next/link";
import type { OtpState } from "@/app/(store)/auth-actions";
import { useToast } from "@/components/ui/toast";

type Action = (prev: OtpState, fd: FormData) => Promise<OtpState>;

const LENGTH = 6;

const boxCls =
  "h-14 w-11 rounded-xl border border-[var(--line-strong)] bg-surface text-center font-display text-2xl font-semibold text-ink outline-none transition focus:border-accent focus:ring-2 focus:ring-[rgba(255,204,4,0.3)] disabled:opacity-60 sm:h-16 sm:w-12";

const submitBtn =
  "w-full rounded-full bg-gradient-to-r from-accent-soft via-accent to-accent-strong px-6 py-3.5 text-sm font-bold uppercase tracking-[0.14em] text-brand-deep shadow-[0_16px_36px_-14px_rgba(255,204,4,0.75)] transition duration-300 hover:-translate-y-0.5 hover:brightness-105 disabled:opacity-60";

export function OtpForm({
  maskedEmail,
  verifyAction,
  resendAction,
  initialWait,
  changeHref,
  changeLabel,
}: {
  maskedEmail: string;
  verifyAction: Action;
  resendAction: Action;
  initialWait: number;
  changeHref: string;
  changeLabel: string;
}) {
  const [state, formAction, pending] = useActionState(verifyAction, {});
  const [resendState, resendFormAction, resending] = useActionState(resendAction, {});
  const [digits, setDigits] = useState<string[]>(Array(LENGTH).fill(""));
  const [wait, setWait] = useState(initialWait);
  const inputs = useRef<(HTMLInputElement | null)[]>([]);
  const formRef = useRef<HTMLFormElement>(null);
  const toast = useToast();

  // Countdown for "Resend code"
  useEffect(() => {
    if (wait <= 0) return;
    const t = setTimeout(() => setWait((w) => w - 1), 1000);
    return () => clearTimeout(t);
  }, [wait]);

  // New action results adjust local state during render (React's recommended
  // pattern instead of setState inside an effect).
  const [seenVerify, setSeenVerify] = useState(state);
  if (state !== seenVerify) {
    setSeenVerify(state);
    if (state.error) setDigits(Array(LENGTH).fill(""));
  }
  const [seenResend, setSeenResend] = useState(resendState);
  if (resendState !== seenResend) {
    setSeenResend(resendState);
    if (resendState.ok) setDigits(Array(LENGTH).fill(""));
    if (resendState.retryAfter) setWait(resendState.retryAfter);
  }

  // Side effects only: toasts + refocus the first box (success redirects).
  const lastVerify = useRef(state);
  useEffect(() => {
    if (state === lastVerify.current) return;
    lastVerify.current = state;
    if (state.error) {
      toast.error(state.error);
      inputs.current[0]?.focus();
    }
  }, [state, toast]);

  const lastResend = useRef(resendState);
  useEffect(() => {
    if (resendState === lastResend.current) return;
    lastResend.current = resendState;
    if (resendState.ok) {
      toast.success(resendState.message ?? "Código reenviado.", { title: "Revisa tu correo" });
      inputs.current[0]?.focus();
    } else if (resendState.error) toast.error(resendState.error);
  }, [resendState, toast]);

  const code = digits.join("");

  const fill = (start: number, chars: string) => {
    const next = [...digits];
    let i = start;
    for (const ch of chars.replace(/\D/g, "").slice(0, LENGTH - start)) next[i++] = ch;
    setDigits(next);
    inputs.current[Math.min(i, LENGTH - 1)]?.focus();
    // Auto-submit once all six digits are in.
    if (next.every(Boolean)) requestAnimationFrame(() => formRef.current?.requestSubmit());
  };

  const onKey = (i: number, e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Backspace" && !digits[i] && i > 0) {
      e.preventDefault();
      const next = [...digits];
      next[i - 1] = "";
      setDigits(next);
      inputs.current[i - 1]?.focus();
    } else if (e.key === "ArrowLeft" && i > 0) inputs.current[i - 1]?.focus();
    else if (e.key === "ArrowRight" && i < LENGTH - 1) inputs.current[i + 1]?.focus();
  };

  const onPaste = (i: number, e: ClipboardEvent<HTMLInputElement>) => {
    e.preventDefault();
    fill(i, e.clipboardData.getData("text"));
  };

  return (
    <div>
      <p className="text-center text-sm text-muted">
        Enviamos un código de 6 dígitos a <span className="font-medium text-ink">{maskedEmail}</span>. Ingrésalo
        abajo; vence en 10 minutos.
      </p>

      <form ref={formRef} action={formAction} className="mt-7 space-y-5">
        <input type="hidden" name="code" value={code} />
        <div className="flex justify-center gap-2 sm:gap-2.5" role="group" aria-label="Código de verificación">
          {digits.map((d, i) => (
            <input
              key={i}
              ref={(el) => {
                inputs.current[i] = el;
              }}
              value={d}
              onChange={(e) => {
                const v = e.target.value.replace(/\D/g, "");
                if (!v) {
                  const next = [...digits];
                  next[i] = "";
                  setDigits(next);
                } else fill(i, v);
              }}
              onKeyDown={(e) => onKey(i, e)}
              onPaste={(e) => onPaste(i, e)}
              onFocus={(e) => e.target.select()}
              inputMode="numeric"
              autoComplete={i === 0 ? "one-time-code" : "off"}
              maxLength={LENGTH}
              autoFocus={i === 0}
              disabled={pending}
              aria-label={`Dígito ${i + 1}`}
              className={boxCls}
            />
          ))}
        </div>

        {state.error && (
          <p className="rounded-md border border-red-200 bg-red-50 px-3 py-2 text-center text-sm text-red-700">{state.error}</p>
        )}

        <button type="submit" disabled={pending || code.length < LENGTH} className={submitBtn}>
          {pending ? "Verificando…" : "Verificar y continuar"}
        </button>
      </form>

      <div className="mt-6 flex flex-col items-center gap-2 text-sm text-muted">
        <form action={resendFormAction}>
          {wait > 0 ? (
            <span>
              ¿No lo recibiste? Podrás reenviar en <span className="font-medium text-ink tabular-nums">{wait}s</span>
            </span>
          ) : (
            <button type="submit" disabled={resending} className="font-medium text-accent-strong hover:underline disabled:opacity-60">
              {resending ? "Enviando…" : "Reenviar código"}
            </button>
          )}
        </form>
        <p className="text-xs">Revisa también las carpetas de spam o promociones.</p>
        <Link href={changeHref} className="text-xs text-accent-strong hover:underline">
          {changeLabel}
        </Link>
      </div>
    </div>
  );
}
"use client";

import { useState } from "react";

/** Show / hide control for password fields: a small accent pill with an eye that
 *  fills in when the password is revealed. */
export function RevealToggle({ shown, onToggle }: { shown: boolean; onToggle: () => void }) {
  return (
    <button
      type="button"
      onClick={onToggle}
      aria-pressed={shown}
      aria-label={shown ? "Ocultar contraseña" : "Mostrar contraseña"}
      className={`group/reveal mr-2 inline-flex h-8 shrink-0 items-center justify-center gap-1.5 rounded-full border px-2.5 text-[0.6rem] font-bold uppercase leading-none tracking-[0.16em] transition-[color,background-color,border-color,box-shadow] duration-300 ${
        shown
          ? "border-accent bg-gradient-to-r from-accent-soft via-accent to-accent-strong text-brand shadow-[0_6px_16px_-8px_rgba(255,204,4,0.9)]"
          : "border-accent/45 bg-transparent text-accent-strong hover:border-accent hover:bg-accent/10"
      }`}
    >
      <svg
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinejoin="round"
        strokeLinecap="round"
        aria-hidden="true"
        className={`h-4 w-4 shrink-0 transition-transform duration-500 ${shown ? "rotate-[360deg] scale-110" : "group-hover/reveal:scale-110"}`}
      >
        <path d="M2.5 12S6 6.5 12 6.5 21.5 12 21.5 12 18 17.5 12 17.5 2.5 12 2.5 12Z" fill={shown ? "currentColor" : "none"} fillOpacity={shown ? 0.16 : 0} />
        <circle cx="12" cy="12" r="2.7" />
        {shown && <path d="M4 4l16 16" strokeWidth="1.4" />}
      </svg>
      {/* Both words share one grid cell, so the pill is always as wide as the
          longer one and never jumps; the trailing letter-spacing is trimmed so
          the word sits optically centred. */}
      <span className="-mr-[0.16em] grid">
        <span className={`col-start-1 row-start-1 ${shown ? "invisible" : ""}`}>Ver</span>
        <span className={`col-start-1 row-start-1 ${shown ? "" : "invisible"}`}>Ocultar</span>
      </span>
    </button>
  );
}

// Password field with the show / hide toggle (used by the admin sign-in).
export function PasswordInput({
  name,
  autoComplete,
  required = false,
  minLength,
  className = "",
}: {
  name: string;
  autoComplete?: string;
  required?: boolean;
  minLength?: number;
  className?: string;
}) {
  const [show, setShow] = useState(false);

  return (
    <div className="relative">
      <input
        name={name}
        type={show ? "text" : "password"}
        required={required}
        minLength={minLength}
        autoComplete={autoComplete}
        className={`${className} pr-24`}
      />
      <span className="absolute right-0 top-1/2 -translate-y-1/2">
        <RevealToggle shown={show} onToggle={() => setShow((s) => !s)} />
      </span>
    </div>
  );
}
