"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { useToast } from "@/components/ui/toast";

// One points purchase in the rewards shop. On success the page is refreshed (so
// the balance and the "para recoger" list update) and the code is kept here,
// because that code is what the counter asks for.
export function RedeemButton({
  rewardId,
  rewardName,
  costPoints,
  pointsShort,
  stock,
}: {
  rewardId: string;
  rewardName: string;
  costPoints: number;
  /** How many points the customer still needs (0 = can afford it). */
  pointsShort: number;
  stock: number;
}) {
  const router = useRouter();
  const toast = useToast();
  const [busy, setBusy] = useState(false);
  const [code, setCode] = useState<string | null>(null);

  const disabled = busy || stock <= 0 || pointsShort > 0;

  async function redeem() {
    setBusy(true);
    try {
      const res = await fetch("/api/loyalty/redeem", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ rewardId }),
      });
      const data = (await res.json()) as { ok: boolean; code?: string; error?: string };
      if (!res.ok || !data.ok || !data.code) {
        throw new Error(data.error || "No pudimos completar el canje.");
      }
      setCode(data.code);
      toast.success(`Canjeaste "${rewardName}". Pide tu regalo en caja con el código ${data.code}.`, {
        title: "¡Regalo reservado!",
      });
      router.refresh();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "No pudimos completar el canje.", {
        title: "Canje no realizado",
      });
    } finally {
      setBusy(false);
    }
  }

  if (code) {
    return (
      <p className="mt-3 rounded-lg border border-accent/50 bg-accent/10 px-3 py-2 text-center text-xs text-ink">
        Presenta este código en caja: <span className="font-mono text-sm font-semibold">{code}</span>
      </p>
    );
  }

  return (
    <button
      type="button"
      onClick={redeem}
      disabled={disabled}
      title={
        stock <= 0
          ? "Agotado por ahora"
          : pointsShort > 0
            ? `Te faltan ${pointsShort} puntos para este regalo`
            : `Canjear por ${costPoints} puntos`
      }
      className="mt-3 w-full rounded-full bg-gradient-to-r from-accent-soft to-accent px-4 py-2.5 text-xs font-semibold uppercase tracking-[0.1em] text-brand transition hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-45"
    >
      {busy
        ? "Canjeando…"
        : stock <= 0
          ? "Agotado"
          : pointsShort > 0
            ? `Faltan ${pointsShort} pts`
            : `Canjear ${costPoints} pts`}
    </button>
  );
}
// Continuous scrolling announcement strip (pure CSS, pauses on hover).
// Lines are edited in Admin → Settings → Announcement bar.

export function Marquee({ items }: { items: string[] }) {
  if (items.length === 0) return null;
  // Rendered twice back-to-back so the -50% translate loops seamlessly.
  const strip = [...items, ...items];

  return (
    <div
      className="marquee-pause relative overflow-hidden border-y border-[rgba(163,212,120,0.28)] py-2.5 text-light"
      style={{ background: "linear-gradient(90deg, #3c6e1b 0%, #4c8a23 50%, #3c6e1b 100%)" }}
    >
      {/* soft accent glow edges */}
      <div
        className="pointer-events-none absolute inset-y-0 left-0 z-10 w-16"
        style={{ background: "linear-gradient(90deg, #3c6e1b, transparent)" }}
      />
      <div
        className="pointer-events-none absolute inset-y-0 right-0 z-10 w-16"
        style={{ background: "linear-gradient(270deg, #3c6e1b, transparent)" }}
      />

      <div className="flex w-max animate-marquee items-center whitespace-nowrap">
        {strip.map((t, i) => (
          <span key={i} className="flex items-center">
            <span className="px-7 text-[0.7rem] font-medium uppercase tracking-[0.22em] text-light/90">
              {t}
            </span>
            {/* accent diamond separator */}
            <span className="h-1.5 w-1.5 rotate-45 bg-accent-soft/70" aria-hidden="true" />
          </span>
        ))}
      </div>
    </div>
  );
}
"use client";

import { useEffect, useState } from "react";
import { useMounted } from "@/lib/use-mounted";
