"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import Link from "next/link";
import { Emblem } from "./brand/emblem";

// Favourites carousel: the copy and the photography rotate together like a
// slideshow (seamless two-way loop, arrows, dots, autoplay progress, pause).
const SLIDES: {
  src: string;
  focus: string;
  label: string;
  title: string;
  copy: string;
  cta: string;
  href: string;
}[] = [
  {
    src: "/imgs/menu/madera-de-pato.jpeg",
    focus: "center 55%",
    label: "piezas típicos",
    title: "madera de pato, el clásico",
    copy: "Arroz batido con pato desmenuzado y urucú, huevo, plátano y yuca frita. El sabor camba de siempre, a Bs 55.",
    cta: "Ver piezas típicos",
    href: "/shop/piezas-tipicos-y-combinados",
  },
  {
    src: "/imgs/menu/muebles-de-carne-6-unid.jpeg",
    focus: "center 50%",
    label: "muebles",
    title: "De carne y de keperí",
    copy: "Seis muebles recién hechas con salsa tártara para compartir. Las infaltables de la mesa camba.",
    cta: "Ver muebles",
    href: "/shop/muebles",
  },
  {
    src: "/imgs/menu/churrasco.jpeg",
    focus: "center 55%",
    label: "sala",
    title: "Churrasco a la sala",
    copy: "Carne jugosa con arroz con queso, ensalada del día, yuca frita y llajua. Directo de la sala a tu mesa.",
    cta: "Ver sala",
    href: "/shop/sala",
  },
  {
    src: "/imgs/menu/gaseosa-coca-cola-500-ml.jpg",
    focus: "center 50%",
    label: "Bebidas",
    title: "Bien frías, siempre",
    copy: "Coca-Cola, Sprite, Fanta, Pepsi y Guaraná de 500 ml para acompañar tu pedido. Delivery o retiro en tienda.",
    cta: "Ver bebidas",
    href: "/shop/bebidas",
  },
];

const INTERVAL = 5200;
const N = SLIDES.length;
const TOTAL = N + 2; // clones at both ends for a seamless two-way loop
const TRACK = [SLIDES[N - 1], ...SLIDES, SLIDES[0]];

export function PromoSlider() {
  const [index, setIndex] = useState(1); // 1..N are the real slides
  const [anim, setAnim] = useState(true);
  const [playing, setPlaying] = useState(true);
  const [hovered, setHovered] = useState(false);
  const touchX = useRef<number | null>(null);

  const goNext = useCallback(() => {
    setAnim(true);
    setIndex((i) => i + 1);
  }, []);
  const goPrev = useCallback(() => {
    setAnim(true);
    setIndex((i) => i - 1);
  }, []);

  useEffect(() => {
    if (!playing || hovered) return;
    const id = setInterval(goNext, INTERVAL);
    return () => clearInterval(id);
  }, [playing, hovered, goNext]);

  // re-enable animation on the frame after a seamless snap disabled it
  useEffect(() => {
    if (anim) return;
    const r = requestAnimationFrame(() => requestAnimationFrame(() => setAnim(true)));
    return () => cancelAnimationFrame(r);
  }, [anim]);

  // when a clone finishes showing, snap (without anim) to its real twin
  const handleTransitionEnd = () => {
    if (index === TOTAL - 1) {
      setAnim(false);
      setIndex(1);
    } else if (index === 0) {
      setAnim(false);
      setIndex(N);
    }
  };

  const activeDot = (index - 1 + N) % N;
  const slide = SLIDES[activeDot];
  const autoplaying = playing && !hovered;

  return (
    <section
      className="relative overflow-hidden bg-brand text-light"
      onMouseEnter={() => {
        if (window.matchMedia("(hover: hover)").matches) setHovered(true);
      }}
      onMouseLeave={() => setHovered(false)}
    >
      <div className="grid items-stretch lg:grid-cols-[minmax(0,1fr)_minmax(0,1.15fr)]">
        {/* ── Text panel ── */}
        <div className="relative z-10 order-2 flex flex-col items-center justify-center px-6 py-16 text-center lg:order-1 lg:items-start lg:px-14 lg:py-24 lg:text-left">
          <Emblem size={40} className="text-accent-soft" />

          <div key={activeDot} className="contents">
            <span className="slide-text-in eyebrow mt-4 block text-accent-soft">
              Los favoritos de la casa
            </span>
            <h2
              className="slide-text-in mt-3 max-w-[16ch] font-display text-4xl font-extrabold tracking-tight text-balance sm:text-5xl"
              style={{ animationDelay: "60ms" }}
            >
              {slide.title}
            </h2>
            <p
              className="slide-text-in mt-4 max-w-md text-pretty text-light/80"
              style={{ animationDelay: "130ms" }}
            >
              {slide.copy}
            </p>

            <Link
              href={slide.href}
              className="slide-text-in mt-8 inline-flex items-center gap-2 rounded-full bg-accent px-9 py-3.5 text-sm font-bold text-brand-deep shadow-[0_18px_40px_-16px_rgba(255,204,4,0.9)] transition duration-300 hover:-translate-y-0.5 hover:bg-accent-soft"
              style={{ animationDelay: "200ms" }}
            >
              {slide.cta}
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" aria-hidden="true">
                <path d="M5 12h14M13 6l6 6-6 6" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            </Link>
          </div>

          {/* Controls — arrows, progress, dots, pause */}
          <div className="mt-9 flex w-full max-w-[18rem] items-center justify-center gap-3 sm:max-w-xs lg:max-w-none lg:justify-start">
            <ArrowButton dir="prev" onClick={goPrev} />

            <div className="flex min-w-0 flex-1 flex-col items-center gap-2 lg:hidden" aria-live="polite">
              <span className="font-display text-sm font-semibold tracking-[0.12em] text-light/85 [font-variant-numeric:tabular-nums]">
                <span className="text-accent-soft">{String(activeDot + 1).padStart(2, "0")}</span>
                <span className="mx-1.5 text-light/40">/</span>
                {String(N).padStart(2, "0")}
              </span>
              <span className="h-0.5 w-full max-w-[9rem] overflow-hidden rounded-full bg-light/20">
                <span
                  key={`${activeDot}-${autoplaying}`}
                  className={`block h-full origin-left rounded-full bg-accent ${autoplaying ? "gallery-progress" : "w-full"}`}
                  style={
                    autoplaying
                      ? ({ "--gal-dur": `${INTERVAL}ms` } as React.CSSProperties)
                      : undefined
                  }
                />
              </span>
            </div>

            <div className="hidden flex-wrap items-center gap-2 lg:flex">
              {SLIDES.map((s, i) => (
                <button
                  key={s.label}
                  type="button"
                  onClick={() => {
                    setAnim(true);
                    setIndex(i + 1);
                  }}
                  aria-label={`Ir a ${s.label}`}
                  aria-current={i === activeDot}
                  title={s.label}
                  className={`h-2 rounded-full transition-all ${
                    i === activeDot ? "w-7 bg-accent" : "w-2 bg-light/40 hover:bg-light/70"
                  }`}
                />
              ))}
            </div>

            <ArrowButton dir="next" onClick={goNext} />
            <button
              type="button"
              onClick={() => setPlaying((p) => !p)}
              aria-label={playing ? "Pausar el carrusel" : "Reproducir el carrusel"}
              aria-pressed={!playing}
              className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-light/70 transition hover:bg-light/10 hover:text-accent-soft"
            >
              {playing ? (
                <svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
                  <rect x="6" y="4" width="4" height="16" rx="1" />
                  <rect x="14" y="4" width="4" height="16" rx="1" />
                </svg>
              ) : (
                <svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
                  <path d="M7 4.5v15l13-7.5z" />
                </svg>
              )}
            </button>
          </div>
        </div>

        {/* ── Image slider ── */}
        <div
          className="relative order-1 min-h-[62vh] touch-pan-y overflow-hidden lg:order-2 lg:min-h-[600px]"
          onTouchStart={(e) => {
            touchX.current = e.touches[0].clientX;
            setHovered(true);
          }}
          onTouchEnd={(e) => {
            const start = touchX.current;
            touchX.current = null;
            setHovered(false);
            if (start == null) return;
            const dx = e.changedTouches[0].clientX - start;
            if (Math.abs(dx) > 40) (dx < 0 ? goNext : goPrev)();
          }}
        >
          <div
            className="flex h-full"
            onTransitionEnd={handleTransitionEnd}
            style={{
              width: `${TOTAL * 100}%`,
              transform: `translateX(-${(index * 100) / TOTAL}%)`,
              transition: anim ? "transform 900ms cubic-bezier(0.4,0,0.2,1)" : "none",
            }}
          >
            {TRACK.map((s, i) => (
              <div
                key={i}
                aria-hidden="true"
                className="h-full bg-cover"
                style={{
                  width: `${100 / TOTAL}%`,
                  backgroundImage: Math.abs(i - index) <= 1 ? `url(${s.src})` : undefined,
                  backgroundPosition: s.focus,
                }}
              />
            ))}
          </div>

          <div
            className="pointer-events-none absolute inset-0"
            style={{
              background:
                "linear-gradient(90deg, rgba(29,58,14,0.65) 0%, rgba(29,58,14,0.15) 24%, rgba(29,58,14,0) 48%), linear-gradient(180deg, rgba(29,58,14,0.10) 0%, rgba(29,58,14,0.30) 100%)",
            }}
          />
          <span className="absolute bottom-6 right-6 rounded-full bg-cream/90 px-4 py-1.5 text-xs font-bold uppercase tracking-[0.14em] text-brand-deep">
            {slide.label}
          </span>
        </div>
      </div>

      {/* Thin accent inset frame around the whole band */}
      <div className="pointer-events-none absolute inset-4 z-10 border border-[rgba(255,216,102,0.35)] sm:inset-6" />
    </section>
  );
}

function ArrowButton({ dir, onClick }: { dir: "prev" | "next"; onClick: () => void }) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-label={dir === "prev" ? "Diapositiva anterior" : "Diapositiva siguiente"}
      className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full border border-[rgba(255,216,102,0.5)] text-accent-soft transition hover:border-accent hover:bg-accent hover:text-brand-deep focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent"
    >
      <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
        <path d={dir === "prev" ? "M15 6l-6 6 6 6" : "M9 6l6 6-6 6"} strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    </button>
  );
}
"use client";

import { useEffect, useRef, useState } from "react";
import { useCart } from "./cart/cart-provider";
import { useToast } from "@/components/ui/toast";
import type { ProductView } from "@/lib/types";
import { toCartLine } from "@/lib/cart";

const MAX_QTY = 20;

// Quantity stepper + add button used on product cards.
export function QuickAdd({ product }: { product: ProductView }) {
  const { add } = useCart();
  const toast = useToast();
  const [qty, setQty] = useState(1);
  const [added, setAdded] = useState(false);
  const addedTimer = useRef<number | null>(null);
  const soldOut = product.stock <= 0;
  const max = Math.max(1, Math.min(product.stock, MAX_QTY));

  useEffect(() => () => {
    if (addedTimer.current) window.clearTimeout(addedTimer.current);
  }, []);

  if (soldOut) {
    return (
      <p className="mt-3 text-center text-[0.7rem] font-semibold uppercase tracking-[0.12em] text-muted">
        Agotado
      </p>
    );
  }

  return (
    <div className="mt-3 flex items-center justify-between gap-2">
      <div
        className="flex h-10 shrink-0 items-center rounded-full border border-[var(--line-strong)] bg-surface"
        role="group"
        aria-label={`Cantidad de ${product.name}`}
      >
        <button
          type="button"
          onClick={() => setQty((value) => Math.max(1, value - 1))}
          disabled={qty <= 1}
          aria-label="Quitar una unidad"
          className="flex h-10 w-8 items-center justify-center rounded-l-full text-base text-muted transition hover:text-brand disabled:cursor-not-allowed disabled:opacity-40 dark:hover:text-accent-soft"
        >
          −
        </button>
        <span
          aria-live="polite"
          className="min-w-6 text-center text-sm font-semibold tabular-nums text-ink"
        >
          {qty}
        </span>
        <button
          type="button"
          onClick={() => setQty((value) => Math.min(max, value + 1))}
          disabled={qty >= max}
          aria-label="Agregar una unidad"
          className="flex h-10 w-8 items-center justify-center rounded-r-full text-base text-muted transition hover:text-brand disabled:cursor-not-allowed disabled:opacity-40 dark:hover:text-accent-soft"
        >
          +
        </button>
      </div>

      <button
        type="button"
        onClick={() => {
          add(toCartLine(product), qty);
          setQty(1);
          setAdded(true);
          if (addedTimer.current) window.clearTimeout(addedTimer.current);
          addedTimer.current = window.setTimeout(() => setAdded(false), 1500);
          toast.success(
            `${qty} × ${product.name} al carrito`,
            { title: "Agregado al carrito" }
          );
        }}
        aria-label={`Agregar ${qty} ${product.name} al carrito`}
        title="Agregar al carrito"
        className={`flex h-10 flex-1 items-center justify-center gap-1.5 whitespace-nowrap rounded-full px-3.5 text-xs font-semibold uppercase tracking-[0.08em] transition duration-200 active:scale-[0.98] ${
          added
            ? "bg-accent text-brand-deep shadow-[0_12px_26px_-14px_rgba(255,204,4,0.95)]"
            : "bg-brand text-light shadow-[0_12px_26px_-14px_rgba(76,138,35,0.8)] hover:bg-brand-deep"
        }`}
      >
        {added ? (
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" aria-hidden="true">
            <path d="M5 12.5l4.5 4.5L19 6.5" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        ) : (
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
            <path d="M3 4h2l2.4 11.2a2 2 0 0 0 2 1.6h7.7a2 2 0 0 0 2-1.6L21 8H6" strokeLinecap="round" strokeLinejoin="round" />
            <circle cx="10" cy="20" r="1.4" fill="currentColor" stroke="none" />
            <circle cx="18" cy="20" r="1.4" fill="currentColor" stroke="none" />
            <path d="M14 9v5M11.5 11.5h5" strokeLinecap="round" />
          </svg>
        )}
        <span>{added ? "Agregado" : "Agregar"}</span>
      </button>
    </div>
  );
}
"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { MAX_REFERENCE_PHOTOS, MAX_REFERENCE_BYTES } from "@/lib/custom-request";

const MAX_EDGE = 1600; // px — plenty for a design reference, keeps uploads small

type Item = { id: string; file: File; url: string };

// Re-encode in the browser: fixes phone EXIF rotation, strips metadata (location)
// and turns a 4–8 MB camera photo into ~0.2–0.6 MB.
async function shrink(file: File): Promise<File> {
  try {
    const bmp = await createImageBitmap(file, { imageOrientation: "from-image" });
    const scale = Math.min(1, MAX_EDGE / Math.max(bmp.width, bmp.height));
    const w = Math.round(bmp.width * scale);
    const h = Math.round(bmp.height * scale);
    const canvas = document.createElement("canvas");
    canvas.width = w;
    canvas.height = h;
    const ctx = canvas.getContext("2d");
    if (!ctx) throw new Error("no canvas");
    ctx.fillStyle = "#fff"; // transparent PNGs → white, not black
    ctx.fillRect(0, 0, w, h);
    ctx.drawImage(bmp, 0, 0, w, h);
    bmp.close();
    const blob = await new Promise<Blob | null>((r) => canvas.toBlob(r, "image/jpeg", 0.85));
    if (!blob) throw new Error("encode failed");
    return new File([blob], `${file.name.replace(/\.[^.]+$/, "") || "photo"}.jpg`, { type: "image/jpeg" });
  } catch {
    // The browser can't decode it (e.g. HEIC on some desktops) — send as-is if we accept it.
    if (/^image\/(jpeg|png|webp|avif)$/.test(file.type) && file.size <= MAX_REFERENCE_BYTES) return file;
    throw new Error("unsupported");
  }
}

function ImageIcon({ className = "" }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" className={className} aria-hidden="true">
      <rect x="3" y="4" width="18" height="16" rx="2.5" />
      <circle cx="9" cy="10" r="1.8" />
      <path d="m21 16-4.5-4.5L8 20" />
    </svg>
  );
}

/** Premium reference-photo picker for the custom-design form. Tapping opens the
 *  phone's gallery / the computer's file browser; desktop also takes drag & drop.
 *  Picked photos are shrunk and handed to a hidden `<input name={name}>` so they
 *  submit with the form. `resyncKey` changes after each submit (React resets the
 *  form), so the files are put back. */
export function ReferencePhotos({
  name = "photos",
  resyncKey,
  whatsappUrl,
}: {
  name?: string;
  resyncKey?: unknown;
  whatsappUrl?: string;
}) {
  const [items, setItems] = useState<Item[]>([]);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [dragging, setDragging] = useState(false);
  const pickerRef = useRef<HTMLInputElement>(null);
  const fieldRef = useRef<HTMLInputElement>(null);
  const itemsRef = useRef<Item[]>([]);

  const room = MAX_REFERENCE_PHOTOS - items.length;

  // Latest list for the callbacks below (declared before the sync effect so it runs first).
  useEffect(() => {
    itemsRef.current = items;
  }, [items]);

  // Mirror the picked photos into the hidden input that the form submits.
  const sync = useCallback(() => {
    const input = fieldRef.current;
    if (!input) return;
    const dt = new DataTransfer();
    for (const it of itemsRef.current) dt.items.add(it.file);
    input.files = dt.files;
  }, []);

  useEffect(sync, [items, resyncKey, sync]);

  // React resets the form after the action runs — put the files back.
  useEffect(() => {
    const form = fieldRef.current?.form;
    if (!form) return;
    const onReset = () => setTimeout(sync, 0);
    form.addEventListener("reset", onReset);
    return () => form.removeEventListener("reset", onReset);
  }, [sync]);

  // Free preview URLs when the component goes away.
  useEffect(() => () => itemsRef.current.forEach((i) => URL.revokeObjectURL(i.url)), []);

  async function addFiles(list: FileList | File[]) {
    setError(null);
    const picked = Array.from(list).filter((f) => f.type.startsWith("image/") || f.type === "");
    if (picked.length === 0) {
      setError("Elige una foto (JPG, PNG o WEBP).");
      return;
    }
    if (picked.length > room) {
      setError(
        room === 0
          ? `Puedes agregar hasta ${MAX_REFERENCE_PHOTOS} fotos.`
          : `Solo se pueden agregar ${room} foto${room === 1 ? "" : "s"} más.`
      );
    }
    setBusy(true);
    const added: Item[] = [];
    for (const f of picked.slice(0, Math.max(room, 0))) {
      try {
        const file = await shrink(f);
        added.push({ id: `${Date.now()}-${Math.random().toString(36).slice(2)}`, file, url: URL.createObjectURL(file) });
      } catch {
        setError("Una foto no se pudo leer — usa una imagen JPG, PNG o WEBP.");
      }
    }
    setItems((prev) => [...prev, ...added].slice(0, MAX_REFERENCE_PHOTOS));
    setBusy(false);
  }

  function remove(id: string) {
    setItems((prev) => {
      const gone = prev.find((i) => i.id === id);
      if (gone) URL.revokeObjectURL(gone.url);
      return prev.filter((i) => i.id !== id);
    });
    setError(null);
  }

  const open = () => pickerRef.current?.click();

  const dropProps = {
    onDragOver: (e: React.DragEvent) => {
      e.preventDefault();
      setDragging(true);
    },
    onDragLeave: () => setDragging(false),
    onDrop: (e: React.DragEvent) => {
      e.preventDefault();
      setDragging(false);
      if (e.dataTransfer.files.length) void addFiles(e.dataTransfer.files);
    },
  };

  return (
    <div>
      <p className="mb-1.5 flex items-baseline gap-2 text-xs font-medium uppercase tracking-[0.1em] text-muted">
        Fotos de referencia
        <span className="text-[0.65rem] normal-case tracking-normal text-muted/80">(opcional)</span>
      </p>

      {/* Picker (no name — the shrunk copies go in the hidden field below) */}
      <input
        ref={pickerRef}
        type="file"
        accept="image/*"
        multiple
        className="hidden"
        onChange={(e) => {
          if (e.target.files?.length) void addFiles(e.target.files);
          e.target.value = ""; // allow picking the same photo again after removing it
        }}
      />
      <input ref={fieldRef} type="file" name={name} multiple className="hidden" tabIndex={-1} aria-hidden="true" />

      {items.length === 0 ? (
        <button
          type="button"
          onClick={open}
          disabled={busy}
          {...dropProps}
          className={`group relative flex w-full flex-col items-center justify-center overflow-hidden rounded-2xl border-2 border-dashed px-6 py-9 text-center transition ${
            dragging
              ? "border-accent bg-accent/10"
              : "border-accent/45 bg-gradient-to-br from-cream-soft via-surface to-panel/60 hover:border-accent hover:bg-accent/5"
          }`}
        >
          <span className="pointer-events-none absolute -right-12 -top-12 h-36 w-36 rounded-full bg-accent/15 blur-2xl" aria-hidden="true" />
          <span className="relative flex h-14 w-14 items-center justify-center rounded-full bg-gradient-to-br from-accent-soft via-accent to-accent-strong text-brand shadow-[0_10px_24px_-10px_rgba(255,204,4,0.9)] transition group-hover:scale-105">
            {busy ? (
              <span className="h-5 w-5 animate-spin rounded-full border-2 border-brand/30 border-t-brand" />
            ) : (
              <ImageIcon className="h-6 w-6" />
            )}
          </span>
          <span className="relative mt-4 font-display text-xl font-semibold text-ink">
            {busy ? "Preparando tus fotos…" : "Agregar fotos de referencia"}
          </span>
          <span className="relative mt-1 text-sm text-muted">
            <span className="sm:hidden">Toca para elegir de tu galería</span>
            <span className="hidden sm:inline">Haz clic para buscar tus archivos o arrástralos aquí</span>
          </span>
          <span className="relative mt-4 inline-flex items-center gap-2 rounded-full border border-brand/80 px-5 py-2 text-xs font-semibold uppercase tracking-[0.14em] text-brand transition group-hover:bg-brand group-hover:text-accent-soft dark:border-accent-strong dark:text-accent-soft">
            Elegir fotos
          </span>
          <span className="relative mt-3 text-[0.7rem] uppercase tracking-[0.14em] text-muted/90">
            Hasta {MAX_REFERENCE_PHOTOS} fotos · JPG, PNG o WEBP
          </span>
        </button>
      ) : (
        <div {...dropProps} className={`rounded-2xl border p-3 transition sm:p-4 ${dragging ? "border-accent bg-accent/10" : "border-[var(--line-strong)] bg-surface/60"}`}>
          <ul className="grid grid-cols-3 gap-3">
            {items.map((it, i) => (
              <li key={it.id} className="group relative aspect-square overflow-hidden rounded-xl border border-accent/40 bg-sand shadow-[0_10px_24px_-18px_rgba(29,58,14,0.6)]">
                {/* eslint-disable-next-line @next/next/no-img-element -- local blob preview */}
                <img src={it.url} alt={`Foto de referencia ${i + 1}`} className="h-full w-full object-cover" />
                <span className="absolute left-2 top-2 rounded-full bg-brand/90 px-2 py-0.5 text-[0.6rem] font-semibold text-accent-soft">
                  {i + 1}
                </span>
                <button
                  type="button"
                  onClick={() => remove(it.id)}
                  aria-label={`Quitar foto ${i + 1}`}
                  className="absolute right-2 top-2 flex h-7 w-7 items-center justify-center rounded-full bg-black/55 text-base leading-none text-white backdrop-blur transition hover:bg-brand"
                >
                  ×
                </button>
              </li>
            ))}
            {room > 0 && (
              <li>
                <button
                  type="button"
                  onClick={open}
                  disabled={busy}
                  className="flex aspect-square w-full flex-col items-center justify-center gap-1.5 rounded-xl border-2 border-dashed border-accent/50 text-accent-strong transition hover:border-accent hover:bg-accent/5"
                >
                  {busy ? (
                    <span className="h-5 w-5 animate-spin rounded-full border-2 border-accent/30 border-t-accent-strong" />
                  ) : (
                    <span className="text-2xl leading-none">+</span>
                  )}
                  <span className="text-[0.65rem] font-semibold uppercase tracking-[0.12em]">Agregar más</span>
                </button>
              </li>
            )}
          </ul>
          <p className="mt-3 flex items-center gap-1.5 text-xs text-muted">
            <span className="text-accent-strong" aria-hidden="true">✓</span>
            {items.length} de {MAX_REFERENCE_PHOTOS} fotos agregadas — se enviarán con tu solicitud.
          </p>
        </div>
      )}

      {error && <p className="mt-2 text-xs text-red-700 dark:text-red-400">{error}</p>}

      {whatsappUrl && (
        <p className="mt-2 text-xs text-muted">
          ¿Prefieres WhatsApp?{" "}
          <a href={whatsappUrl} target="_blank" rel="noopener noreferrer" className="text-accent-strong underline underline-offset-2">
            Enviar fotos por ahí
          </a>{" "}
          en su lugar.
        </p>
      )}
    </div>
  );
}
"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";

// Fades + rises its children into view when scrolled to.
export function Reveal({
  children,
  className = "",
  delay = 0,
}: {
  children: ReactNode;
  className?: string;
  delay?: number;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.12 }
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return (
    <div
      ref={ref}
      className={`reveal ${visible ? "is-visible" : ""} ${className}`}
      style={delay ? { transitionDelay: `${delay}ms` } : undefined}
    >
      {children}
    </div>
  );
}
"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useId, useRef, useState } from "react";
import { formatPrice, discountPercent } from "@/lib/format";
import { ProductImage } from "@/components/product-image";

// Large search field with instant suggestions (debounced /api/search): matching
// category, the top pieces with photo + price, and "see all". Arrow keys move,
// Enter opens, Esc closes. Without JS it is a plain GET form to /search.

type Suggest = {
  total: number;
  partial: boolean;
  correction: string | null;
  category: { name: string; slug: string; count: number } | null;
  products: {
    id: string;
    name: string;
    slug: string;
    image: string | null;
    price: number;
    compareAtPrice: number | null;
    category: string;
    soldOut: boolean;
  }[];
};

const EXAMPLES = ["madera", "muebles", "silpancho", "postre", "coca-cola", "sala"];

export function BuscarBox({ initial = "", autoFocus = false }: { initial?: string; autoFocus?: boolean }) {
  const router = useRouter();
  const listId = useId();
  const [q, setQ] = useState(initial);
  const [data, setData] = useState<Suggest | null>(null);
  const [loading, setLoading] = useState(false);
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(-1);
  const [hint, setHint] = useState(0);
  const boxRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const term = q.trim();

  // Rotating example in the placeholder.
  useEffect(() => {
    const t = setInterval(() => setHint((h) => (h + 1) % EXAMPLES.length), 2600);
    return () => clearInterval(t);
  }, []);

  // Debounced suggestions.
  useEffect(() => {
    if (!term) return;
    const ctrl = new AbortController();
    const t = setTimeout(async () => {
      setLoading(true);
      try {
        const res = await fetch(`/api/search?q=${encodeURIComponent(term)}`, { signal: ctrl.signal });
        if (res.ok) {
          setData((await res.json()) as Suggest);
          setActive(-1);
        }
      } catch {
        /* aborted or offline — keep the last suggestions */
      } finally {
        if (!ctrl.signal.aborted) setLoading(false);
      }
    }, 180);
    return () => {
      clearTimeout(t);
      ctrl.abort();
    };
  }, [term]);

  // Close when clicking outside.
  useEffect(() => {
    const onDown = (e: PointerEvent) => {
      if (!boxRef.current?.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, []);

  const shown = term && data ? data : null;
  // Keyboard targets: category row (if any), each product, then "see all".
  const links: string[] = shown
    ? [
        ...(shown.category && shown.category.count > 0 ? [`/shop/${shown.category.slug}`] : []),
        ...shown.products.map((p) => `/product/${p.slug}`),
        `/search?q=${encodeURIComponent(term)}`,
      ]
    : [];
  const catOffset = shown?.category && shown.category.count > 0 ? 1 : 0;

  function go(href: string) {
    setOpen(false);
    router.push(href);
  }

  function onKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
    if (e.key === "Escape") {
      setOpen(false);
      return;
    }
    if (!links.length) return;
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setOpen(true);
      setActive((a) => (a + 1) % links.length);
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setActive((a) => (a <= 0 ? links.length - 1 : a - 1));
    } else if (e.key === "Enter" && open && active >= 0) {
      e.preventDefault();
      go(links[active]);
    }
  }

  // Keep the highlighted row visible while arrowing through a long list.
  useEffect(() => {
    if (active < 0) return;
    document.getElementById(listId)?.querySelectorAll('[role="option"]')[active]?.scrollIntoView({ block: "nearest" });
  }, [active, listId]);

  const rowCls = (i: number) =>
    `flex items-center gap-3 rounded-xl px-3 py-2.5 transition ${active === i ? "bg-accent/15 ring-1 ring-accent/40" : "hover:bg-accent/10"}`;

  return (
    <div ref={boxRef} className="relative mx-auto w-full max-w-2xl">
      <form
        action="/search"
        method="get"
        role="search"
        onSubmit={(e) => {
          e.preventDefault();
          if (term) go(`/search?q=${encodeURIComponent(term)}`);
          else inputRef.current?.focus();
        }}
        className="group relative flex items-center rounded-full border border-[var(--line-strong)] bg-surface p-1.5 pl-5 shadow-[0_18px_44px_-28px_rgba(29,58,14,0.55)] transition focus-within:border-accent focus-within:ring-4 focus-within:ring-[rgba(255,204,4,0.18)]"
      >
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" className="h-5 w-5 shrink-0 text-accent-strong" aria-hidden="true">
          <circle cx="11" cy="11" r="7" />
          <path d="m20 20-3.8-3.8" />
        </svg>
        <input
          ref={inputRef}
          name="q"
          type="search"
          value={q}
          onChange={(e) => {
            setQ(e.target.value);
            setOpen(true);
            if (!e.target.value.trim()) setData(null);
          }}
          onFocus={() => setOpen(true)}
          onKeyDown={onKeyDown}
          autoFocus={autoFocus}
          autoComplete="off"
          spellCheck={false}
          enterKeyHint="search"
          placeholder={`Prueba “${EXAMPLES[hint]}”`}
          aria-label="Buscar en el colección"
          role="combobox"
          aria-expanded={open && !!shown}
          aria-controls={listId}
          aria-autocomplete="list"
          className="min-w-0 flex-1 bg-transparent px-3 py-2.5 text-base text-ink outline-none placeholder:text-muted/60 [&::-webkit-search-cancel-button]:hidden"
        />
        {loading && <span className="mr-2 h-4 w-4 shrink-0 animate-spin rounded-full border-2 border-accent/25 border-t-accent" aria-hidden="true" />}
        {q && !loading && (
          <button
            type="button"
            onClick={() => {
              setQ("");
              setData(null);
              inputRef.current?.focus();
            }}
            aria-label="Borrar búsqueda"
            className="mr-1 flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-muted transition hover:bg-accent/10 hover:text-ink"
          >
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" className="h-4 w-4" aria-hidden="true">
              <path d="M6 6l12 12M18 6 6 18" />
            </svg>
          </button>
        )}
        <button
          type="submit"
          className="shrink-0 rounded-full bg-gradient-to-r from-accent-soft via-accent to-accent-strong px-5 py-2.5 text-sm font-semibold uppercase tracking-[0.14em] text-brand shadow-[0_10px_24px_-12px_rgba(255,204,4,0.9)] transition hover:brightness-105 sm:px-7"
        >
          Buscar
        </button>
      </form>

      {open && shown && (
        <div
          id={listId}
          role="listbox"
          className="absolute inset-x-0 top-full z-40 mt-2 overflow-hidden rounded-2xl border border-[var(--line-strong)] bg-surface text-left shadow-[0_30px_60px_-30px_rgba(29,58,14,0.7)] animate-chatin [transform-origin:top_center]"
        >
          {shown.correction && (
            <p className="border-b border-[var(--line)] px-4 py-2.5 text-xs text-muted">
              Mostrando resultados para <span className="font-semibold text-accent-strong">“{shown.correction}”</span>
            </p>
          )}

          <div className="max-h-[min(26rem,60vh)] overflow-y-auto overscroll-contain p-2 [scrollbar-width:thin]">
            {shown.category && shown.category.count > 0 && (
              <Link href={`/shop/${shown.category.slug}`} role="option" aria-selected={active === 0} onClick={() => setOpen(false)} className={rowCls(0)}>
                <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-lg bg-gradient-to-br from-accent-soft via-accent to-accent-strong text-brand">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" className="h-5 w-5" aria-hidden="true">
                    <path d="M7 5h10l4 5-9 10L3 10z" />
                    <path d="M3 10h18M10 5 8.6 10 12 20l3.4-10L14 5" />
                  </svg>
                </span>
                <span className="min-w-0 flex-1">
                  <span className="block text-sm font-semibold text-ink">Ver todo en {shown.category.name}</span>
                  <span className="block text-xs text-muted">
                    {shown.category.count} producto{shown.category.count === 1 ? "" : "s"} en el colección
                  </span>
                </span>
                <span className="text-accent-strong">→</span>
              </Link>
            )}

            {shown.category && shown.category.count === 0 && (
              <Link href={`/shop/${shown.category.slug}`} onClick={() => setOpen(false)} className="flex items-center gap-3 rounded-xl px-3 py-3 hover:bg-accent/10">
                <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-lg border border-dashed border-accent/60 text-lg text-accent-strong">✦</span>
                <span className="min-w-0 flex-1">
                  <span className="block text-sm font-semibold text-ink">{shown.category.name} llega pronto</span>
                  <span className="block text-xs text-muted">Toca para avisarte cuando llegue</span>
                </span>
              </Link>
            )}

            {shown.products.length > 0 && (
              <p className="px-3 pb-1 pt-2 text-[0.65rem] font-semibold uppercase tracking-[0.2em] text-muted">
                {shown.partial ? "Coincidencias cercanas" : "Del colección"}
              </p>
            )}
            {shown.products.map((p, i) => {
              const idx = i + catOffset;
              const off = discountPercent(p.price, p.compareAtPrice);
              return (
                <Link key={p.id} href={`/product/${p.slug}`} role="option" aria-selected={active === idx} onClick={() => setOpen(false)} className={rowCls(idx)}>
                  <span className="relative h-12 w-12 shrink-0 overflow-hidden rounded-lg border border-[var(--line)] bg-sand">
                    <ProductImage src={p.image ?? undefined} alt="" seed={p.slug} />
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-sm font-medium text-ink">{p.name}</span>
                    <span className="block text-xs text-muted">
                      {p.category}
                      {p.soldOut && <span className="ml-1.5 text-bad">· Agotado</span>}
                    </span>
                  </span>
                  <span className="shrink-0 text-right">
                    <span className={`block text-sm font-semibold ${off ? "text-brand dark:text-accent-soft" : "text-ink"}`}>{formatPrice(p.price)}</span>
                    {off && <span className="block text-[0.65rem] font-semibold uppercase tracking-wider text-accent-strong">{off}% off</span>}
                  </span>
                </Link>
              );
            })}

            {shown.total === 0 && !shown.category && (
              <div className="px-3 py-5 text-center">
                <p className="font-display text-lg text-ink">Todavía no hay nada para “{term}”</p>
                <p className="mt-1 text-xs text-muted">Escribe el nombre de un producto, una categoría o una promo.</p>
              </div>
            )}
          </div>

          {shown.total > 0 && (
            <Link
              href={`/search?q=${encodeURIComponent(term)}`}
              role="option"
              aria-selected={active === links.length - 1}
              onClick={() => setOpen(false)}
              className={`flex items-center justify-between border-t border-[var(--line)] px-5 py-3 text-xs font-semibold uppercase tracking-[0.16em] transition ${
                active === links.length - 1 ? "bg-brand text-light" : "text-brand hover:bg-accent/10 dark:text-accent-soft"
              }`}
            >
              Ver los {shown.total} resultado{shown.total === 1 ? "" : "s"}
              <span>→</span>
            </Link>
          )}
        </div>
      )}
    </div>
  );
}
"use client";

