/** Cart line total; on sale it adds the struck-through regular total and the saving. */
export function LinePrice({
  price,
  compareAt,
  quantity,
}: {
  price: number;
  compareAt?: number | null;
  quantity: number;
}) {
  const saved = savingsOf(price, compareAt);
  if (!saved || !compareAt) {
    return <span className="shrink-0 font-medium text-ink">{formatPrice(price * quantity)}</span>;
  }
  return (
    <div className="shrink-0 text-right">
      <span className="font-semibold text-brand dark:text-accent-soft">{formatPrice(price * quantity)}</span>
      <p className="text-sm text-muted line-through decoration-brand/50 dark:decoration-accent/60">
        {formatPrice(compareAt * quantity)}
      </p>
      <p className="text-[0.7rem] font-semibold uppercase tracking-[0.1em] text-accent-strong">
        Ahorras {formatPrice(saved * quantity)}
      </p>
    </div>
  );
}
"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { useMounted } from "@/lib/use-mounted";
import { createPortal } from "react-dom";

type Variant = "success" | "error" | "info";

type Toast = {
  id: string;
  message: string;
  title?: string;
  variant: Variant;
  duration: number;
};

type ToastInput = {
  message: string;
  title?: string;
  variant?: Variant;
  duration?: number;
};

type ToastOpts = Omit<ToastInput, "message" | "variant">;

type ToastApi = {
  toast: (input: ToastInput) => string;
  success: (message: string, opts?: ToastOpts) => string;
  error: (message: string, opts?: ToastOpts) => string;
  info: (message: string, opts?: ToastOpts) => string;
  dismiss: (id: string) => void;
};

const ToastContext = createContext<ToastApi | null>(null);

/** Access the toast API. Must be used within <ToastProvider> (mounted in the root layout). */
export function useToast(): ToastApi {
  const ctx = useContext(ToastContext);
  if (!ctx) throw new Error("useToast must be used within <ToastProvider>");
  return ctx;
}

const MAX_VISIBLE = 4;

export function ToastProvider({ children }: { children: React.ReactNode }) {
  const [toasts, setToasts] = useState<Toast[]>([]);
  const timers = useRef<Map<string, ReturnType<typeof setTimeout>>>(new Map());
  const mounted = useMounted();

  const dismiss = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
    const tm = timers.current.get(id);
    if (tm) {
      clearTimeout(tm);
      timers.current.delete(id);
    }
  }, []);

  const startTimer = useCallback(
    (id: string, duration: number) => {
      const tm = setTimeout(() => dismiss(id), duration);
      timers.current.set(id, tm);
    },
    [dismiss]
  );

  const push = useCallback(
    (input: ToastInput) => {
      const id =
        (globalThis.crypto?.randomUUID?.() as string | undefined) ??
        Math.random().toString(36).slice(2);
      const variant = input.variant ?? "info";
      const duration = input.duration ?? (variant === "error" ? 5000 : 4000);
      const next: Toast = { id, message: input.message, title: input.title, variant, duration };
      // keep only the most recent MAX_VISIBLE toasts
      setToasts((prev) => [...prev, next].slice(-MAX_VISIBLE));
      startTimer(id, duration);
      return id;
    },
    [startTimer]
  );

  const api = useMemo<ToastApi>(
    () => ({
      toast: push,
      success: (message, opts) => push({ ...opts, message, variant: "success" }),
      error: (message, opts) => push({ ...opts, message, variant: "error" }),
      info: (message, opts) => push({ ...opts, message, variant: "info" }),
      dismiss,
    }),
    [push, dismiss]
  );

  const pause = useCallback((id: string) => {
    const tm = timers.current.get(id);
    if (tm) {
      clearTimeout(tm);
      timers.current.delete(id);
    }
  }, []);

  const resume = useCallback(
    (id: string, duration: number) => {
      if (!timers.current.has(id)) startTimer(id, duration);
    },
    [startTimer]
  );

  // clean up any pending timers on unmount
  useEffect(() => {
    const map = timers.current;
    return () => {
      map.forEach((tm) => clearTimeout(tm));
      map.clear();
    };
  }, []);

  return (
    <ToastContext.Provider value={api}>
      {children}
      {mounted &&
        createPortal(
          <div
            className="pointer-events-none fixed inset-x-0 bottom-20 z-[9999] flex flex-col items-center gap-2.5 p-4 sm:inset-x-auto sm:bottom-24 sm:right-5 sm:items-end sm:p-0"
            aria-live="polite"
          >
            {toasts.map((t) => (
              <ToastCard
                key={t.id}
                toast={t}
                onDismiss={() => dismiss(t.id)}
                onPause={() => pause(t.id)}
                onResume={() => resume(t.id, t.duration)}
              />
            ))}
          </div>,
          document.body
        )}
    </ToastContext.Provider>
  );
}

function ToastCard({
  toast,
  onDismiss,
  onPause,
  onResume,
}: {
  toast: Toast;
  onDismiss: () => void;
  onPause: () => void;
  onResume: () => void;
}) {
  const { variant } = toast;
  const accent =
    variant === "success"
      ? "text-emerald-600 dark:text-emerald-400"
      : variant === "error"
        ? "text-red-600 dark:text-red-400"
        : "text-accent-strong";
  const border =
    variant === "success"
      ? "border-emerald-500/35"
      : variant === "error"
        ? "border-red-500/35"
        : "border-accent/45";

  return (
    <div
      role={variant === "error" ? "alert" : "status"}
      onMouseEnter={onPause}
      onMouseLeave={onResume}
      className={`pointer-events-auto flex w-[21rem] max-w-[calc(100vw-2rem)] items-start gap-3 rounded-xl border ${border} bg-surface p-4 text-ink shadow-[0_24px_60px_-20px_rgba(29,58,14,0.5)] animate-[toastin_.35s_cubic-bezier(.2,.8,.2,1)]`}
    >
      <span className={`mt-0.5 shrink-0 ${accent}`}>
        <VariantIcon variant={variant} />
      </span>
      <div className="min-w-0 flex-1">
        {toast.title && <p className="text-sm font-semibold leading-snug">{toast.title}</p>}
        <p className={`text-sm leading-snug ${toast.title ? "mt-0.5 text-muted" : "font-medium"}`}>
          {toast.message}
        </p>
      </div>
      <button
        onClick={onDismiss}
        aria-label="Cerrar notificación"
        className="-mr-1 -mt-1 shrink-0 rounded-md p-1 text-muted transition hover:bg-cream-soft hover:text-ink"
      >
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
          <path d="M6 6l12 12M18 6L6 18" strokeLinecap="round" />
        </svg>
      </button>
    </div>
  );
}

function VariantIcon({ variant }: { variant: Variant }) {
  if (variant === "success") {
    return (
      <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <circle cx="12" cy="12" r="9" />
        <path d="M8.5 12.5l2.5 2.5 4.5-5" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    );
  }
  if (variant === "error") {
    return (
      <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <circle cx="12" cy="12" r="9" />
        <path d="M12 7.5v5M12 16h.01" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    );
  }
  return (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
      <circle cx="12" cy="12" r="9" />
      <path d="M12 11v5M12 8h.01" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}
"use client";

import { useRef, useState } from "react";
import { ProductImage } from "./product-image";

// Hover-to-zoom for the product stage. The packshot sits on a white seamless
// background, so `mix-blend-multiply` dissolves the photo's own white box into
// the stage — no visible edge. On touch devices it stays a normal image so the
// browser's pinch-zoom still works.
export function ZoomImage({
  src,
  alt,
  seed,
  zoom = 2.1,
  priority = false,
}: {
  src?: string;
  alt: string;
  seed: string;
  zoom?: number;
  priority?: boolean;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const [active, setActive] = useState(false);
  const [origin, setOrigin] = useState("50% 50%");

  if (!src) {
    return <ProductImage src={src} alt={alt} seed={seed} fit="contain" />;
  }

  function handleMove(e: React.MouseEvent<HTMLDivElement>) {
    const el = ref.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;
    setOrigin(`${x}% ${y}%`);
  }

  return (
    <div
      ref={ref}
      onMouseEnter={() => setActive(true)}
      onMouseLeave={() => setActive(false)}
      onMouseMove={handleMove}
      className="group/zoom relative h-full w-full cursor-zoom-in overflow-hidden"
    >
      <img
        src={src}
        alt={alt}
        draggable={false}
        loading={priority ? "eager" : "lazy"}
        decoding="async"
        className="h-full w-full select-none object-contain mix-blend-multiply transition-transform duration-300 ease-out"
        style={{ transform: active ? `scale(${zoom})` : "scale(1)", transformOrigin: origin }}
      />
      <span className="pointer-events-none absolute bottom-4 right-4 hidden items-center gap-1.5 rounded-full border border-[rgba(28,43,32,0.12)] bg-white/80 px-3 py-1.5 text-[0.68rem] font-medium text-ink/70 backdrop-blur-sm transition-opacity duration-200 group-hover/zoom:opacity-0 md:flex">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
          <circle cx="11" cy="11" r="7" />
          <path d="M21 21l-4.3-4.3M11 8v6M8 11h6" strokeLinecap="round" />
        </svg>
        Acerca para ampliar
      </span>
    </div>
  );
}
"use server";

import { lookupOrder, type OrderLookupResult } from "@/lib/order-lookup";
import { courierLabel, trackingUrl } from "@/lib/couriers";
import { clientIp, rateLimit, TOO_MANY } from "@/lib/rate-limit";

export type LookupState = (
  | { status: "idle" }
  | { status: "error"; message: string }
  | {
      status: "found";
      order: Extract<OrderLookupResult, { ok: true }>["order"] & {
        courierName: string | null;
        trackUrl: string | null;
      };
    }
) & { values?: { order: string; email: string } };

// Order tracking runs as a POST server action so the shopper's email never
// ends up in the URL / browser history / server logs.
export async function lookupOrderAction(prev: LookupState, formData: FormData): Promise<LookupState> {
  // Keep the typed order number + email visible after submit (React 19 resets the form).
  const values = { order: String(formData.get("order") ?? ""), email: String(formData.get("email") ?? "") };
  return { ...(await lookup(prev, formData)), values };
}

async function lookup(_prev: LookupState, formData: FormData): Promise<LookupState> {
  const orderNumber = String(formData.get("order") ?? "").trim().toUpperCase();
  const email = String(formData.get("email") ?? "").trim();
  if (!orderNumber || !email) {
    return { status: "error", message: "Ingresa tu número de pedido y tu correo." };
  }
  if (!rateLimit(`track:${await clientIp()}`, 20, 10 * 60_000)) {
    return { status: "error", message: TOO_MANY };
  }

  const result = await lookupOrder(orderNumber, email);
  if (!result.ok) {
    return {
      status: "error",
      message:
        result.reason === "db-down"
          ? "El rastreo de pedidos no está disponible ahora. Intenta más tarde o contáctanos."
          : "No se encontró un pedido con ese número y correo. Verifica e intenta de nuevo.",
    };
  }
  const { courier, trackingNumber } = result.order;
  return {
    status: "found",
    order: {
      ...result.order,
      courierName: courier ? courierLabel(courier) : null,
      trackUrl: courier && trackingNumber ? trackingUrl(courier, trackingNumber) : null,
    },
  };
}
"use server";

import { createHash } from "node:crypto";
import { redirect } from "next/navigation";
import { prisma } from "@/lib/prisma";
import { hashPassword, verifyPassword } from "@/lib/password";
import { emailError, nameError, newPasswordError } from "@/lib/auth-rules";
import { startCustomerSession, endCustomerSession, safeNext } from "@/lib/customer-auth";
import { clientIp, rateLimit, TOO_MANY } from "@/lib/rate-limit";
import { createToken, readToken } from "@/lib/session-token";
import { sendPasswordResetEmail } from "@/lib/email";
import { logDbError } from "@/lib/db-errors";
import { siteUrl } from "@/lib/site";
import { requireCustomer } from "@/lib/customer-auth";
import { issueCode, verifyCode, setPending, getPending, clearPending, RESEND_COOLDOWN_S } from "@/lib/otp";

export type AuthState = {
  error?: string;
  /** Inputs to mark as wrong (red) next to the error, e.g. ["email", "password"]. */
  fields?: string[];
  ok?: boolean;
  message?: string;
  values?: Record<string, string>;
};

// React 19 resets a form after its server action runs, so on an error the
// shopper would have to retype everything. Echo the (non-secret) fields back;
// the inputs use them as defaultValue.
function keep(formData: FormData, keys: string[]): Record<string, string> {
  return Object.fromEntries(keys.map((k) => [k, String(formData.get(k) ?? "")]));
}


// First failing field (same rules the form shows live — lib/auth-rules.ts).
function firstFieldError(checks: [string, string | null][]): AuthState | null {
  const bad = checks.find(([, err]) => err);
  return bad ? { error: bad[1]!, fields: [bad[0]] } : null;
}

const MINUTE = 60_000;

export async function registerAction(prev: AuthState, formData: FormData): Promise<AuthState> {
  return { ...(await register(prev, formData)), values: keep(formData, ["name", "email"]) };
}

// Step 1 of sign-up: validate, then email a 6-digit code. The account is only
// created once the code is confirmed (step 2, verifyRegistrationAction), so
// nobody can register an email address they don't own.
async function register(_prev: AuthState, formData: FormData): Promise<AuthState> {
  if (!rateLimit(`register:${await clientIp()}`, 8, 60 * MINUTE)) return { error: TOO_MANY };

  const name = String(formData.get("name") ?? "").trim();
  const email = String(formData.get("email") ?? "").trim();
  const password = String(formData.get("password") ?? "");
  const invalid = firstFieldError([
    ["name", nameError(name)],
    ["email", emailError(email)],
    ["password", newPasswordError(password)],
  ]);
  if (invalid) return invalid;

  const e = email.toLowerCase();
  const payload = { name, passwordHash: hashPassword(password), next: safeNext(formData.get("next")) };

  try {
    if (await prisma.customer.findUnique({ where: { email: e }, select: { id: true } })) {
      return {
        error: "Ya existe una cuenta con este correo. Inicia sesión o restablece tu contraseña.",
        fields: ["email"],
      };
    }
    const sent = await issueCode(e, "register", payload);
    if (!sent.ok) {
      if (!sent.retryAfter) return { error: sent.error };
      // A code was sent moments ago — keep it, but use the latest name/password.
      await prisma.emailVerification.update({
        where: { email_purpose: { email: e, purpose: "register" } },
        data: { payload },
      });
    }
  } catch (err) {
    const kind = logDbError("register", err);
    if (kind === "unavailable" || kind === "not-migrated" || kind === "engine") {
      return { error: "Servicio no disponible. Inténtalo de nuevo en un momento." };
    }
    return { error: "No pudimos iniciar el registro. Inténtalo de nuevo." };
  }

  await setPending(e, "register");
  redirect("/register/verify");
}

export type OtpState = { ok?: boolean; error?: string; message?: string; retryAfter?: number };

const CODE_MSG = { expired: "Tu registro expiró. Vuelve a empezar." };

// Step 2 of sign-up: confirm the code, then create the (verified) account.
export async function verifyRegistrationAction(_prev: OtpState, formData: FormData): Promise<OtpState> {
  if (!rateLimit(`otp:${await clientIp()}`, 25, 10 * MINUTE)) return { error: TOO_MANY };
  const pending = await getPending("register");
  if (!pending) return { error: CODE_MSG.expired };

  let created;
  try {
    const r = await verifyCode(pending.email, "register", String(formData.get("code") ?? ""));
    if (!r.ok) return { error: r.error };
    const data = (r.payload ?? {}) as { name?: string; passwordHash?: string; next?: string };
    if (!data.name || !data.passwordHash) return { error: CODE_MSG.expired };
    created = await prisma.customer.create({
      data: { name: data.name, email: pending.email, passwordHash: data.passwordHash, emailVerifiedAt: new Date() },
    });
    await clearPending();
    await startCustomerSession({ id: created.id, email: created.email, name: created.name });
    redirect(withFlash(safeNext(data.next), "register"));
  } catch (err) {
    if (isRedirect(err)) throw err;
    const kind = logDbError("register-verify", err);
    if (kind === "duplicate") return { error: "Ya existe una cuenta con este correo. Inicia sesión." };
    return { error: "Servicio no disponible. Inténtalo de nuevo en un momento." };
  }
}

export async function resendRegistrationCode(): Promise<OtpState> {
  if (!rateLimit(`otp-resend:${await clientIp()}`, 10, 60 * MINUTE)) return { error: TOO_MANY };
  const pending = await getPending("register");
  if (!pending) return { error: CODE_MSG.expired };
  try {
    const r = await issueCode(pending.email, "register");
    if (!r.ok) return { error: r.error, retryAfter: r.retryAfter };
  } catch (err) {
    logDbError("register-resend", err);
    return { error: "Servicio no disponible. Inténtalo de nuevo en un momento." };
  }
  return { ok: true, message: "Te enviamos un nuevo código.", retryAfter: RESEND_COOLDOWN_S };
}

// ---------- Existing customers: verify email (accounts made before OTP / at checkout) ----------

export async function startEmailVerification(): Promise<void> {
  const session = await requireCustomer("/account");
  const customer = await prisma.customer.findUnique({
    where: { id: session.id },
    select: { email: true, emailVerifiedAt: true },
  });
  if (!customer) {
    // Account was removed but the browser still holds its session cookie.
    await endCustomerSession();
    redirect("/login");
  }
  if (customer.emailVerifiedAt) redirect("/account");
  const r = await issueCode(customer.email, "verify");
  if (!r.ok && !r.retryAfter) redirect("/account?flash=verify-send-failed");
  await setPending(customer.email, "verify");
  redirect("/account/verify-email");
}

export async function verifyEmailAction(_prev: OtpState, formData: FormData): Promise<OtpState> {
  if (!rateLimit(`otp:${await clientIp()}`, 25, 10 * MINUTE)) return { error: TOO_MANY };
  const session = await requireCustomer("/account");
  const pending = await getPending("verify");
  if (!pending || pending.email !== session.email.toLowerCase())
    return { error: "La verificación expiró. Vuelve a empezar desde tu cuenta." };
  try {
    const r = await verifyCode(pending.email, "verify", String(formData.get("code") ?? ""));
    if (!r.ok) return { error: r.error };
    await prisma.customer.update({ where: { id: session.id }, data: { emailVerifiedAt: new Date() } });
    await clearPending();
    redirect("/account?flash=email-verified");
  } catch (err) {
    if (isRedirect(err)) throw err;
    logDbError("verify-email", err);
    return { error: "Servicio no disponible. Inténtalo de nuevo en un momento." };
  }
}

export async function resendEmailVerification(): Promise<OtpState> {
  if (!rateLimit(`otp-resend:${await clientIp()}`, 10, 60 * MINUTE)) return { error: TOO_MANY };
  const session = await requireCustomer("/account");
  const pending = await getPending("verify");
  if (!pending || pending.email !== session.email.toLowerCase())
    return { error: "La verificación expiró. Vuelve a empezar desde tu cuenta." };
  try {
    const r = await issueCode(pending.email, "verify");
    if (!r.ok) return { error: r.error, retryAfter: r.retryAfter };
  } catch (err) {
    logDbError("verify-resend", err);
    return { error: "Servicio no disponible. Inténtalo de nuevo en un momento." };
  }
  return { ok: true, message: "Te enviamos un nuevo código.", retryAfter: RESEND_COOLDOWN_S };
}

// next/navigation's redirect() works by throwing — let it through our catch blocks.
function isRedirect(err: unknown): boolean {
  const digest = (err as { digest?: unknown } | null)?.digest;
  return typeof digest === "string" && digest.startsWith("NEXT_REDIRECT");
}

export async function loginAction(prev: AuthState, formData: FormData): Promise<AuthState> {
  return { ...(await login(prev, formData)), values: keep(formData, ["email"]) };
}

async function login(_prev: AuthState, formData: FormData): Promise<AuthState> {
  const email = String(formData.get("email") ?? "").trim().toLowerCase();
  const password = String(formData.get("password") ?? "");
  if (!email || !password) {
    return { error: "Ingresa tu correo y contraseña.", fields: [!email ? "email" : "password"] };
  }
  if (emailError(email)) return { error: emailError(email)!, fields: ["email"] };

  const ip = await clientIp();
  if (!rateLimit(`login:${ip}`, 20, 15 * MINUTE) || !rateLimit(`login:${email}`, 8, 15 * MINUTE)) {
    return { error: TOO_MANY };
  }

  let customer;
  try {
    customer = await prisma.customer.findUnique({ where: { email } });
  } catch (err) {
    logDbError("login", err);
    return { error: "Servicio no disponible. Inténtalo de nuevo en un momento." };
  }

  if (!customer || !verifyPassword(password, customer.passwordHash)) {
    // Don't reveal which one was wrong — mark both.
    return { error: "Correo o contraseña incorrectos. Inténtalo de nuevo.", fields: ["email", "password"] };
  }

  await startCustomerSession({ id: customer.id, email: customer.email, name: customer.name });
  redirect(withFlash(safeNext(formData.get("next")), "login"));
}

export async function logoutAction(): Promise<void> {
  await endCustomerSession();
  redirect("/?flash=signed-out");
}

// ---------- Password reset ----------
// Stateless signed link (1 hour). It embeds a fingerprint of the current
// password hash, so it stops working as soon as the password is changed —
// i.e. each link is single-use.

const RESET_TTL_SECONDS = 60 * 60;
type ResetToken = { id: string; v: string; exp: number };

function fingerprint(passwordHash: string): string {
  return createHash("sha256").update(passwordHash).digest("base64url").slice(0, 16);
}

export async function requestPasswordResetAction(prev: AuthState, formData: FormData): Promise<AuthState> {
  return { ...(await requestReset(prev, formData)), values: keep(formData, ["email"]) };
}

async function requestReset(_prev: AuthState, formData: FormData): Promise<AuthState> {
  const email = String(formData.get("email") ?? "").trim().toLowerCase();
  if (emailError(email)) return { error: emailError(email)!, fields: ["email"] };
  if (!rateLimit(`reset:${await clientIp()}`, 5, 30 * MINUTE) || !rateLimit(`reset:${email}`, 3, 30 * MINUTE)) {
    return { error: TOO_MANY };
  }

  // Same answer whether or not the account exists (no account enumeration).
  const done: AuthState = {
    ok: true,
    message: "Si existe una cuenta con ese correo, te enviamos un enlace para restablecer tu contraseña.",
  };

  try {
    const customer = await prisma.customer.findUnique({ where: { email } });
    if (!customer) return done;
    const token = createToken<ResetToken>("reset", {
      id: customer.id,
      v: fingerprint(customer.passwordHash),
      exp: Math.floor(Date.now() / 1000) + RESET_TTL_SECONDS,
    });
    await sendPasswordResetEmail({
      to: customer.email,
      name: customer.name,
      url: `${siteUrl}/reset-password?token=${encodeURIComponent(token)}`,
    });
  } catch (err) {
    console.error("[auth] password reset request failed:", err);
  }
  return done;
}

export async function resetPasswordAction(_prev: AuthState, formData: FormData): Promise<AuthState> {
  if (!rateLimit(`reset-submit:${await clientIp()}`, 10, 30 * MINUTE)) return { error: TOO_MANY };

  const token = String(formData.get("token") ?? "");
  const password = String(formData.get("password") ?? "");
  const weak = newPasswordError(password);
  if (weak) return { error: weak, fields: ["password"] };

  const data = readToken<ResetToken>("reset", token);
  const invalid = { error: "Este enlace no es válido o expiró. Solicita uno nuevo." };
  if (!data) return invalid;

  let customer;
  try {
    customer = await prisma.customer.findUnique({ where: { id: data.id } });
    if (!customer || fingerprint(customer.passwordHash) !== data.v) return invalid;
    customer = await prisma.customer.update({
      where: { id: customer.id },
      data: { passwordHash: hashPassword(password) },
    });
  } catch {
    return { error: "Servicio no disponible. Inténtalo de nuevo en un momento." };
  }

  await startCustomerSession({ id: customer.id, email: customer.email, name: customer.name });
  redirect("/account?flash=password-reset");
}

function withFlash(path: string, flash: string): string {
  return `${path}${path.includes("?") ? "&" : "?"}flash=${flash}`;
}
"use server";

import { after } from "next/server";
import { prisma } from "@/lib/prisma";
import { clientIp, rateLimit, TOO_MANY } from "@/lib/rate-limit";
import { sendContactNotification } from "@/lib/email";
import { randomBytes } from "node:crypto";
import {
  MAX_REFERENCE_PHOTOS,
  MAX_REFERENCE_BYTES,
  REFERENCE_PHOTOS_HEADING,
} from "@/lib/custom-request";
import { saveUpload, sniffImage, type ImageExt } from "@/lib/uploads";
import { emailError, normalizePhone } from "@/lib/auth-rules";
import { CONTACT_VALIDATORS, CUSTOM_VALIDATORS, checkFields } from "@/lib/inbound-rules";

export type InboundState = {
  ok?: boolean;
  error?: string;
  /** Fields the server rejected (the form marks them red). */
  fields?: string[];
  values?: Record<string, string>;
};

const CONTACT_FIELDS = Object.keys(CONTACT_VALIDATORS);

/** Trimmed text of each field (missing → ""). */
const readFields = (formData: FormData, keys: string[]) =>
  Object.fromEntries(keys.map((k) => [k, String(formData.get(k) ?? "")])) as Record<string, string>;

// Contact form → saved for the admin (Messages page) + best-effort email alert.
export async function sendContactMessage(_prev: InboundState, formData: FormData): Promise<InboundState> {
  const values = readFields(formData, CONTACT_FIELDS);
  // Honeypot: real users never fill this hidden field.
  if (String(formData.get("website") ?? "")) return { ok: true };
  if (!rateLimit(`contact:${await clientIp()}`, 5, 30 * 60_000)) return { error: TOO_MANY, values };

  // The same rules the form checks live — enforced here for anyone skipping the browser.
  const bad = checkFields(CONTACT_VALIDATORS, values);
  if (bad) return { ...bad, values };
  const d = {
    name: values.name.trim(),
    email: values.email.trim(),
    phone: values.phone.trim() ? normalizePhone(values.phone) : undefined,
    subject: values.subject.trim() || undefined,
    message: values.message.trim(),
    topic: String(formData.get("topic") ?? "").trim().slice(0, 80) || undefined,
  };

  try {
    await prisma.contactMessage.create({
      data: {
        name: d.name,
        email: d.email.toLowerCase(),
        phone: d.phone || null,
        subject: d.subject || null,
        message: d.message,
        topic: d.topic || null,
      },
    });
  } catch (err) {
    console.error("[contact] could not save message:", err);
    return { error: "We couldn't send your message right now. Please try again shortly.", values };
  }

  // The owner alert goes out after the reply, so the visitor isn't kept waiting on SMTP.
  after(() => sendContactNotification(d));
  return { ok: true };
}

// ---------- Custom design request (Custom page) ----------
// Saved as a ContactMessage with topic "custom" so it shows in Admin → Messages.

const CUSTOM_FIELDS = Object.keys(CUSTOM_VALIDATORS);

export async function sendCustomRequest(_prev: InboundState, formData: FormData): Promise<InboundState> {
  const values = readFields(formData, CUSTOM_FIELDS);
  if (String(formData.get("website") ?? "")) return { ok: true }; // honeypot
  if (!rateLimit(`custom:${await clientIp()}`, 5, 30 * 60_000)) return { error: TOO_MANY, values };

  // The same rules the form checks live — enforced here for anyone skipping the browser.
  const bad = checkFields(CUSTOM_VALIDATORS, values);
  if (bad) return { ...bad, values };
  const d = Object.fromEntries(CUSTOM_FIELDS.map((k) => [k, values[k].trim()]));
  d.phone = normalizePhone(d.phone);

  // Optional reference photos: real type from the bytes, never the client's word.
  const files = formData.getAll("photos").filter((f): f is File => f instanceof File && f.size > 0);
  if (files.length > MAX_REFERENCE_PHOTOS) {
    return { error: `Please attach up to ${MAX_REFERENCE_PHOTOS} photos.`, values };
  }
  const images: { bytes: Buffer; ext: ImageExt }[] = [];
  for (const file of files) {
    if (file.size > MAX_REFERENCE_BYTES) return { error: "Each photo must be under 3 MB.", values };
    const bytes = Buffer.from(await file.arrayBuffer());
    const ext = sniffImage(bytes);
    if (!ext) return { error: "Photos must be JPG, PNG, WEBP or AVIF images.", values };
    images.push({ bytes, ext });
  }
  const photoUrls: string[] = [];
  try {
    for (const img of images) {
      const filename = `ref-${randomBytes(6).toString("hex")}-${Date.now()}.${img.ext}`;
      photoUrls.push(await saveUpload(filename, img.bytes, img.ext, "references"));
    }
  } catch (err) {
    console.error("[custom] could not save reference photos:", err);
    return { error: "We couldn't upload your photos right now. Please try again, or send them on WhatsApp.", values };
  }

  const subject = `Pedido para evento: ${d.pieceType}`;
  const message = [
    `Tipo: ${d.pieceType}`,
    `Formato: ${d.finish}`,
    `Presupuesto: ${d.budget}`,
    `Para cuándo: ${d.neededBy || "Flexible"}`,
    "",
    d.details,
    ...(photoUrls.length ? ["", REFERENCE_PHOTOS_HEADING, ...photoUrls] : []),
  ].join("\n");

  try {
    await prisma.contactMessage.create({
      data: { name: d.name, email: d.email.toLowerCase(), phone: d.phone, subject, message, topic: "custom" },
    });
  } catch (err) {
    console.error("[custom] could not save request:", err);
    return { error: "We couldn't send your request right now. Please try again shortly.", values };
  }

  after(() => sendContactNotification({ name: d.name, email: d.email, phone: d.phone, subject, message, topic: "custom" }));
  return { ok: true };
}

// Newsletter / "notify me" sign-up. Idempotent per email.
export async function subscribe(_prev: InboundState, formData: FormData): Promise<InboundState> {
  if (String(formData.get("website") ?? "")) return { ok: true };
  if (!rateLimit(`subscribe:${await clientIp()}`, 10, 30 * 60_000)) return { error: TOO_MANY };

  const email = String(formData.get("email") ?? "").trim().toLowerCase();
  const emailProblem = emailError(email);
  if (emailProblem) {
    return { error: emailProblem };
  }
  const source = String(formData.get("source") ?? "newsletter").slice(0, 80) || "newsletter";

  try {
    await prisma.subscriber.upsert({
      where: { email },
      create: { email, source },
      update: {},
    });
  } catch (err) {
    console.error("[newsletter] could not save subscriber:", err);
    return { error: "We couldn't sign you up right now. Please try again shortly." };
  }
  return { ok: true };
}
"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { unstable_rethrow } from "next/navigation";
import { z } from "zod";
import { prisma } from "@/lib/prisma";
import { requireOwner } from "@/lib/admin";
import { slugify } from "@/lib/slug";
import { refreshStorefront } from "@/lib/cache-tags";
import { dbErrorKind } from "@/lib/db-errors";

export type BranchState = {
  ok?: boolean;
  error?: string;
  values?: Record<string, string | boolean>;
};

const optionalMoney = z.preprocess(
  (v) => (v === "" || v == null ? null : Number(v)),
  z
    .number()
    .min(0, "El monto no puede ser negativo")
    .max(10_000_000, "El monto es demasiado alto")
    .nullable()
);

const optionalUrl = z
  .string()
  .trim()
  .max(500)
  .refine(
    (v) => v === "" || /^https:\/\/[^\s]+$/i.test(v) || v.startsWith("/"),
    "Usa un enlace https:// o una ruta que empiece por /"
  );

const optionalLatitude = z.preprocess(
  (v) => (v === "" || v == null ? null : Number(v)),
  z
    .number()
    .min(-90, "La latitud debe estar entre -90 y 90")
    .max(90, "La latitud debe estar entre -90 y 90")
    .nullable()
);

const optionalLongitude = z.preprocess(
  (v) => (v === "" || v == null ? null : Number(v)),
  z
    .number()
    .min(-180, "La longitud debe estar entre -180 y 180")
    .max(180, "La longitud debe estar entre -180 y 180")
    .nullable()
);

const schema = z
  .object({
    name: z.string().trim().min(2, "Ingresa el nombre de la sucursal").max(120),
    code: z
      .string()
      .trim()
      .regex(/^[A-Za-z0-9]{2,8}$/, "El código debe tener de 2 a 8 letras o números (p. ej. CC01)")
      .transform((v) => v.toUpperCase()),
    slug: z.string().trim().max(120),
    address: z.string().trim().min(3, "Ingresa la dirección").max(200),
    city: z.string().trim().min(2, "Ingresa la ciudad").max(120),
    phone: z.string().trim().max(30),
    whatsapp: z
      .string()
      .transform((v) => v.replace(/[^0-9]/g, ""))
      .refine((v) => v === "" || (v.length >= 10 && v.length <= 15), "WhatsApp: formato internacional, p. ej. 59170000000"),
    hours: z.string().trim().max(120),
    image: optionalUrl,
    mapsUrl: optionalUrl,
    latitude: optionalLatitude,
    longitude: optionalLongitude,
    flatFee: optionalMoney,
    freeThreshold: optionalMoney,
    sortOrder: z.coerce.number().int().min(0).max(999),
    deliveryEnabled: z.boolean(),
    pickupEnabled: z.boolean(),
    active: z.boolean(),
  })
  .refine((d) => d.deliveryEnabled || d.pickupEnabled, {
    message: "Activa entrega a domicilio, retiro en tienda o ambos.",
    path: ["deliveryEnabled"],
  })
  .refine((d) => d.flatFee == null || d.freeThreshold == null || d.freeThreshold >= d.flatFee, {
    message: "El envío gratis debe ser mayor o igual al costo de envío (o usa 0 para gratis siempre).",
    path: ["freeThreshold"],
  });

function read(fd: FormData) {
  return {
    name: String(fd.get("name") ?? ""),
    code: String(fd.get("code") ?? ""),
    slug: String(fd.get("slug") ?? ""),
    address: String(fd.get("address") ?? ""),
    city: String(fd.get("city") ?? ""),
    phone: String(fd.get("phone") ?? ""),
    whatsapp: String(fd.get("whatsapp") ?? ""),
    hours: String(fd.get("hours") ?? ""),
    image: String(fd.get("image") ?? ""),
    mapsUrl: String(fd.get("mapsUrl") ?? ""),
    latitude: String(fd.get("latitude") ?? ""),
    longitude: String(fd.get("longitude") ?? ""),
    flatFee: String(fd.get("flatFee") ?? ""),
    freeThreshold: String(fd.get("freeThreshold") ?? ""),
    sortOrder: String(fd.get("sortOrder") ?? "0"),
    deliveryEnabled: fd.get("deliveryEnabled") === "on",
    pickupEnabled: fd.get("pickupEnabled") === "on",
    active: fd.get("active") === "on",
  };
}

function data(d: z.infer<typeof schema>) {
  return {
    name: d.name,
    code: d.code,
    slug: d.slug ? slugify(d.slug) : slugify(d.name),
    address: d.address,
    city: d.city,
    phone: d.phone || null,
    whatsapp: d.whatsapp || null,
    hours: d.hours || null,
    image: d.image || null,
    mapsUrl: d.mapsUrl || null,
    latitude: d.latitude,
    longitude: d.longitude,
    flatFee: d.flatFee,
    freeThreshold: d.freeThreshold,
    sortOrder: d.sortOrder,
    deliveryEnabled: d.deliveryEnabled,
    pickupEnabled: d.pickupEnabled,
    active: d.active,
  };
}

export async function createBranch(_prev: BranchState, fd: FormData): Promise<BranchState> {
  const values = read(fd);
  try {
    await requireOwner();
  } catch (e) {
    unstable_rethrow(e);
    return { error: (e as Error).message, values };
  }
  const parsed = schema.safeParse(values);
  if (!parsed.success) return { error: parsed.error.issues[0]?.message, values };
  if (!slugify(parsed.data.slug || parsed.data.name)) return { error: "Ingresa un nombre válido.", values };

  try {
    await prisma.branch.create({ data: data(parsed.data) });
  } catch (err) {
    if (dbErrorKind(err) === "duplicate") return { error: "Ya existe una sucursal con ese código o slug.", values };
    return { error: "No se pudo crear la sucursal.", values };
  }
  refreshStorefront();
  revalidatePath("/admin/branches");
  revalidatePath("/admin/inventory");
  return { ok: true };
}

export async function updateBranch(id: string, _prev: BranchState, fd: FormData): Promise<BranchState> {
  const values = read(fd);
  try {
    await requireOwner();
  } catch (e) {
    unstable_rethrow(e);
    return { error: (e as Error).message, values };
  }
  const parsed = schema.safeParse(values);
  if (!parsed.success) return { error: parsed.error.issues[0]?.message, values };
  if (!slugify(parsed.data.slug || parsed.data.name)) return { error: "Ingresa un nombre válido.", values };

  try {
    await prisma.branch.update({ where: { id }, data: data(parsed.data) });
  } catch (err) {
    if (dbErrorKind(err) === "duplicate") return { error: "Ya existe otra sucursal con ese código o slug.", values };
    return { error: "No se pudo guardar la sucursal.", values };
  }
  refreshStorefront();
  revalidatePath("/admin/branches");
  revalidatePath(`/admin/branches/${id}`);
  revalidatePath("/admin/inventory");
  return { ok: true };
}

export async function toggleBranchActive(id: string, formData: FormData): Promise<void> {
  await requireOwner();
  const active = formData.get("active") === "1";
  await prisma.branch.update({ where: { id }, data: { active } });
  refreshStorefront();
  revalidatePath("/admin/branches");
  revalidatePath("/admin/inventory");
}

export async function deleteBranch(id: string): Promise<void> {
  await requireOwner();
  let flash = "branch-deleted";
  try {
    const branch = await prisma.branch.findUnique({
      where: { id },
      select: { _count: { select: { orders: true, users: true } } },
    });
    if (!branch) flash = "branch-missing";
    else if (branch._count.orders > 0 || branch._count.users > 0) flash = "branch-in-use";
    else await prisma.branch.delete({ where: { id } });
  } catch (err) {
    flash = dbErrorKind(err) === "in-use" ? "branch-in-use" : "branch-delete-failed";
  }
  refreshStorefront();
  revalidatePath("/admin/branches");
  redirect(`/admin/branches?flash=${flash}`);
}
"use server";

import { redirect } from "next/navigation";
import { z } from "zod";
import { prisma } from "@/lib/prisma";
import { requireAdmin } from "@/lib/admin";
import { slugify } from "@/lib/slug";
import { refreshStorefront } from "@/lib/cache-tags";
import { dbErrorKind } from "@/lib/db-errors";

export type CategoryState = { error?: string; ok?: boolean };

const schema = z.object({
  name: z.string().min(2, "Ingresa un nombre de categoría"),
  slug: z.string().optional(),
  description: z.string().optional(),
});

export async function createCategory(
  _prev: CategoryState,
  formData: FormData
): Promise<CategoryState> {
  await requireAdmin();
  const parsed = schema.safeParse({
    name: formData.get("name"),
    slug: formData.get("slug"),
    description: formData.get("description"),
  });
  if (!parsed.success) return { error: parsed.error.issues[0]?.message };

  const { name, slug, description } = parsed.data;
  try {
    await prisma.category.create({
      data: {
        name: name.trim(),
        slug: slug ? slugify(slug) : slugify(name),
        description: description?.trim() || null,
      },
    });
  } catch (err) {
    const kind = dbErrorKind(err);
    if (kind === "duplicate") return { error: "Ya existe una categoría con ese nombre o slug." };
    if (kind === "unavailable")
      return { error: "Base de datos no disponible. Inténtalo de nuevo." };
    return { error: "No se pudo crear la categoría." };
  }
  refreshStorefront();
  return { ok: true };
}

export async function deleteCategory(id: string): Promise<void> {
  await requireAdmin();
  let flash = "category-deleted";
  try {
    await prisma.category.delete({ where: { id } });
  } catch (err) {
    flash = dbErrorKind(err) === "in-use" ? "category-in-use" : "delete-failed";
  }
  refreshStorefront();
  redirect(`/admin/categories?flash=${flash}`);
}
"use server";

import { revalidatePath } from "next/cache";
import { prisma } from "@/lib/prisma";
import { requireAdmin, canAccessBranch } from "@/lib/admin";
import { refreshCatalog } from "@/lib/cache-tags";

const MAX_STOCK = 1_000_000;

export async function setBranchStock(formData: FormData): Promise<void> {
  const session = await requireAdmin();
  const productId = String(formData.get("productId") ?? "");
  const branchId = String(formData.get("branchId") ?? "");
  const raw = Number(formData.get("stock"));
  if (!productId || !branchId || !canAccessBranch(session, branchId)) return;
  const stock = Number.isFinite(raw) ? Math.min(MAX_STOCK, Math.max(0, Math.floor(raw))) : 0;

  try {
    await prisma.branchStock.upsert({
      where: { branchId_productId: { branchId, productId } },
      create: { branchId, productId, stock },
      update: { stock },
    });
  } catch (err) {
    console.error("[inventory] could not save stock:", err);
    return;
  }
  refreshCatalog();
  revalidatePath("/admin/inventory");
}

/** Hide/show a product for one branch without touching the shared catalog. */
export async function setBranchProductActive(formData: FormData): Promise<void> {
  const session = await requireAdmin();
  const productId = String(formData.get("productId") ?? "");
  const branchId = String(formData.get("branchId") ?? "");
  const active = formData.get("active") === "1";
  if (!productId || !branchId || !canAccessBranch(session, branchId)) return;

  try {
    await prisma.branchStock.upsert({
      where: { branchId_productId: { branchId, productId } },
      create: { branchId, productId, stock: 0, active },
      update: { active },
    });
  } catch (err) {
    console.error("[inventory] could not change availability:", err);
    return;
  }
  refreshCatalog();
  revalidatePath("/admin/inventory");
}
"use server";

import { revalidatePath } from "next/cache";
import { unstable_rethrow } from "next/navigation";
import { z } from "zod";
import { prisma } from "@/lib/prisma";
import { requireAdmin } from "@/lib/admin";
import { saveStoreSettings } from "@/lib/settings";
import { slugify } from "@/lib/slug";
import { adjustBalance } from "@/lib/loyalty";
import type { LoyaltySettings } from "@/lib/settings-shared";
import type { RedemptionStatus } from "@prisma/client";

export type LoyaltyState = { ok?: boolean; error?: string; values?: Record<string, string> };

// Rules and prize catalogue are owner-only; the redemption counter is a daily
// task, so staff can move a canje through its statuses too.
async function requireOwner() {
  const session = await requireAdmin();
  if (session.role !== "ADMIN")
    throw new Error("Solo un administrador puede cambiar las reglas del programa.");
  return session;
}

function guard<T>(fn: () => Promise<T>): Promise<T | null> {
  return fn().catch((e) => {
    unstable_rethrow(e); // a signed-out redirect must reach the browser
    return null;
  });
}

function touched() {
  // The club page, the header/footer links and every product hint read these.
  revalidatePath("/", "layout");
  revalidatePath("/admin/loyalty");
}

// ---------- Rules ----------
export async function saveLoyaltyRules(
  _p: LoyaltyState,
  fd: FormData
): Promise<LoyaltyState> {
  const session = await guard(requireOwner);
  if (!session) return { error: "No tienes permiso para cambiar las reglas." };

  const raw = {
    enabled: fd.get("enabled") === "on",
    name: String(fd.get("name") ?? "").trim(),
    stampsToFree: String(fd.get("stampsToFree") ?? "").trim(),
    eligible: String(fd.get("eligible") ?? "all"),
    pointsPer: String(fd.get("pointsPer") ?? "").trim(),
    pointsAmount: String(fd.get("pointsAmount") ?? "").trim(),
    pointsOnShipping: fd.get("pointsOnShipping") === "on",
    expiryDays: String(fd.get("expiryDays") ?? "").trim(),
  };
  const values = Object.fromEntries(
    Object.entries(raw).map(([k, v]) => [k, typeof v === "boolean" ? String(v) : v])
  );

  const parsed = z
    .object({
      enabled: z.boolean(),
      name: z.string().min(2, "Ponle un nombre al programa").max(40),
      stampsToFree: z.coerce
        .number()
        .int("Debe ser un número entero")
        .min(1, "Mínimo 1 sello")
        .max(100, "Máximo 100 sellos"),
      eligible: z.enum(["all", "category", "product"]),
      pointsPer: z.coerce.number().int().min(0, "Usa 0 para pausar los puntos").max(10_000),
      pointsAmount: z.coerce.number().int().min(1, "El gasto base debe ser al menos Bs 1").max(100_000),
      pointsOnShipping: z.boolean(),
      expiryDays: z.coerce.number().int().min(0, "0 significa que no vencen").max(3650),
    })
    .safeParse(raw);
  if (!parsed.success) return { error: parsed.error.issues[0]?.message, values };

  // Slugs arrive as repeated fields from the checkbox groups; anything outside
  // the mode that was saved is dropped so a stale list can't leak in.
  const wanted =
    parsed.data.eligible === "all"
      ? []
      : fd.getAll("eligibleSlugs").map((s) => String(s)).filter(Boolean);
  const known =
    parsed.data.eligible === "category"
      ? new Set((await prisma.category.findMany({ select: { slug: true } })).map((c) => c.slug))
      : parsed.data.eligible === "product"
        ? new Set((await prisma.product.findMany({ select: { slug: true } })).map((p) => p.slug))
        : new Set<string>();
  const eligibleSlugs = [...new Set(wanted)].filter((s) => known.has(s)).slice(0, 200);

  const loyalty: LoyaltySettings = { ...parsed.data, eligibleSlugs };
  try {
    await saveStoreSettings("loyalty", loyalty);
  } catch (err) {
    console.error("[loyalty] rules save failed:", err);
    return { error: "No se pudo guardar: base de datos no disponible.", values };
  }
  touched();
  return { ok: true, values };
}

// ---------- Rewards catalogue ----------
export async function saveReward(
  _p: LoyaltyState,
  fd: FormData
): Promise<LoyaltyState> {
  const session = await guard(requireOwner);
  if (!session) return { error: "No tienes permiso para editar los regalos." };

  const id = String(fd.get("id") ?? "").trim();
  const raw = {
    name: String(fd.get("name") ?? "").trim(),
    description: String(fd.get("description") ?? "").trim(),
    image: String(fd.get("image") ?? "").trim(),
    costPoints: String(fd.get("costPoints") ?? "").trim(),
    stock: String(fd.get("stock") ?? "").trim(),
    order: String(fd.get("order") ?? "").trim(),
  };
  const values = { ...raw, id };
  const parsed = z
    .object({
      name: z.string().min(2, "Nombra el regalo").max(80),
      description: z.string().max(240),
      image: z.string().refine((v) => v === "" || /^\/|^https:\/\//i.test(v), "Enlace de imagen inválido"),
      costPoints: z.coerce.number().int().min(1, "Mínimo 1 punto").max(1_000_000),
      stock: z.coerce.number().int().min(0).max(100_000),
      order: z.coerce.number().int().min(0).max(9999),
    })
    .safeParse(raw);
  if (!parsed.success) return { error: parsed.error.issues[0]?.message, values };

  const data = {
    ...parsed.data,
    description: parsed.data.description || null,
    image: parsed.data.image || null,
  };
  try {
    if (id) {
      await prisma.reward.update({ where: { id }, data });
    } else {
      // Slug is unique and only used for the URL/seed matching.
      let slug = slugify(parsed.data.name) || "regalo";
      for (let n = 2; await prisma.reward.findUnique({ where: { slug } }); n++)
        slug = `${slugify(parsed.data.name)}-${n}`;
      await prisma.reward.create({ data: { ...data, slug } });
    }
  } catch (err) {
    console.error("[loyalty] reward save failed:", err);
    return { error: "No se pudo guardar el regalo.", values };
  }
  touched();
  return { ok: true, values };
}

export async function setRewardActive(id: string, active: boolean): Promise<void> {
  const session = await guard(requireOwner);
  if (!session) return;
  await prisma.reward
    .update({ where: { id }, data: { active } })
    .catch((err) => console.error("[loyalty] reward toggle failed:", err));
  touched();
}

export async function deleteReward(id: string): Promise<{ ok?: boolean; error?: string }> {
  const session = await guard(requireOwner);
  if (!session) return { error: "Sin permiso." };
  try {
    await prisma.reward.delete({ where: { id } });
  } catch {
    // A reward that has been redeemed stays (its canjes apuntan a ella).
    return { error: "Este regalo ya fue canjeado: desactívalo en lugar de borrarlo." };
  }
  touched();
  return { ok: true };
}

// ---------- Redemption counter ----------
const STATUSES: RedemptionStatus[] = ["PENDING", "READY", "COLLECTED", "CANCELLED"];

export async function setRedemptionStatus(id: string, status: string): Promise<void> {
  const session = await guard(requireAdmin);
  if (!session) return;
  if (!STATUSES.includes(status as RedemptionStatus)) return;
  const to = status as RedemptionStatus;
  const redemption = await prisma.redemption.findUnique({ where: { id } });
  if (!redemption || redemption.status === to) return;
  try {
    await prisma.$transaction(async (tx) => {
      await tx.redemption.update({ where: { id }, data: { status: to } });
      // Cancelling gives the prize back to the shelf and the points to the
      // customer, as one atomic step.
      if (to === "CANCELLED") {
        await tx.reward.update({ where: { id: redemption.rewardId }, data: { stock: { increment: 1 } } });
        await tx.loyaltyEntry.create({
          data: {
            customerId: redemption.customerId,
            rewardId: redemption.rewardId,
            kind: "ADJUST",
            points: redemption.costPoints,
            note: `Devolución por canje cancelado ${redemption.code}`,
          },
        });
      }
    });
  } catch (err) {
    console.error("[loyalty] status change failed:", err);
    return;
  }
  revalidatePath("/admin/loyalty");
}

// ---------- Manual corrections ----------
export async function adjustCustomer(
  _p: LoyaltyState,
  fd: FormData
): Promise<LoyaltyState> {
  const session = await guard(requireOwner);
  if (!session) return { error: "Solo un administrador puede ajustar saldos." };

  const raw = {
    customerId: String(fd.get("customerId") ?? ""),
    stamps: String(fd.get("stamps") ?? "").trim(),
    points: String(fd.get("points") ?? "").trim(),
    productId: String(fd.get("productId") ?? ""),
    note: String(fd.get("note") ?? "").trim(),
  };
  const values = { stamps: raw.stamps, points: raw.points, note: raw.note };
  const parsed = z
    .object({
      customerId: z.string().min(1),
      stamps: z.coerce.number().int().min(-1000).max(1000),
      points: z.coerce.number().int().min(-100_000).max(100_000),
      productId: z.string(),
      note: z.string().min(3, "Escribe por qué haces el ajuste").max(200),
    })
    .safeParse(raw);
  if (!parsed.success) return { error: parsed.error.issues[0]?.message, values };
  if (parsed.data.stamps === 0 && parsed.data.points === 0)
    return { error: "Indica sellos o puntos que quieras ajustar.", values };

  const customer = await prisma.customer.findUnique({ where: { id: parsed.data.customerId } });
  if (!customer) return { error: "Ese cliente ya no existe.", values };

  try {
    await adjustBalance({
      customerId: parsed.data.customerId,
      stamps: parsed.data.stamps,
      points: parsed.data.points,
      productId: parsed.data.productId || null,
      note: parsed.data.note,
    });
  } catch (err) {
    console.error("[loyalty] adjust failed:", err);
    return { error: "No se pudo registrar el ajuste.", values };
  }
  revalidatePath("/admin/loyalty");
  return { ok: true, values };
}
