export async function answerCustomer(history: ChatTurn[]): Promise<ChatReply> {
  const { text, settings, products, categories } = await storeKnowledge();
  const last = history[history.length - 1]?.content ?? "";

  if (aiEnabled()) {
    try {
      const reply = await aiReply(history, text);
      if (reply) return { reply, mode: "ai" };
    } catch (err) {
      if (err instanceof Anthropic.RateLimitError) console.warn("[chat] Claude rate limited — basic mode");
      else if (err instanceof Anthropic.AuthenticationError) console.error("[chat] Invalid ANTHROPIC_API_KEY — basic mode");
      else if (err instanceof Anthropic.APIError) console.error(`[chat] Claude API error ${err.status}:`, err.message);
      else console.error("[chat] assistant failed:", err);
    }
  }
  return { reply: basicReply(last, settings, products, categories), mode: "basic" };
}
// Field rules shared by the sign-in / sign-up / reset forms (live feedback in the
// browser) and their server actions (the real check). Dependency-free so it can
// load anywhere, including standalone scripts.

/** Minimum length for customer passwords (register, checkout sign-up, reset). */
export const MIN_PASSWORD = 8;

// name@domain.tld, strictly: local part of letters / digits / . _ % + - with no
// leading, trailing or doubled dots; after the @ letters only (owner's rule — no
// digits), labels that don't start or end with "-"; a TLD of 2–24 letters.
export const EMAIL_RE =
  /^[a-z0-9_%+-]+(?:\.[a-z0-9_%+-]+)*@(?:[a-z](?:[a-z-]{0,61}[a-z])?\.)+[a-z]{2,24}$/i;

// Real endings only: any 2-letter country code (.pk, .uk, .ae …) or one of
// these. Catches ".comm", ".con", ".cmo", ".coom" and friends.
const GENERIC_TLDS = new Set(
  "com net org edu gov mil int info biz name pro mobi asia aero coop jobs travel io co app dev me tv cc ai xyz online site store shop tech cloud live email digital agency studio design media news blog website space world life today company services solutions group global network systems academy center consulting".split(" ")
);
const TLD_TYPOS = new Set(["co", "cm", "om", "con", "cmo", "ocm", "comm", "coom", "vom", "xom", "cpm", "clm", "cim", "comn", "coml", "net1"]);

// Mailboxes people actually use — a near miss ("gmial.com", "gmail.co") is a typo.
const PROVIDERS = [
  "gmail.com", "googlemail.com", "yahoo.com", "ymail.com", "rocketmail.com", "hotmail.com", "outlook.com",
  "live.com", "msn.com", "icloud.com", "me.com", "aol.com", "protonmail.com", "proton.me", "mail.com", "zoho.com",
  "email.com", "gmx.com", "yandex.com",
];

function editDistance(a: string, b: string): number {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array(b.length).fill(0)]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++)
    for (let j = 1; j <= b.length; j++) {
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
      if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1);
    }
  return d[a.length][b.length];
}

/** "ahmad@gmial.com" → "ahmad@gmail.com"; null when the domain looks deliberate. */
export function emailSuggestion(value: string): string | null {
  const v = value.trim().toLowerCase();
  const at = v.lastIndexOf("@");
  if (at < 1) return null;
  const domain = v.slice(at + 1);
  if (!domain || PROVIDERS.includes(domain)) return null;
  const sld = domain.split(".")[0];
  const tld = domain.slice(sld.length + 1);
  let best: string | null = null;
  let bestScore = Infinity;
  for (const p of PROVIDERS) {
    const pSld = p.split(".")[0];
    // Same provider name with a wrong ending (gmail.co, gmail.con, hotmail.comm) …
    if (sld === pSld && tld !== p.slice(pSld.length + 1) && (TLD_TYPOS.has(tld) || tld.startsWith("com") || tld === "")) return v.slice(0, at + 1) + p;
    // … or a misspelt provider name (gmial, gmai, yahooo, hotmial, outlok).
    if (pSld.length >= 5 && sld.length >= 4 && (tld === p.slice(pSld.length + 1) || TLD_TYPOS.has(tld))) {
      const dist = editDistance(sld, pSld);
      if (dist > 0 && dist <= 2 && dist < bestScore) [best, bestScore] = [p, dist];
    }
  }
  return best ? v.slice(0, at + 1) + best : null;
}

export function emailError(value: string): string | null {
  const v = value.trim();
  if (!v) return "Ingresa tu correo";
  if (/\s/.test(v)) return "El correo no puede tener espacios";
  const at = v.split("@").length - 1;
  if (at === 0) return "Falta el @, por ejemplo nombre@ejemplo.com";
  if (at > 1) return "El correo solo puede tener un @";
  const [local, domain] = v.split("@");
  if (!local) return "Escribe tu nombre antes del @";
  if (!domain) return "Agrega el dominio después del @, por ejemplo gmail.com";
  if (/[^a-z.-]/i.test(domain)) return "Usa solo letras después del @, por ejemplo gmail.com";
  if (!domain.includes(".")) return "Al dominio le falta una terminación, por ejemplo .com o .bo";
  if (v.length > 200 || local.length > 64 || !EMAIL_RE.test(v)) return "Ingresa un correo válido, por ejemplo nombre@ejemplo.com";
  const tld = domain.slice(domain.lastIndexOf(".") + 1).toLowerCase();
  const fix = emailSuggestion(v);
  if (fix) return `¿Quisiste decir ${fix}?`;
  if (tld.length !== 2 && !GENERIC_TLDS.has(tld)) return `".${tld}" no es una terminación real: revísala (ej. .com, .bo)`;
  return null;
}

// Letters in any script (Urdu too) plus spaces, dots, apostrophes and hyphens;
// starts with a letter.
export const NAME_RE = /^\p{L}[\p{L}\p{M} .'-]*$/u;

export function nameError(value: string): string | null {
  const v = value.trim();
  if (!v) return "Ingresa tu nombre";
  if (v.length < 2) return "El nombre es muy corto";
  if (v.length > 120) return "El nombre es muy largo";
  if (!NAME_RE.test(v)) return "Usa solo letras (espacios, . ' - están bien)";
  return null;
}

// Phone / WhatsApp. Brasiln numbers in any usual form — 71234567,
// 071234567, 591 71234567 or +591 71234567 — or any number with a "+" country
// code (E.164: 8–15 digits). Spaces and dashes are fine while typing.
export const PHONE_RE = /^\+[1-9]\d{7,14}$/;

/** Saved form: "071234567" / "591-71234567" → "+59171234567"; others lose spaces / dashes. */
export function normalizePhone(value: string): string {
  const v = value.trim().replace(/[\s-]/g, "");
  if (/^0\d{8}$/.test(v)) return `+591${v.slice(1)}`;
  if (/^591\d{8}$/.test(v)) return `+${v}`;
  return v;
}

export function phoneError(value: string): string | null {
  const v = value.trim().replace(/[\s-]/g, "");
  if (!v) return "Ingresa tu teléfono o WhatsApp";
  if (!/^\+?\d+$/.test(v)) return "Usa solo números (puedes empezar con +)";
  if (v.startsWith("0")) return /^0\d{8}$/.test(v) ? null : "Los números en Brasil tienen 8 dígitos, como 71234567";
  if (v.startsWith("591")) return /^591\d{8}$/.test(v) ? null : "El código de Brasil es +591, como +591 71234567";
  if (v.startsWith("+591")) return /^\+591\d{8}$/.test(v) ? null : "El código de Brasil es +591, como +591 71234567";
  if (!v.startsWith("+")) return "Empieza con 0, 591 o tu código de país (como +44)";
  return PHONE_RE.test(v) ? null : "Escribe el número completo con código de país, como +591 71234567";
}

/** The checklist shown under a new-password field. */
export function passwordRules(value: string) {
  return [
    { id: "length", label: `Al menos ${MIN_PASSWORD} caracteres`, ok: value.length >= MIN_PASSWORD },
    { id: "letter", label: "Una letra", ok: /\p{L}/u.test(value) },
    { id: "number", label: "Un número", ok: /\d/.test(value) },
  ];
}

export function newPasswordError(value: string): string | null {
  if (!value) return "Elige una contraseña";
  if (value.length > 200) return "La contraseña es muy larga";
  const missing = passwordRules(value).find((r) => !r.ok);
  return missing ? `La contraseña necesita ${missing.label.toLowerCase()}` : null;
}

/** 0–4: drives the strength meter (rules met, plus a bonus for length / symbols). */
export function passwordStrength(value: string): number {
  if (!value) return 0;
  const met = passwordRules(value).filter((r) => r.ok).length;
  let score = met; // 0–3
  if (met === 3 && (value.length >= 12 || /[^\p{L}\d]/u.test(value))) score = 4;
  return score;
}
import { cookies } from "next/headers";
import { createToken, readToken } from "./session-token";

// Lightweight admin auth — no external dependencies.
// Passwords: scrypt salted hashes (see ./password). Sessions: HMAC-signed cookie
// (see ./session-token — admin tokens use their own signing key).

export { hashPassword, verifyPassword } from "./password";

const SESSION_COOKIE = "inbramet_admin";
const SESSION_TTL_SECONDS = 60 * 60 * 8; // 8 hours
export const ADMIN_ROLES = ["ADMIN", "STAFF"];

/** `ver` = the admin row's `updatedAt` (ms) when this session signed in; a newer
 *  sign-in on the same account bumps it, which retires this session (see lib/admin).
 *  `branchId` binds STAFF sessions to one store; ADMIN sessions are global. */
export type AdminSession = { email: string; role: string; ver: number; branchId: string | null; exp: number };

// ---------- Cookie helpers (server actions / route handlers) ----------

export async function startSession(
  email: string,
  role: string,
  ver: number,
  branchId: string | null = null
): Promise<void> {
  const session: AdminSession = {
    email,
    role,
    ver,
    branchId,
    exp: Math.floor(Date.now() / 1000) + SESSION_TTL_SECONDS,
  };
  const store = await cookies();
  store.set(SESSION_COOKIE, createToken("admin", session), {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
    maxAge: SESSION_TTL_SECONDS,
  });
}

export async function endSession(): Promise<void> {
  const store = await cookies();
  store.delete(SESSION_COOKIE);
}

export async function getAdminSession(): Promise<AdminSession | null> {
  const store = await cookies();
  const token = store.get(SESSION_COOKIE)?.value;
  if (!token) return null;
  const session = readToken<AdminSession>("admin", token);
  if (!session || !session.email || typeof session.ver !== "number" || !ADMIN_ROLES.includes(session.role)) return null;
  return { ...session, branchId: typeof session.branchId === "string" ? session.branchId : null };
}
import { cookies } from "next/headers";
import { cache } from "react";
import { prisma } from "./prisma";
import type { StoreSettings } from "./settings-shared";

// The branch a shopper picked is kept in a long-lived cookie. Browsing works
// without one (the storefront shows availability across the chain); it becomes
// mandatory the moment an order is started.
export const BRANCH_COOKIE = "cc_branch";

export type BranchView = {
  id: string;
  name: string;
  slug: string;
  code: string;
  address: string;
  city: string;
  phone: string | null;
  whatsapp: string | null;
  hours: string | null;
  image: string | null;
  mapsUrl: string | null;
  latitude: number | null;
  longitude: number | null;
  deliveryEnabled: boolean;
  pickupEnabled: boolean;
  flatFee: number | null;
  freeThreshold: number | null;
};

export type BranchWithStock = BranchView & { products: number; units: number };

function toView(b: {
  id: string;
  name: string;
  slug: string;
  code: string;
  address: string;
  city: string;
  phone: string | null;
  whatsapp: string | null;
  hours: string | null;
  image: string | null;
  mapsUrl: string | null;
  latitude: number | null;
  longitude: number | null;
  deliveryEnabled: boolean;
  pickupEnabled: boolean;
  flatFee: unknown;
  freeThreshold: unknown;
}): BranchView {
  return {
    id: b.id,
    name: b.name,
    slug: b.slug,
    code: b.code,
    address: b.address,
    city: b.city,
    phone: b.phone,
    whatsapp: b.whatsapp,
    hours: b.hours,
    image: b.image,
    mapsUrl: b.mapsUrl,
    latitude: b.latitude,
    longitude: b.longitude,
    deliveryEnabled: b.deliveryEnabled,
    pickupEnabled: b.pickupEnabled,
    flatFee: b.flatFee == null ? null : Number(b.flatFee),
    freeThreshold: b.freeThreshold == null ? null : Number(b.freeThreshold),
  };
}

/** Active branches, in display order. Never throws (storefront must render). */
export const getBranches = cache(async (): Promise<BranchView[]> => {
  try {
    const rows = await prisma.branch.findMany({
      where: { active: true },
      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
    });
    return rows.map(toView);
  } catch {
    return [];
  }
});

export const getBranchBySlug = cache(async (slug: string): Promise<BranchView | null> => {
  const branches = await getBranches();
  return branches.find((b) => b.slug === slug) ?? null;
});

/** Any branch by id (including inactive ones), for the admin panel. */
export const getBranchById = cache(async (id: string): Promise<BranchView | null> => {
  try {
    const b = await prisma.branch.findUnique({ where: { id } });
    return b ? toView(b) : null;
  } catch {
    return null;
  }
});

/** Branch picked by the shopper, or null when none/unavailable. */
export const getSelectedBranch = cache(async (): Promise<BranchView | null> => {
  const store = await cookies();
  const slug = store.get(BRANCH_COOKIE)?.value;
  if (!slug) return null;
  return (await getBranches()).find((b) => b.slug === slug) ?? null;
});

/** Shipping rules for a branch (falls back to store-wide settings). */
export function shippingForBranch(
  branch: { flatFee: number | null; freeThreshold: number | null } | null,
  settings: Pick<StoreSettings, "shipping">
): StoreSettings["shipping"] {
  return {
    flatFee: branch?.flatFee ?? settings.shipping.flatFee,
    freeThreshold: branch?.freeThreshold ?? settings.shipping.freeThreshold,
    deliveryTime: settings.shipping.deliveryTime,
  };
}
import { revalidatePath, revalidateTag } from "next/cache";

// Cross-request caches for storefront data, and the one call that refreshes each.
// `expire: 0` = the next visitor gets fresh data (never a stale page), which is
// what an admin expects right after saving.

export const CATALOG_TAG = "catalog";
export const SETTINGS_TAG = "store-settings";

function refresh(tag: string) {
  try {
    revalidateTag(tag, { expire: 0 });
  } catch (err) {
    // Outside a request (scripts / seed) there is no cache to refresh.
    if (process.env.NEXT_RUNTIME) console.error(`[cache] could not refresh "${tag}":`, err);
  }
}

/** Products, categories or stock changed. */
export const refreshCatalog = () => refresh(CATALOG_TAG);

/** An admin edit to products / categories: fresh catalog data and fresh cached
 *  pages (every route, incl. ISR product pages) on the next visit. */
export function refreshStorefront() {
  refreshCatalog();
  revalidatePath("/", "layout");
}

/** Admin → Settings saved. */
export const refreshSettings = () => refresh(SETTINGS_TAG);
import type { CartItem } from "@/components/cart/cart-provider";
import type { ProductView } from "./types";

// Plain module (not "use client") so server pages and client buttons share it.
/** The cart line for a product — everything but the quantity. */
export function toCartLine(product: ProductView): Omit<CartItem, "quantity"> {
  return {
    id: product.id,
    slug: product.slug,
    name: product.name,
    price: product.price,
    compareAtPrice: product.compareAtPrice,
    image: product.images[0],
    material: product.material,
    stock: product.stock,
  };
}
import { cache } from "react";
import { unstable_cache } from "next/cache";
import { prisma } from "./prisma";
import { sampleCategories, sampleProducts } from "./sample-data";
import { searchCatalog, type SearchCategory, type SearchResult } from "./search-engine";
import { CATALOG_TAG } from "./cache-tags";
import type { CategoryView, ProductView, ProductFilters, ShopFacets } from "./types";

// The storefront reads through these functions. The active catalog is one
// cached snapshot (product + per-branch stock rows, shared across requests and
// refreshed whenever the admin edits a product, a branch's stock, or an order
// changes stock — see lib/cache-tags). Filters, facets and search are worked out
// in memory. Availability is resolved for the branch the shopper picked; with
// no branch selected it shows the chain-wide total so browsing still works.
// Without a database the bundled sample data is served so the UI stays previewable.

let warned = false;
function warnFallback(err: unknown) {
  // In production this means the live DB is unreachable — log every time so it
  // shows up in the host's function logs instead of silently serving samples.
  if (process.env.NODE_ENV === "production") {
    console.error("[catalog] DATABASE UNAVAILABLE — serving sample data:", err);
    return;
  }
  if (!warned) {
    warned = true;
    console.warn(
      "[catalog] Database unavailable — serving sample data. Connect DATABASE_URL and run `npx prisma migrate dev` + `npm run db:seed` to go live.",
      err instanceof Error ? err.message : err
    );
  }
}

type SnapshotProduct = Omit<ProductView, "stock"> & {
  stockByBranch: Record<string, number>;
  totalStock: number;
};

type Snapshot = { products: SnapshotProduct[]; categories: CategoryView[] };

// Cross-request cache (5 min safety net; normally refreshed by tag).
const loadSnapshot = unstable_cache(
  async (): Promise<Snapshot> => {
    const [products, categories] = await Promise.all([
      prisma.product.findMany({
        where: { active: true },
        include: {
          category: { select: { name: true, slug: true } },
          branchStock: { select: { branchId: true, stock: true, active: true } },
        },
        orderBy: { createdAt: "desc" },
      }),
      prisma.category.findMany({
        where: { OR: [{ slug: { not: "combos" } }, { products: { some: { active: true } } }] },
        orderBy: { name: "asc" },
      }),
    ]);
    return {
      products: products.map((p) => {
        const stockByBranch: Record<string, number> = {};
        let totalStock = 0;
        for (const s of p.branchStock) {
          if (!s.active) continue;
          const n = Math.max(0, s.stock);
          stockByBranch[s.branchId] = n;
          totalStock += n;
        }
        return {
          id: p.id,
          name: p.name,
          slug: p.slug,
          description: p.description,
          price: Number(p.price),
          compareAtPrice: p.compareAtPrice == null ? null : Number(p.compareAtPrice),
          material: p.material,
          specs: p.specs ?? null,
          images: p.images ?? [],
          featured: p.featured,
          category: p.category,
          stockByBranch,
          totalStock,
        };
      }),
      categories: categories.map((c) => ({ id: c.id, name: c.name, slug: c.slug, description: c.description })),
    };
  },
  ["catalog-snapshot-v2"],
  { tags: [CATALOG_TAG], revalidate: 300 }
);

/** Per request: one snapshot, however many catalog calls the page makes. */
const getSnapshot = cache(async (): Promise<Snapshot> => {
  try {
    return await loadSnapshot();
  } catch (err) {
    warnFallback(err);
    return {
      products: sampleProducts.map((p) => ({
        ...p,
        stockByBranch: {},
        totalStock: p.stock,
      })),
      categories: sampleCategories,
    };
  }
});

/** Resolve availability for a branch (or the chain-wide total when null). */
function toView(p: SnapshotProduct, branchId?: string | null): ProductView {
  return {
    ...p,
    stock: branchId ? (p.stockByBranch[branchId] ?? 0) : p.totalStock,
  };
}

async function listFor(branchId?: string | null): Promise<ProductView[]> {
  const { products } = await getSnapshot();
  return products.map((p) => toView(p, branchId));
}

// ---------- Categories ----------

export async function getCategories(): Promise<CategoryView[]> {
  return (await getSnapshot()).categories;
}

export async function getCategoryBySlug(slug: string): Promise<CategoryView | null> {
  return (await getSnapshot()).categories.find((c) => c.slug === slug) ?? null;
}

// ---------- Products ----------

const onSaleNow = (p: ProductView) => p.compareAtPrice != null && p.compareAtPrice > p.price;

/** Newest first unless a price sort is picked; `q` ranks by relevance. */
export async function getProducts(
  filters: ProductFilters = {},
  branchId?: string | null
): Promise<ProductView[]> {
  const { categorySlug, q, minPrice, maxPrice, material, onSale, inStock, sort = "newest" } = filters;
  const products = await listFor(branchId);

  let list = products.filter(
    (p) =>
      (!categorySlug || p.category.slug === categorySlug) &&
      (!material || p.material === material) &&
      (!onSale || onSaleNow(p)) &&
      (!inStock || p.stock > 0) &&
      (minPrice == null || p.price >= minPrice) &&
      (maxPrice == null || p.price <= maxPrice)
  );
  if (q) list = applyQuery(list, q);
  if (sort === "price-asc") list = [...list].sort((a, b) => a.price - b.price);
  else if (sort === "price-desc") list = [...list].sort((a, b) => b.price - a.price);
  return list;
}

/** Products by id (cart refresh / buy-now), with availability for one branch. */
export async function getProductsByIds(ids: string[], branchId?: string | null): Promise<ProductView[]> {
  const wanted = new Set(ids);
  return (await listFor(branchId)).filter((p) => wanted.has(p.id));
}

/** The shop's `?q=` text filter: same typo-tolerant matching as /search. */
function applyQuery(list: ProductView[], q: string): ProductView[] {
  const cats = new Map<string, SearchCategory>();
  for (const p of list) {
    const c = cats.get(p.category.slug);
    if (c) c.count++;
    else cats.set(p.category.slug, { id: p.category.slug, name: p.category.name, slug: p.category.slug, description: null, count: 1 });
  }
  return searchCatalog(q, list, [...cats.values()]).products;
}

export async function getProductBySlug(slug: string, branchId?: string | null): Promise<ProductView | null> {
  return (await listFor(branchId)).find((p) => p.slug === slug) ?? null;
}

/** Featured pieces, newest first; the newest pieces when none are featured. */
export async function getFeaturedProducts(limit = 4, branchId?: string | null): Promise<ProductView[]> {
  const products = await listFor(branchId);
  const featured = products.filter((p) => p.featured);
  return (featured.length ? featured : products).slice(0, limit);
}

export async function getRelatedProducts(
  product: ProductView,
  branchId?: string | null,
  limit = 4
): Promise<ProductView[]> {
  const products = await listFor(branchId);
  return products.filter((p) => p.category.slug === product.category.slug && p.id !== product.id).slice(0, limit);
}

// ---------- Search ----------

/** Full /search answer: ranked pieces plus how the query was read. All
 *  categories are passed (even empty ones) so an empty category can say "coming soon". */
export async function searchStore(
  q: string,
  branchId?: string | null
): Promise<SearchResult & { categories: SearchCategory[]; all: ProductView[] }> {
  const { categories: list } = await getSnapshot();
  const products = await listFor(branchId);
  const categories = list.map((c) => ({
    ...c,
    count: products.filter((p) => p.category.slug === c.slug).length,
  }));
  return { ...searchCatalog(q, products, categories), categories, all: products };
}

// ---------- Shop sidebar facets ----------

/** Category counts (whole store) + price bounds, materials, sale and stock counts
 *  for the current category scope. */
export async function getShopFacets(
  categorySlug?: string,
  branchId?: string | null
): Promise<ShopFacets> {
  const { categories } = await getSnapshot();
  const rows = await listFor(branchId);

  const scoped = categorySlug ? rows.filter((r) => r.category.slug === categorySlug) : rows;
  const prices = (scoped.length ? scoped : rows).map((r) => r.price);
  const priceMin = prices.length ? Math.floor(Math.min(...prices) / 100) * 100 : 0;
  let priceMax = prices.length ? Math.ceil(Math.max(...prices) / 100) * 100 : 0;
  if (priceMax <= priceMin) priceMax = priceMin + 100;

  const materialCounts = new Map<string, number>();
  for (const r of scoped) {
    if (r.material) materialCounts.set(r.material, (materialCounts.get(r.material) ?? 0) + 1);
  }

  return {
    total: rows.length,
    categories: categories
      .map((c) => ({
        name: c.name,
        slug: c.slug,
        count: rows.filter((r) => r.category.slug === c.slug).length,
      }))
      .filter((c) => c.count > 0),
    priceMin,
    priceMax,
    materials: [...materialCounts]
      .map(([name, count]) => ({ name, count }))
      .sort((a, b) => a.name.localeCompare(b.name)),
    onSale: scoped.filter(onSaleNow).length,
    inStock: scoped.filter((r) => r.stock > 0).length,
  };
}
