function clean(v: string | undefined): string {
  return (v ?? "").trim();
}

const whatsapp = clean(process.env.NEXT_PUBLIC_WHATSAPP_NUMBER).replace(/[^0-9]/g, "");
const phone = clean(process.env.NEXT_PUBLIC_CONTACT_PHONE);

export const CONTACT = {
  /** International format, digits only (e.g. 59171662586). */
  whatsapp,
  whatsappUrl: whatsapp ? `https://wa.me/${whatsapp}` : "",
  /** Display format (e.g. "+591 71 662 586"). */
  phone,
  phoneHref: phone ? `tel:${phone.replace(/[^0-9+]/g, "")}` : "",
  email: clean(process.env.NEXT_PUBLIC_CONTACT_EMAIL),
  city: clean(process.env.NEXT_PUBLIC_CONTACT_CITY) || STORE_LOCATION,
  hours: clean(process.env.NEXT_PUBLIC_CONTACT_HOURS) || "Lunes a domingo · 11:00 a 23:00",
  instagram: clean(process.env.NEXT_PUBLIC_INSTAGRAM_URL),
  facebook: clean(process.env.NEXT_PUBLIC_FACEBOOK_URL),
  tiktok: clean(process.env.NEXT_PUBLIC_TIKTOK_URL),
} as const;
// Courier integration for Brasil — Leopards & TCS.
//
// Live booking needs the client's courier MERCHANT account API credentials,
// set as environment variables (see below). Until those are set, bookShipment
// runs in SIMULATION mode: it generates a realistic tracking number so the
// whole order → ship → track flow works for demos/testing. The moment the
// real keys are added, the same call books a live shipment automatically.
//
// Env vars to go live:
//   Leopards:  LEOPARDS_API_KEY, LEOPARDS_API_PASSWORD
//   TCS:       TCS_USERNAME, TCS_PASSWORD, TCS_CLIENT_ID, TCS_CLIENT_SECRET, TCS_COST_CENTER

export type Courier = "LEOPARDS" | "TCS";

export type BookResult =
  | { ok: true; trackingNumber: string; simulated: boolean }
  | { ok: false; error: string };

type OrderForShipment = {
  orderNumber: string;
  customerName: string;
  email: string;
  phone: string;
  address: string;
  city: string;
  total: number;
  paymentMethod: string;
  itemCount: number;
};

export function isCourier(v: string): v is Courier {
  return v === "LEOPARDS" || v === "TCS";
}

export function courierLabel(c: string): string {
  if (c === "LEOPARDS") return "Leopards Courier";
  if (c === "TCS") return "TCS";
  return c;
}

export function trackingUrl(courier: string, trackingNumber: string): string {
  const tn = encodeURIComponent(trackingNumber);
  if (courier === "LEOPARDS") return `https://www.leopardscourier.com/leopards-tracking?tracking_number=${tn}`;
  if (courier === "TCS") return `https://www.tcsexpress.com/track/?consignmentNo=${tn}`;
  return "#";
}

// Simulation is for development/demos only. In production a missing courier
// key is an error unless COURIER_SIMULATION=true is set explicitly; otherwise
// orders would be marked SHIPPED with a fake tracking number.
function simulationAllowed(): boolean {
  return process.env.NODE_ENV !== "production" || process.env.COURIER_SIMULATION === "true";
}

function notConfigured(name: string): BookResult {
  return {
    ok: false,
    error: `${name}: las credenciales de la API aún no están configuradas. Agrégalas al entorno del servidor para reservar envíos.`,
  };
}

function simulatedTracking(courier: Courier): string {
  const n = Math.floor(100000000 + Math.random() * 899999999);
  return courier === "LEOPARDS" ? `LE${n}` : `TCS${n}`;
}

export async function bookShipment(order: OrderForShipment, courier: Courier): Promise<BookResult> {
  try {
    if (courier === "LEOPARDS") return await bookLeopards(order);
    return await bookTcs(order);
  } catch (err) {
    console.error("[courier] booking failed:", err);
    return { ok: false, error: "No se pudo reservar el envío. Inténtalo de nuevo." };
  }
}

// ---------------- Leopards ----------------
async function bookLeopards(order: OrderForShipment): Promise<BookResult> {
  const key = process.env.LEOPARDS_API_KEY;
  const pass = process.env.LEOPARDS_API_PASSWORD;

  // No credentials yet → simulate so the flow works.
  if (!key || !pass) {
    if (!simulationAllowed()) return notConfigured("Leopards");
    return { ok: true, trackingNumber: simulatedTracking("LEOPARDS"), simulated: true };
  }

  const origin = process.env.LEOPARDS_ORIGIN_CITY || "Brasil";
  const res = await fetch("https://merchantapi.leopardscourier.com/api/bookPacket/format/json/", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      api_key: key,
      api_password: pass,
      booked_packet_weight: Math.max(500, order.itemCount * 250), // grams
      booked_packet_no_piece: order.itemCount || 1,
      booked_packet_collect_amount: order.paymentMethod === "COD" ? order.total : 0,
      booked_packet_order_id: order.orderNumber,
      origin_city: origin,
      destination_city: order.city,
      shipment_name_eng: order.customerName,
      shipment_email: order.email,
      shipment_phone: order.phone,
      shipment_address: order.address,
      shipment_item_desc: "productos",
    }),
    signal: AbortSignal.timeout(15000),
  });
  const data = await res.json().catch(() => ({}));
  const tn = data?.track_number || data?.trackNumber;
  if (data?.status && tn) return { ok: true, trackingNumber: String(tn), simulated: false };
  return { ok: false, error: data?.error || "Leopards no devolvió un número de seguimiento." };
}

// ---------------- TCS ----------------
async function bookTcs(order: OrderForShipment): Promise<BookResult> {
  const user = process.env.TCS_USERNAME;
  const pass = process.env.TCS_PASSWORD;
  const clientId = process.env.TCS_CLIENT_ID;
  const clientSecret = process.env.TCS_CLIENT_SECRET;

  if (!user || !pass || !clientId || !clientSecret) {
    if (!simulationAllowed()) return notConfigured("TCS");
    return { ok: true, trackingNumber: simulatedTracking("TCS"), simulated: true };
  }

  const origin = process.env.TCS_ORIGIN_CITY || "Brasil";
  const res = await fetch("https://api.tcscourier.com/production/v1/cod/create-order", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "X-IBM-Client-Id": clientId,
      "X-IBM-Client-Secret": clientSecret,
    },
    body: JSON.stringify({
      userName: user,
      password: pass,
      costCenterCode: process.env.TCS_COST_CENTER || "",
      consigneeName: order.customerName,
      consigneeAddress: order.address,
      consigneeMobNo: order.phone,
      consigneeEmail: order.email,
      originCityName: origin,
      destinationCityName: order.city,
      weight: Math.max(0.5, (order.itemCount || 1) * 0.25),
      pieces: order.itemCount || 1,
      codAmount: order.paymentMethod === "COD" ? order.total : 0,
      customerReferenceNo: order.orderNumber,
      services: "O", // overnight
      productDetails: "productos",
    }),
    signal: AbortSignal.timeout(15000),
  });
  const data = await res.json().catch(() => ({}));
  const tn = data?.consignmentNo || data?.consignmentNumber || data?.trackingNumber;
  if (tn) return { ok: true, trackingNumber: String(tn), simulated: false };
  return { ok: false, error: data?.returnStatus?.message || "TCS no devolvió un número de seguimiento." };
}
// Options for the custom-order request form (shared by the form + server action).
export const PIECE_TYPES = ["piezas típicos", "sala", "muebles", "Postres", "Bebidas", "Pedido para evento", "Otro"] as const;
export const FINISHES = ["Individual", "Para 2 personas", "Para 4 personas", "Bandeja para compartir", "No estoy seguro"] as const;
export const BUDGETS = ["Menos de Bs 100", "Bs 100 – 300", "Bs 300 – 600", "Bs 600 o más", "No estoy seguro"] as const;

// Reference photos attached to a custom-order request.
export const MAX_REFERENCE_PHOTOS = 3;
/** Per photo, after the browser shrinks it (originals it can't shrink must fit too). */
export const MAX_REFERENCE_BYTES = 3 * 1024 * 1024;
/** Heading the server writes above the photo links in the saved message. */
export const REFERENCE_PHOTOS_HEADING = "Fotos de referencia:";

// Only links to our own reference uploads are treated as photos (a customer
// could type the heading into their description).
const OWN_REFERENCE_URL =
  /^(\/uploads\/references\/[a-z0-9-]+\.(jpg|png|webp|avif)|https:\/\/[a-z0-9-]+\.public\.blob\.vercel-storage\.com\/references\/[a-z0-9-]+\.(jpg|png|webp|avif))$/;

/** Splits a saved custom-request message into its text and reference-photo URLs. */
export function splitReferencePhotos(message: string): { text: string; photos: string[] } {
  const at = message.lastIndexOf(`\n${REFERENCE_PHOTOS_HEADING}\n`);
  if (at === -1) return { text: message, photos: [] };
  const lines = message.slice(at + REFERENCE_PHOTOS_HEADING.length + 2).split("\n").map((l) => l.trim());
  const photos = lines.filter((l) => OWN_REFERENCE_URL.test(l));
  if (photos.length === 0 || photos.length !== lines.filter(Boolean).length) return { text: message, photos: [] };
  return { text: message.slice(0, at).trimEnd(), photos };
}
import { cookies } from "next/headers";
import { redirect } from "next/navigation";
import { createToken, readToken } from "./session-token";

// Storefront customer sessions — separate cookie AND separate signing key from
// the admin session (see ./session-token).

const COOKIE = "inbramet_customer";
const TTL_SECONDS = 60 * 60 * 24 * 30; // 30 days

export type CustomerSession = {
  id: string;
  email: string;
  name: string;
  exp: number;
};

export async function startCustomerSession(customer: {
  id: string;
  email: string;
  name: string;
}): Promise<void> {
  const session: CustomerSession = {
    id: customer.id,
    email: customer.email,
    name: customer.name,
    exp: Math.floor(Date.now() / 1000) + TTL_SECONDS,
  };
  const store = await cookies();
  store.set(COOKIE, createToken("customer", session), {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
    maxAge: TTL_SECONDS,
  });
}

export async function endCustomerSession(): Promise<void> {
  const store = await cookies();
  store.delete(COOKIE);
}

export async function getCustomerSession(): Promise<CustomerSession | null> {
  const store = await cookies();
  const token = store.get(COOKIE)?.value;
  return token ? readToken<CustomerSession>("customer", token) : null;
}

// Only allow same-site relative paths as a post-login destination
// (prevents open redirects like `?next=//evil.com`).
export function safeNext(value: unknown, fallback = "/account"): string {
  const v = typeof value === "string" ? value.trim() : "";
  if (!v.startsWith("/") || v.startsWith("//") || v.startsWith("/\\")) return fallback;
  if (v.startsWith("/login") || v.startsWith("/register")) return fallback;
  return v;
}

// Guards customer-only pages — redirects to login (and back afterwards).
export async function requireCustomer(returnTo = "/account"): Promise<CustomerSession> {
  const session = await getCustomerSession();
  if (!session) redirect(`/login?next=${encodeURIComponent(safeNext(returnTo))}`);
  return session;
}
// Classifies Prisma / database errors so the shopper gets the right message and
// the real cause is always logged (visible in Vercel / Netlify function logs).

export type DbErrorKind = "unavailable" | "duplicate" | "in-use" | "not-migrated" | "engine" | "unknown";

export function dbErrorKind(err: unknown): DbErrorKind {
  const e = err as { code?: string; errorCode?: string; message?: string; name?: string } | null;
  const code = e?.code || e?.errorCode || "";
  const msg = e?.message || "";
  if (code === "P2002" || /Unique constraint/i.test(msg)) return "duplicate";
  // Foreign key: the row is still referenced (e.g. a product in past orders).
  if (code === "P2003" || /Foreign key constraint/i.test(msg)) return "in-use";
  if (
    ["P1000", "P1001", "P1002", "P1003", "P1008", "P1010", "P1011", "P1017"].includes(code) ||
    /Can't reach database|ECONNREFUSED|ETIMEDOUT|ENOTFOUND|connection|Authentication failed|TLS|timed out/i.test(msg) ||
    e?.name === "PrismaClientInitializationError"
  )
    return "unavailable";
  if (code === "P2021" || code === "P2022" || /does not exist in the current database|relation .* does not exist/i.test(msg))
    return "not-migrated";
  if (/Query Engine|could not locate|libquery_engine|binaryTargets/i.test(msg)) return "engine";
  return "unknown";
}

/** Logs the full error with a tag and returns its kind. */
export function logDbError(tag: string, err: unknown): DbErrorKind {
  const kind = dbErrorKind(err);
  console.error(`[${tag}] database error (${kind}):`, err);
  return kind;
}
import nodemailer from "nodemailer";
import { formatPrice } from "./format";
import { getStoreSettings } from "./settings";

// Where owner alerts go: Admin → Settings → Notifications, else env.
async function alertAddress(): Promise<string> {
  const fromSettings = (await getStoreSettings()).notifications.orderEmail;
  return fromSettings || process.env.ADMIN_NOTIFY_EMAIL || process.env.SMTP_USER || "";
}

// Transactional email via SMTP. Works with any provider (Gmail, your web-host
// mailbox, Brevo/SendinBlue, Mailgun SMTP, etc.). Until SMTP env vars are set,
// emails are skipped gracefully (checkout still succeeds).

export type OrderEmailData = {
  orderNumber: string;
  customerName: string;
  email: string;
  phone: string;
  address: string;
  city: string;
  branchName?: string;
  fulfillment?: "DELIVERY" | "PICKUP";
  paymentMethod: string;
  items: { name: string; quantity: number; price: number }[];
  subtotal: number;
  shipping: number;
  total: number;
};

export function emailConfigured(): boolean {
  return Boolean(process.env.SMTP_HOST && process.env.SMTP_USER && process.env.SMTP_PASS);
}

function getTransport() {
  return nodemailer.createTransport({
    host: process.env.SMTP_HOST,
    port: Number(process.env.SMTP_PORT || 587),
    secure: process.env.SMTP_SECURE === "true", // true for port 465
    auth: {
      user: process.env.SMTP_USER,
      // Google shows App Passwords as "abcd efgh ijkl mnop"; the real password has no spaces.
      pass: /gmail|googlemail/i.test(process.env.SMTP_HOST ?? "")
        ? process.env.SMTP_PASS?.replace(/\s+/g, "")
        : process.env.SMTP_PASS,
    },
  });
}

function itemsTable(o: OrderEmailData): string {
  const rows = o.items
    .map(
      (i) => `
      <tr>
        <td style="padding:8px 0;border-bottom:1px solid #eef5ea;color:#1c2b20">
          ${escape(i.name)} <span style="color:#5b6b7c">× ${i.quantity}</span>
        </td>
        <td style="padding:8px 0;border-bottom:1px solid #eef5ea;text-align:right;color:#1c2b20">
          ${formatPrice(i.price * i.quantity)}
        </td>
      </tr>`
    )
    .join("");

  return `
    <table style="width:100%;border-collapse:collapse;font-size:14px">
      ${rows}
      <tr><td style="padding:8px 0;color:#5b6b7c">Subtotal</td><td style="padding:8px 0;text-align:right;color:#1c2b20">${formatPrice(o.subtotal)}</td></tr>
      <tr><td style="padding:8px 0;color:#5b6b7c">Delivery</td><td style="padding:8px 0;text-align:right;color:#1c2b20">${o.shipping === 0 ? "Gratis" : formatPrice(o.shipping)}</td></tr>
      <tr><td style="padding:12px 0 0;font-weight:700;color:#1c2b20">Total</td><td style="padding:12px 0 0;text-align:right;font-weight:700;color:#1c2b20">${formatPrice(o.total)}</td></tr>
    </table>`;
}

function shell(title: string, inner: string): string {
  return `
  <div style="background:#eef6e4;padding:24px;font-family:Arial,Helvetica,sans-serif">
    <div style="max-width:560px;margin:0 auto;background:#fbfcfe;border:1px solid #dcecc6;border-radius:12px;overflow:hidden">
      <div style="background:#4c8a23;padding:22px;text-align:center">
        <div style="color:#ffcc04;font-size:24px;letter-spacing:6px;font-weight:700">Inbramet</div>
        <div style="color:#d8e8c4;font-size:13px;margin-top:4px">Comida típica cruceña · Desde 2026</div>
      </div>
      <div style="padding:28px">
        <h1 style="margin:0 0 8px;color:#101820;font-size:22px">${title}</h1>
        ${inner}
      </div>
      <div style="background:#4c8a23;padding:16px;text-align:center;color:#d8e8c4;font-size:12px">
        Inbramet · Brasil, Brasil
      </div>
    </div>
  </div>`;
}

function customerHtml(o: OrderEmailData): string {
  return shell(
    "¡Gracias por tu pedido!",
    `<p style="color:#1c2b20;font-size:14px">Hola ${escape(o.customerName)}, recibimos tu pedido y nuestro equipo se pondrá en contacto contigo en breve.</p>
     <p style="color:#1c2b20;font-size:14px">Número de pedido: <strong>${escape(o.orderNumber)}</strong><br/>
     Pago: <strong>${escape(o.paymentMethod)}</strong></p>
     <div style="margin:18px 0">${itemsTable(o)}</div>
     <p style="color:#5b6b7c;font-size:13px">Entrega en: ${escape(o.address)}, ${escape(o.city)}<br/>Teléfono: ${escape(o.phone)}</p>
     ${o.paymentMethod === "COD" ? `<p style="color:#5b6b7c;font-size:13px">Si elegiste pago contra entrega, ten el monto listo al recibir tu pedido.</p>` : ""}`
  );
}

function adminHtml(o: OrderEmailData): string {
  return shell(
    "Nuevo pedido",
    `<p style="color:#1c2b20;font-size:14px">Pedido <strong>${escape(o.orderNumber)}</strong> — ${formatPrice(o.total)} (${escape(o.paymentMethod)})</p>
     <p style="color:#1c2b20;font-size:14px"><strong>${escape(o.customerName)}</strong><br/>
     ${escape(o.email)} · ${escape(o.phone)}<br/>
     ${escape(o.address)}, ${escape(o.city)}</p>
     <div style="margin:18px 0">${itemsTable(o)}</div>`
  );
}

function escape(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

// Sends confirmation to the customer + notification to the store owner.
// Never throws — email failures must not break checkout.
export async function sendOrderEmails(o: OrderEmailData): Promise<void> {
  if (!emailConfigured()) {
    console.warn("[email] SMTP not configured — skipping order emails.");
    return;
  }

  const from = process.env.MAIL_FROM || `Inbramet <${process.env.SMTP_USER}>`;
  const adminTo = await alertAddress();

  try {
    const transport = getTransport();
    await Promise.all([
      transport.sendMail({
        from,
        to: o.email,
        subject: `Tu pedido en Inbramet ${o.orderNumber}`,
        html: customerHtml(o),
      }),
      transport.sendMail({
        from,
        to: adminTo,
        subject: `Nuevo pedido ${o.orderNumber} — ${formatPrice(o.total)}`,
        html: adminHtml(o),
      }),
    ]);
  } catch (err) {
    console.error("[email] Failed to send order emails:", err);
  }
}

// Password-reset link for a storefront customer. Never throws.
export async function sendPasswordResetEmail(p: { to: string; name: string; url: string }): Promise<void> {
  if (!emailConfigured()) {
    console.warn("[email] SMTP not configured — password reset email not sent.");
    return;
  }
  const from = process.env.MAIL_FROM || `Inbramet <${process.env.SMTP_USER}>`;
  try {
    await getTransport().sendMail({
      from,
      to: p.to,
      subject: "Restablece tu contraseña de Inbramet",
      html: shell(
        "Restablece tu contraseña",
        `<p style="color:#1c2b20;font-size:14px">Hola ${escape(p.name)}, recibimos una solicitud para restablecer tu contraseña.</p>
         <p style="margin:22px 0"><a href="${escape(p.url)}" style="background:#4c8a23;color:#f6f3e8;padding:12px 22px;border-radius:999px;text-decoration:none;font-size:14px">Elegir nueva contraseña</a></p>
         <p style="color:#5b6b7c;font-size:13px">Este enlace vence en 1 hora y se puede usar una sola vez. Si no lo solicitaste, puedes ignorar este correo.</p>`
      ),
    });
  } catch (err) {
    console.error("[email] Failed to send password reset email:", err);
  }
}

// Alerts the store owner about a contact-form message. Never throws.
export async function sendContactNotification(m: {
  name: string;
  email: string;
  phone?: string;
  subject?: string;
  message: string;
  topic?: string;
}): Promise<void> {
  if (!emailConfigured()) return; // message is still saved in the admin "Messages" page
  const from = process.env.MAIL_FROM || `Inbramet <${process.env.SMTP_USER}>`;
  const to = await alertAddress();
  try {
    await getTransport().sendMail({
      from,
      to,
      replyTo: m.email,
      subject: `Nuevo mensaje: ${m.subject || m.topic || "Formulario de contacto"} — ${m.name}`,
      html: shell(
        "Nuevo mensaje de contacto",
        `<p style="color:#1c2b20;font-size:14px"><strong>${escape(m.name)}</strong> · ${escape(m.email)}${
          m.phone ? ` · ${escape(m.phone)}` : ""
        }</p>
         ${m.subject ? `<p style="color:#1c2b20;font-size:14px"><strong>${escape(m.subject)}</strong></p>` : ""}
         <p style="color:#1c2b20;font-size:14px;white-space:pre-wrap">${escape(m.message)}</p>`
      ),
    });
  } catch (err) {
    console.error("[email] Failed to send contact notification:", err);
  }
}

// One-time verification code (sign-up / email verification).
// Without SMTP: in development the code is printed to the server console so the
// flow can be tested; in production sending fails (sign-up can't be verified).
export async function sendOtpEmail(
  to: string,
  code: string,
  purpose: "register" | "verify"
): Promise<{ ok: true } | { ok: false; error: string }> {
  if (!emailConfigured()) {
    if (process.env.NODE_ENV !== "production") {
      console.warn(`\n[email] SMTP not configured — DEV ONLY verification code for ${to}: ${code}\n`);
      return { ok: true };
    }
    console.error("[email] SMTP not configured — cannot send verification code");
    return { ok: false, error: "No podemos enviar correos de verificación ahora. Intenta más tarde o contáctanos." };
  }
  const from = process.env.MAIL_FROM || `Inbramet <${process.env.SMTP_USER}>`;
  const spaced = code.split("").join(" ");
  const title = purpose === "register" ? "Confirma tu correo" : "Verifica tu correo";
  try {
    await getTransport().sendMail({
      from,
      to,
      subject: `${code} es tu código de verificación de Inbramet`,
      text: `Tu código de verificación de Inbramet es ${code}. Vence en 10 minutos. Si no lo solicitaste, puedes ignorar este correo.`,
      html: shell(
        title,
        `<p style="color:#1c2b20;font-size:14px">Usa este código para ${
          purpose === "register" ? "terminar de crear tu cuenta de Inbramet" : "verificar tu correo electrónico"
        }:</p>
         <p style="margin:22px 0;text-align:center">
           <span style="display:inline-block;background:#f6f3e8;border:1px solid #ef7d06;border-radius:10px;padding:14px 22px;font-size:30px;font-weight:700;letter-spacing:8px;color:#4c8a23;font-family:'Courier New',monospace">${escape(spaced)}</span>
         </p>
         <p style="color:#5b6b7c;font-size:13px">Este código vence en <strong>10 minutos</strong>. No lo compartas con nadie — Inbramet nunca te lo pedirá por teléfono ni WhatsApp.</p>
         <p style="color:#5b6b7c;font-size:13px">Si no intentaste registrarte, puedes ignorar este correo.</p>`
      ),
    });
    return { ok: true };
  } catch (err) {
    console.error("[email] Failed to send verification code:", err);
    // Only a rejected recipient is the shopper's to fix; login / connection
    // failures (e.g. a revoked Gmail App Password) are ours.
    const e = err as { code?: string; responseCode?: number; rejected?: string[] };
    const badRecipient = e.code === "EENVELOPE" || Boolean(e.rejected?.length) || (e.responseCode ?? 0) === 550;
    return {
      ok: false,
      error: badRecipient
        ? "No pudimos enviar el código a esa dirección. Revisa tu correo e inténtalo de nuevo."
        : "No podemos enviar correos de verificación ahora. Intenta en un momento o contáctanos.",
    };
  }
}
import type { ProductFilters } from "./types";

type RawParams = Record<string, string | string[] | undefined>;

function first(v: string | string[] | undefined): string | undefined {
  return Array.isArray(v) ? v[0] : v;
}

function num(v: string | string[] | undefined): number | undefined {
  const s = first(v);
  if (s == null || s === "") return undefined;
  const n = Number(s);
  return Number.isFinite(n) && n >= 0 ? n : undefined;
}

// Turns URL search params into a validated ProductFilters object.
export function parseProductFilters(sp: RawParams): ProductFilters {
  const sortRaw = first(sp.sort);
  const sort =
    sortRaw === "price-asc" || sortRaw === "price-desc" || sortRaw === "newest"
      ? sortRaw
      : "newest";

  let minPrice = num(sp.minPrice);
  let maxPrice = num(sp.maxPrice);
  // A reversed range (min > max) would match nothing — treat it as swapped.
  if (minPrice != null && maxPrice != null && minPrice > maxPrice) {
    [minPrice, maxPrice] = [maxPrice, minPrice];
  }

  return {
    q: first(sp.q)?.trim().slice(0, 100) || undefined,
    material: first(sp.material),
    minPrice,
    maxPrice,
    onSale: first(sp.sale) === "1" || undefined,
    inStock: first(sp.stock) === "1" || undefined,
    sort,
  };
}
// Money is in Brasiln Pesos. Clean, no-decimal display: "Bs 48,000".
const bo = new Intl.NumberFormat("es-BO", { maximumFractionDigits: 0 });

export function formatPrice(amount: number): string {
  return `Bs ${bo.format(Math.round(amount))}`;
}

/** Legacy `material` field from the old catalog is sometimes a filler string. */
export function visiblePack(material: string | null | undefined): string | null {
  if (!material || /f[oó]rmula|matem[aá]tica/i.test(material)) return null;
  return material;
}

export function discountPercent(price: number, compareAt: number | null | undefined): number | null {
  if (!compareAt || compareAt <= price) return null;
  return Math.round(((compareAt - price) / compareAt) * 100);
}

/** Saved per product vs the compare-at price, or null when not on sale. */
export function savingsOf(price: number, compareAt: number | null | undefined): number | null {
  if (!compareAt || compareAt <= price) return null;
  return compareAt - price;
}

/** "12 Oct 2026" (or "12 Oct" with `year: false`, plus "3:05 pm" with `time: true`). */
export function formatDate(
  date: Date | string,
  { year = true, time = false }: { year?: boolean; time?: boolean } = {}
): string {
  const d = typeof date === "string" ? new Date(date) : date;
  const opts: Intl.DateTimeFormatOptions = { day: "numeric", month: "short" };
  if (year) opts.year = "numeric";
  if (time) Object.assign(opts, { hour: "numeric", minute: "2-digit" });
  return time ? d.toLocaleString("es-BO", opts) : d.toLocaleDateString("es-BO", opts);
}
export type Coords = { latitude: number; longitude: number; accuracy?: number };

export function distanceKm(a: Coords, b: Coords): number {
  const R = 6371;
  const rad = (d: number) => (d * Math.PI) / 180;
  const dLat = rad(b.latitude - a.latitude);
  const dLon = rad(b.longitude - a.longitude);
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(rad(a.latitude)) * Math.cos(rad(b.latitude)) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}

export function formatDistance(km: number): string {
  if (km < 1) return `${Math.max(50, Math.round((km * 1000) / 50) * 50)} m`;
  return `${km.toFixed(1)} km`;
}

export function sortByDistance<T extends Coords>(items: T[], from: Coords) {
  return items
    .map((item) => ({ item, distance: distanceKm(from, item) }))
    .sort((a, b) => a.distance - b.distance);
}

/** Browser geolocation with high accuracy; resolves null instead of throwing. */
export function getBrowserLocation(timeout = 12000): Promise<Coords | null> {
  if (typeof navigator === "undefined" || !("geolocation" in navigator)) {
    return Promise.resolve(null);
  }
  return new Promise((resolve) => {
    navigator.geolocation.getCurrentPosition(
      (position) =>
        resolve({
          latitude: position.coords.latitude,
          longitude: position.coords.longitude,
          accuracy: position.coords.accuracy,
        }),
      () => resolve(null),
      { enableHighAccuracy: true, timeout, maximumAge: 0 }
    );
  });
}
import { emailError, phoneError } from "./auth-rules";
import { PIECE_TYPES, FINISHES, BUDGETS } from "./custom-request";

// Field rules for the event-order and Contact forms: checked live in the
// browser and enforced again by the server actions (inbound-actions.ts).

type Validators = Record<string, (value: string) => string | null>;

/** 5–10 letters (A–Z), single spaces between words allowed. */
export const PERSON_NAME_RE = /^[A-Za-z]+(?: [A-Za-z]+)*$/;

export function personNameError(value: string): string | null {
  const v = value.trim();
  if (!v) return "Ingresa tu nombre";
  if (!PERSON_NAME_RE.test(v)) return /\s{2,}/.test(v) ? "Usa un solo espacio entre palabras" : "Usa solo letras (A–Z)";
  const letters = v.replace(/ /g, "").length;
  if (letters < 5) return "El nombre necesita al menos 5 letras";
  if (letters > 10) return "El nombre puede tener máximo 10 letras";
  return null;
}

const oneOf = (options: readonly string[], message: string) => (v: string) => (options.includes(v) ? null : message);
const optional = (rule: (v: string) => string | null) => (v: string) => (v.trim() ? rule(v) : null);
const maxLen = (n: number, message: string) => (v: string) => (v.trim().length > n ? message : null);
const textBetween = (min: number, max: number, short: string) => (v: string) => {
  const t = v.trim();
  if (t.length < min) return short;
  if (t.length > max) return `Máximo ${max.toLocaleString("es-BO")} caracteres`;
  return null;
};

export const CUSTOM_VALIDATORS: Validators = {
  name: personNameError,
  email: emailError,
  phone: phoneError,
  pieceType: oneOf(PIECE_TYPES, "Elige qué necesitas"),
  finish: oneOf(FINISHES, "Elige un formato"),
  budget: oneOf(BUDGETS, "Elige un presupuesto"),
  neededBy: maxLen(60, "Máximo 60 caracteres"),
  details: textBetween(10, 3000, "Cuéntanos un poco sobre tu pedido (al menos una frase)"),
};

export const CONTACT_VALIDATORS: Validators = {
  name: personNameError,
  email: emailError,
  phone: optional(phoneError),
  subject: maxLen(200, "Máximo 200 caracteres"),
  message: textBetween(5, 5000, "Escribe un mensaje breve (al menos 5 caracteres)"),
};

/** Runs the rules over submitted values: the bad fields (in form order) and the first message. */
export function checkFields(rules: Validators, values: Record<string, string>) {
  const fields = Object.keys(rules).filter((k) => rules[k](values[k] ?? ""));
  return fields.length ? { fields, error: rules[fields[0]](values[fields[0]] ?? "")! } : null;
}
// Pure loyalty rules — client-safe (no Prisma, no server imports) so the
// checkout form, the Club page and the admin preview all compute the same
// numbers from the same stored settings.
//
// Two currencies, both stored as signed deltas in an append-only ledger:
//  · stamps → belong to one product; a full card redeems that same product.
//  · points → pooled; spent in the rewards shop.

import type { LoyaltySettings } from "./settings-shared";

/** What the rules need to know about one cart line. */
export type LoyaltyLine = {
  productId: string;
  productSlug: string;
  categorySlug: string;
  quantity: number;
};

export function stampEligible(
  line: Pick<LoyaltyLine, "productSlug" | "categorySlug">,
  rules: LoyaltySettings
): boolean {
  if (!rules.enabled) return false;
  if (rules.eligible === "all") return true;
  const slug = rules.eligible === "category" ? line.categorySlug : line.productSlug;
  return rules.eligibleSlugs.includes(slug);
}

/**
 * Stamps a line earns: one per unit, but never past a full card — an
 * 11th stamp would otherwise be thrown away on the next purchase.
 */
export function stampsForLine(
  line: Pick<LoyaltyLine, "quantity">,
  rules: LoyaltySettings,
  ownedForProduct: number
): number {
  const remaining = Math.max(0, rules.stampsToFree - ownedForProduct);
  return Math.min(line.quantity, remaining);
}

/** Bs spent × points rate. Only counts delivery when the owner opted in. */
export function pointsForOrder(
  amounts: { subtotal: number; shipping: number },
  rules: LoyaltySettings
): number {
  if (!rules.enabled || rules.pointsAmount <= 0 || rules.pointsPer <= 0) return 0;
  const spend = amounts.subtotal + (rules.pointsOnShipping ? amounts.shipping : 0);
  return Math.floor(spend / rules.pointsAmount) * rules.pointsPer;
}

export type StampCard = {
  size: number;
  filled: number;
  remaining: number;
  full: boolean;
};

export function stampCard(owned: number, rules: LoyaltySettings): StampCard {
  // The card size follows the current rule even if a card was filled under an
  // older, bigger one — the stamps stay valid, they just need fewer to redeem.
  const size = Math.max(1, rules.stampsToFree);
  const filled = Math.min(Math.max(0, owned), size);
  return { size, filled, remaining: Math.max(0, size - owned), full: owned >= size };
}

/** Whole-line preview used by the checkout UI and by the accrual itself. */
export function previewLoyalty(
  lines: LoyaltyLine[],
  amounts: { subtotal: number; shipping: number },
  rules: LoyaltySettings,
  ownedStamps: Record<string, number> = {}
): { stampsByProduct: Record<string, number>; stamps: number; points: number } {
  const stampsByProduct: Record<string, number> = {};
  let stamps = 0;
  if (rules.enabled) {
    const earned: Record<string, number> = {};
    for (const line of lines) {
      if (!stampEligible(line, rules)) continue;
      // Multiple lines can point at the same product; cap on the running total.
      const pool = (ownedStamps[line.productId] ?? 0) + (earned[line.productId] ?? 0);
      const got = stampsForLine(line, rules, pool);
      if (got > 0) {
        earned[line.productId] = (earned[line.productId] ?? 0) + got;
        stamps += got;
      }
    }
    for (const [id, n] of Object.entries(earned)) if (n > 0) stampsByProduct[id] = n;
  }
  return { stampsByProduct, stamps, points: pointsForOrder(amounts, rules) };
}

/** What the cart on screen means for the programme (checkout preview payload). */
export type LoyaltyCartPreview = {
  ok: true;
  enabled: boolean;
  name: string;
  stampsToFree: number;
  points: number;
  stamps: number;
  balance: { points: number; stamps: number };
  cards: { productId: string; name: string; filled: number; size: number }[];
  redeemable: { productId: string; name: string; price: number }[];
};

/** "10 sellos = 1 gratis" phrasing used across the store. */
export function stampRuleLabel(rules: LoyaltySettings): string {
  const n = rules.stampsToFree;
  return `${n === 1 ? "1 sello" : `${n} sellos`} = 1 producto gratis`;
}

export function pointRuleLabel(rules: LoyaltySettings): string {
  const bs = new Intl.NumberFormat("es-BO", { maximumFractionDigits: 0 }).format(rules.pointsAmount);
  const pts = rules.pointsPer === 1 ? "1 punto" : `${rules.pointsPer} puntos`;
  return `${pts} por cada Bs ${bs} de compra`;
}

/** Spanish label for one ledger entry; used by the club page and the admin panel. */
export function movementLabel(h: {
  kind: string;
  product: { name: string } | null;
  reward: { name: string } | null;
  order: { orderNumber: string } | null;
  note: string | null;
}): string {
  switch (h.kind) {
    case "STAMP":
      return `Pedido ${h.order?.orderNumber ?? ""} — ${h.product?.name ?? "producto"}`;
    case "POINT":
      return `Compra ${h.order?.orderNumber ?? ""}`;
    case "REDEEM_STAMP":
      return `Canje de ${h.product?.name ?? "un producto"} gratis`;
    case "REDEEM_PRIZE":
      return `Regalo canjeado: ${h.reward?.name ?? ""}`;
    case "REFUND":
      return `Pedido cancelado ${h.order?.orderNumber ?? ""}`;
    default:
      return h.note ?? "Ajuste";
  }
}

import { randomInt } from "node:crypto";
import type { Prisma } from "@prisma/client";
import { prisma } from "./prisma";
import type { LoyaltySettings } from "./settings-shared";
import { previewLoyalty, stampCard, type LoyaltyLine } from "./loyalty-shared";

// Server side of Club Camba. The ledger (LoyaltyEntry) is append-only and holds
// signed deltas, so a balance is always the sum of its rows: earning, spending,
// refunds and manual corrections are all just new rows. Nothing is ever
// rewritten, which keeps customer disputes answerable.

export type LoyaltyBalances = {
  /** Pooled points available for the rewards shop. */
  points: number;
  /** Stamps per product id — each product carries its own card. */
  stampsByProduct: Record<string, number>;
  /** Products whose card is currently full. */
  readyForRedemption: string[];
  totalStamps: number;
};

/** A spend the customer isn't entitled to — safe to show verbatim. */
class LoyaltySpendError extends Error {}

/** Rows older than the expiry window are ignored (never deleted). */
function withinWindow(createdAt: Date, expiryDays: number, now: number): boolean {
  if (!expiryDays || expiryDays <= 0) return true;
  return now - createdAt.getTime() <= expiryDays * 86_400_000;
}

export async function getBalances(
  customerId: string,
  rules: LoyaltySettings
): Promise<LoyaltyBalances> {
  const rows = await prisma.loyaltyEntry.findMany({
    where: { customerId },
    select: { stamps: true, points: true, productId: true, createdAt: true },
  });
  const now = Date.now();
  const stampsByProduct: Record<string, number> = {};
  let points = 0;
  let totalStamps = 0;
  for (const r of rows) {
    if (!withinWindow(r.createdAt, rules.expiryDays, now)) continue;
    if (r.points) points += r.points;
    if (r.stamps) {
      totalStamps += r.stamps;
      const key = r.productId ?? "";
      stampsByProduct[key] = (stampsByProduct[key] ?? 0) + r.stamps;
    }
  }
  const full = Math.max(1, rules.stampsToFree);
  const readyForRedemption = Object.entries(stampsByProduct)
    .filter(([id, n]) => id !== "" && n >= full)
    .map(([id]) => id);
  return { points, stampsByProduct, readyForRedemption, totalStamps };
}

/** The signed sum of a customer's rows for one kind — used to guard spends. */
async function balanceOf(
  tx: Prisma.TransactionClient,
  customerId: string,
  field: "points" | "stamps",
  productId?: string
): Promise<number> {
  const res = await tx.loyaltyEntry.aggregate({
    where: { customerId, ...(productId ? { productId } : {}) },
    _sum: { [field]: true },
  });
  return res._sum[field] ?? 0;
}

/**
 * Adds the stamps + points one order earned. Called inside the checkout
 * transaction, after the order row exists, so a rolled back order never pays out.
 */
export async function accrueOrder(
  tx: Prisma.TransactionClient,
  input: {
    orderId: string;
    customerId: string;
    lines: LoyaltyLine[];
    amounts: { subtotal: number; shipping: number };
    rules: LoyaltySettings;
    ownedStamps: Record<string, number>;
  }
): Promise<{ stamps: number; points: number }> {
  const preview = previewLoyalty(input.lines, input.amounts, input.rules, input.ownedStamps);
  for (const [productId, stamps] of Object.entries(preview.stampsByProduct)) {
    await tx.loyaltyEntry.create({
      data: {
        customerId: input.customerId,
        orderId: input.orderId,
        productId,
        kind: "STAMP",
        stamps,
      },
    });
  }
  if (preview.points > 0) {
    await tx.loyaltyEntry.create({
      data: {
        customerId: input.customerId,
        orderId: input.orderId,
        kind: "POINT",
        points: preview.points,
      },
    });
  }
  return { stamps: preview.stamps, points: preview.points };
}

/**
 * Spends a full card for one product. Throws if the card isn't full — the
 * caller must also make the matching unit free on the order.
 */
export async function redeemStamps(
  tx: Prisma.TransactionClient,
  input: { customerId: string; productId: string; orderId?: string; rules: LoyaltySettings }
): Promise<void> {
  const owned = await balanceOf(tx, input.customerId, "stamps", input.productId);
  const card = stampCard(owned, input.rules);
  if (!card.full)
    throw new LoyaltySpendError(
      `Te faltan ${card.remaining} sellos para canjear este producto.`
    );
  await tx.loyaltyEntry.create({
    data: {
      customerId: input.customerId,
      productId: input.productId,
      orderId: input.orderId,
      kind: "REDEEM_STAMP",
      stamps: -input.rules.stampsToFree,
    },
  });
}

// Redemption codes are handed to the branch at pickup, so they stay short and
// unreadable-by-accident (same no-0/O/1/I/L alphabet as order numbers).
const REDEEM_ALPHABET = "23456789ABCDEFGHJKMNPQRSTUVWXYZ";

function generateRedemptionCode(): string {
  let code = "";
  for (let i = 0; i < 6; i++) code += REDEEM_ALPHABET[randomInt(REDEEM_ALPHABET.length)];
  return code;
}

export type RedeemResult = { ok: true; code: string } | { ok: false; error: string };

/** Buys a rewards-shop prize with points. One unit per call. */
export async function redeemReward(input: {
  customerId: string;
  rewardId: string;
  branchId?: string | null;
  rules: LoyaltySettings;
}): Promise<RedeemResult> {
  if (!input.rules.enabled) return { ok: false, error: "El programa de puntos está pausado." };
  for (let attempt = 0; attempt < 4; attempt++) {
    const code = generateRedemptionCode();
    try {
      return await prisma.$transaction(async (tx) => {
        const reward = await tx.reward.findFirst({
          where: { id: input.rewardId, active: true },
          select: { id: true, name: true, costPoints: true, stock: true },
        });
        if (!reward) return { ok: false, error: "Este regalo ya no está disponible." };
        if (reward.stock <= 0)
          return { ok: false, error: `"${reward.name}" está agotado por ahora.` };

        // Conditional decrement, same trick as branch stock: two taps can't
        // spend the same points twice.
        await tx.loyaltyEntry.create({
          data: {
            customerId: input.customerId,
            rewardId: reward.id,
            kind: "REDEEM_PRIZE",
            points: -reward.costPoints,
          },
        });
        const balance = await balanceOf(tx, input.customerId, "points");
        if (balance < 0) throw new LoyaltySpendError("No te alcanzan los puntos para este regalo.");
        const stock = await tx.reward.updateMany({
          where: { id: reward.id, stock: { gt: 0 } },
          data: { stock: { decrement: 1 } },
        });
        if (stock.count !== 1) throw new LoyaltySpendError(`"${reward.name}" está agotado por ahora.`);

        await tx.redemption.create({
          data: {
            code,
            customerId: input.customerId,
            rewardId: reward.id,
            rewardName: reward.name,
            costPoints: reward.costPoints,
            branchId: input.branchId ?? null,
          },
        });
        return { ok: true as const, code };
      });
    } catch (err) {
      if (err instanceof LoyaltySpendError) return { ok: false, error: err.message };
      const msg = err instanceof Error ? err.message : "";
      // Only a code collision is worth retrying; anything else is a real failure.
      if (/P2002|Unique constraint/i.test(msg) && /code/.test(msg)) continue;
      console.error("[loyalty] reward redemption failed:", err);
      return { ok: false, error: "No pudimos registrar el canje. Inténtalo de nuevo." };
    }
  }
  return { ok: false, error: "No pudimos registrar el canje. Inténtalo de nuevo." };
}

/**
 * Reverses everything an order earned (cancelled/refunded orders). Idempotent:
 * a second call for the same order writes nothing. A card spent on that order's
 * free product comes back too.
 *
 * A reversal never takes away stamps or points the customer already spent: the
 * ledger can end at zero, never below, so cancelling an old order cannot leave a
 * negative balance behind.
 */
export async function refundOrderLoyalty(orderId: string): Promise<boolean> {
  return prisma.$transaction(async (tx) => {
    const earned = await tx.loyaltyEntry.findMany({
      where: { orderId, kind: { in: ["STAMP", "POINT", "REDEEM_STAMP"] } },
      select: { customerId: true, productId: true, kind: true, stamps: true, points: true },
    });
    if (earned.length === 0) return false;
    const already = await tx.loyaltyEntry.count({ where: { orderId, kind: "REFUND" } });
    if (already > 0) return false;
    for (const e of earned) {
      let stamps = -e.stamps;
      let points = -e.points;
      // Only the debits need a floor: a refund may not push a spent balance
      // further down than what the customer still has.
      if (e.stamps > 0) {
        const left = await balanceOf(tx, e.customerId, "stamps", e.productId ?? undefined);
        stamps = -Math.min(e.stamps, Math.max(0, left));
      }
      if (e.points > 0) {
        const left = await balanceOf(tx, e.customerId, "points");
        points = -Math.min(e.points, Math.max(0, left));
      }
      await tx.loyaltyEntry.create({
        data: {
          customerId: e.customerId,
          productId: e.productId,
          orderId,
          kind: "REFUND",
          stamps,
          points,
          note:
            stamps === -e.stamps && points === -e.points
              ? null
              : "Reverso parcial: parte del saldo ya estaba canjeada.",
        },
      });
    }
    return true;
  });
}

/** Admin correction: credit or debit either currency with a note. */
export async function adjustBalance(input: {
  customerId: string;
  stamps?: number;
  points?: number;
  productId?: string | null;
  note: string;
}): Promise<void> {
  const stamps = Math.trunc(input.stamps ?? 0);
  const points = Math.trunc(input.points ?? 0);
  if (stamps === 0 && points === 0) return;
  await prisma.loyaltyEntry.create({
    data: {
      customerId: input.customerId,
      productId: input.productId ?? null,
      kind: "ADJUST",
      stamps,
      points,
      note: input.note.trim() || "Ajuste manual",
    },
  });
}

/** What one order moved on the ledger, for the confirmation screen. */
export async function orderLoyalty(
  orderId: string
): Promise<{ stamps: number; points: number; redeemed: boolean }> {
  try {
    const rows = await prisma.loyaltyEntry.findMany({
      where: { orderId },
      select: { kind: true, stamps: true, points: true },
    });
    let stamps = 0;
    let points = 0;
    let redeemed = false;
    for (const r of rows) {
      if (r.kind === "STAMP") stamps += r.stamps;
      else if (r.kind === "POINT") points += r.points;
      else if (r.kind === "REDEEM_STAMP") redeemed = true;
    }
    return { stamps, points, redeemed };
  } catch {
    return { stamps: 0, points: 0, redeemed: false };
  }
}

/** Ledger newest-first, with the names the customer needs to recognise rows. */
export async function getHistory(customerId: string, take = 30) {
  return prisma.loyaltyEntry.findMany({
    where: { customerId },
    orderBy: { createdAt: "desc" },
    take,
    select: {
      id: true,
      kind: true,
      stamps: true,
      points: true,
      note: true,
      createdAt: true,
      product: { select: { name: true, slug: true } },
      reward: { select: { name: true } },
      order: { select: { orderNumber: true } },
    },
  });
}
import { prisma } from "./prisma";

export type OrderLookupItem = { name: string; quantity: number; price: number };

export type OrderLookupResult =
  | {
      ok: true;
      order: {
        orderNumber: string;
        status: string;
        paymentStatus: string;
        paymentMethod: string;
        total: number;
        createdAt: string;
        courier: string | null;
        trackingNumber: string | null;
        items: OrderLookupItem[];
      };
    }
  | { ok: false; reason: "not-found" | "db-down" };

// Looks up an order by its number + the email used at checkout.
export async function lookupOrder(
  orderNumber: string,
  email: string
): Promise<OrderLookupResult> {
  try {
    const o = await prisma.order.findFirst({
      where: {
        orderNumber: orderNumber.trim(),
        // Older orders stored the email as typed — match case-insensitively.
        email: { equals: email.trim(), mode: "insensitive" },
      },
      include: { items: true },
    });
    if (!o) return { ok: false, reason: "not-found" };
    return {
      ok: true,
      order: {
        orderNumber: o.orderNumber,
        status: o.status,
        paymentStatus: o.paymentStatus,
        paymentMethod: o.paymentMethod,
        total: Number(o.total),
        createdAt: o.createdAt.toISOString(),
        courier: o.courier,
        trackingNumber: o.trackingNumber,
        items: o.items.map((i) => ({
          name: i.name,
          quantity: i.quantity,
          price: Number(i.price),
        })),
      },
    };
  } catch {
    return { ok: false, reason: "db-down" };
  }
}
import { prisma } from "./prisma";
import { cancelOrderAndRestock } from "./orders";

// Applies a verified gateway result to an order (by order number).
// Idempotent and state-guarded:
//  - success: only PENDING/FAILED payments become PAID; a PENDING order becomes
//    CONFIRMED. Cancelled/shipped orders keep their status (admin can refund).
//  - failure: only a PENDING payment becomes FAILED, and the unpaid order is
//    cancelled with its stock restored so the shopper can simply retry.
//  - amount (when the gateway reports it) must match the order total.
export async function markOrderPayment(
  orderNumber: string,
  paid: boolean,
  amount?: number | null
): Promise<boolean> {
  try {
    const order = await prisma.order.findUnique({
      where: { orderNumber },
      select: { id: true, total: true, status: true, paymentStatus: true, paymentMethod: true },
    });
    if (!order || order.paymentMethod === "COD") return false;

    if (paid) {
      if (amount != null && Math.abs(Number(order.total) - amount) > 1) {
        console.error(`[payment] amount mismatch for ${orderNumber}: got ${amount}, expected ${order.total}`);
        return false;
      }
      if (order.paymentStatus === "PAID") return true; // duplicate notification
      const res = await prisma.order.updateMany({
        where: { id: order.id, paymentStatus: { in: ["PENDING", "FAILED"] } },
        data: { paymentStatus: "PAID" },
      });
      await prisma.order.updateMany({
        where: { id: order.id, status: "PENDING" },
        data: { status: "CONFIRMED" },
      });
      return res.count === 1;
    }

    if (order.paymentStatus !== "PENDING") return true; // already resolved
    const res = await prisma.order.updateMany({
      where: { id: order.id, paymentStatus: "PENDING" },
      data: { paymentStatus: "FAILED" },
    });
    if (res.count === 1) await cancelOrderAndRestock(order.id);
    return true;
  } catch (err) {
    console.error("[payment] could not update order:", err);
    return false;
  }
}
// Plain constants (safe to import anywhere — not a "use server" module).
export const ORDER_STATUSES = [
  "PENDING",
  "CONFIRMED",
  "PROCESSING",
  "SHIPPED",
  "DELIVERED",
  "CANCELLED",
] as const;

export const PAYMENT_STATUSES = ["PENDING", "PAID", "FAILED", "REFUNDED"] as const;

export type OrderStatus = (typeof ORDER_STATUSES)[number];
export type PaymentStatus = (typeof PAYMENT_STATUSES)[number];

// Allowed order-status moves. DELIVERED and CANCELLED are final (cancelling
// restores stock, so un-cancelling would double-count inventory).
export const ORDER_TRANSITIONS: Record<OrderStatus, readonly OrderStatus[]> = {
  PENDING: ["CONFIRMED", "PROCESSING", "SHIPPED", "CANCELLED"],
  CONFIRMED: ["PENDING", "PROCESSING", "SHIPPED", "CANCELLED"],
  PROCESSING: ["CONFIRMED", "SHIPPED", "CANCELLED"],
  SHIPPED: ["DELIVERED", "CANCELLED"],
  DELIVERED: [],
  CANCELLED: [],
};

export const PAYMENT_TRANSITIONS: Record<PaymentStatus, readonly PaymentStatus[]> = {
  PENDING: ["PAID", "FAILED"],
  FAILED: ["PENDING", "PAID"],
  PAID: ["REFUNDED"],
  REFUNDED: [],
};

export function canMoveOrder(from: OrderStatus, to: OrderStatus): boolean {
  return ORDER_TRANSITIONS[from]?.includes(to) ?? false;
}

export function canMovePayment(from: PaymentStatus, to: PaymentStatus): boolean {
  return PAYMENT_TRANSITIONS[from]?.includes(to) ?? false;
}

export const PAYMENT_METHOD_LABEL: Record<string, string> = {
  COD: "Pago contra entrega",
  PAYFAST: "Tarjeta (PayFast)",
  SAFEPAY: "Tarjeta / billetera (Safepay)",
};

export const ORDER_STATUS_LABEL: Record<string, string> = {
  PENDING: "Pendiente",
  CONFIRMED: "Confirmado",
  PROCESSING: "En preparación",
  SHIPPED: "Enviado",
  DELIVERED: "Entregado",
  CANCELLED: "Cancelado",
};

export const PAYMENT_STATUS_LABEL: Record<string, string> = {
  PENDING: "Pendiente",
  PAID: "Pagado",
  FAILED: "Fallido",
  REFUNDED: "Reembolsado",
};
import { randomInt } from "node:crypto";
import { z } from "zod";
import { prisma } from "./prisma";
import { shippingFor } from "./settings-shared";
import { getStoreSettings } from "./settings";
import { shippingForBranch } from "./branch";
import { after } from "next/server";
import { sendOrderEmails } from "./email";
import { refreshCatalog } from "./cache-tags";
import { accrueOrder, getBalances, redeemStamps, refundOrderLoyalty } from "./loyalty";
import { stampCard, type LoyaltyLine } from "./loyalty-shared";

export const checkoutSchema = z.object({
  customerName: z.string().trim().min(2, "Ingresa tu nombre completo").max(120),
  email: z.string().trim().email("Ingresa un correo válido").max(200),
  phone: z.string().trim().min(7, "Ingresa un teléfono válido").max(30),
  branchId: z.string().min(1, "Elige la sucursal donde harás tu pedido"),
  fulfillment: z.enum(["DELIVERY", "PICKUP"]).default("DELIVERY"),
  address: z.string().trim().max(500).nullish(),
  city: z.string().trim().max(100).nullish(),
  postalCode: z.string().max(20).nullish(),
  notes: z.string().max(1000).nullish(),
  paymentMethod: z.enum(["COD", "PAYFAST", "SAFEPAY"]),
  /** Product whose full stamp card is being spent on this order (one free unit). */
  redeemProductId: z.string().max(100).nullish(),
  items: z
    .array(
      z.object({
        productId: z.string().max(100),
        name: z.string().max(200),
        price: z.number().nonnegative(),
        quantity: z.number().int().positive().max(99),
      })
    )
    .min(1, "Tu carrito está vacío")
    .max(50),
});

export type CheckoutInput = z.infer<typeof checkoutSchema>;

export type CreateOrderResult =
  | {
      ok: true;
      orderNumber: string;
      total: number;
      /** What Club Camba gave this order (0 when the shopper isn't signed in). */
      loyalty: { stamps: number; points: number; redeemedProduct: string | null };
    }
  | { ok: false; error: string };

// User-facing validation problems (bad cart) vs unexpected server errors.
class OrderValidationError extends Error {}

// Unambiguous alphabet (no 0/O, 1/I/L). 8 crypto-random chars ≈ 40 bits, so
// order numbers can't be guessed (they also act as a lookup key with the email).
const ORDER_ALPHABET = "23456789ABCDEFGHJKMNPQRSTUVWXYZ";

function generateOrderNumber(branchCode: string): string {
  const stamp = Date.now().toString(36).toUpperCase().slice(-6);
  let rand = "";
  for (let i = 0; i < 8; i++) rand += ORDER_ALPHABET[randomInt(ORDER_ALPHABET.length)];
  return `${branchCode}-${stamp}-${rand}`;
}

// Cancels an order exactly once and puts its items back into that branch's stock.
// Safe to call repeatedly — only the call that flips the status restocks.
export async function cancelOrderAndRestock(orderId: string): Promise<boolean> {
  const restocked = await prisma.$transaction(async (tx) => {
    const order = await tx.order.findUnique({
      where: { id: orderId },
      select: { branchId: true, status: true },
    });
    if (!order || order.status === "CANCELLED") return false;
    const res = await tx.order.updateMany({
      where: { id: orderId, status: { not: "CANCELLED" } },
      data: { status: "CANCELLED" },
    });
    if (res.count !== 1) return false;
    const items = await tx.orderItem.findMany({
      where: { orderId },
      select: { productId: true, quantity: true },
    });
    for (const i of items) {
      await tx.branchStock.updateMany({
        where: { branchId: order.branchId, productId: i.productId },
        data: { stock: { increment: i.quantity } },
      });
    }
    return true;
  });
  if (restocked) {
    refreshCatalog();
    // The stamps/points that order granted (and any card it spent) are
    // reversed on the ledger, so a cancelled order neither rewards nor costs.
    await refundOrderLoyalty(orderId).catch((err) =>
      console.error("[loyalty] refund entry failed:", err)
    );
  }
  return restocked;
}

export async function createOrder(
  input: CheckoutInput,
  customerId?: string | null
): Promise<CreateOrderResult> {
  const parsed = checkoutSchema.safeParse(input);
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? "Pedido inválido" };
  }
  const data = parsed.data;

  // Delivery needs a real address; pickup happens at the branch.
  const isPickup = data.fulfillment === "PICKUP";
  const address = data.address?.trim() || null;
  const city = data.city?.trim() || null;
  if (!isPickup && (!address || address.length < 5)) {
    return { ok: false, error: "Ingresa tu dirección de entrega" };
  }
  if (!isPickup && (!city || city.length < 2)) {
    return { ok: false, error: "Ingresa tu ciudad" };
  }

  try {
    const branch = await prisma.branch.findFirst({
      where: { id: data.branchId, active: true },
    });
    if (!branch) {
      throw new OrderValidationError("La sucursal elegida no está disponible. Elige otra.");
    }
    if (isPickup && !branch.pickupEnabled) {
      throw new OrderValidationError("Esta sucursal no ofrece retiro en tienda. Elige otra modalidad.");
    }
    if (!isPickup && !branch.deliveryEnabled) {
      throw new OrderValidationError("Esta sucursal no ofrece entrega a domicilio. Puedes elegir retiro.");
    }

    // Re-price against the database to prevent client-side tampering,
    // validate branch stock, then create the order and decrement stock atomically.
    const ids = data.items.map((i) => i.productId);
    const stocks = await prisma.branchStock.findMany({
      where: { branchId: branch.id, productId: { in: ids }, active: true, product: { active: true } },
      select: {
        productId: true,
        stock: true,
        product: {
          select: {
            id: true,
            name: true,
            price: true,
            slug: true,
            category: { select: { slug: true } },
          },
        },
      },
    });
    const byId = new Map(stocks.map((s) => [s.productId, s]));

    // Merge duplicate lines for the same product so stock checks are per product.
    const qtyById = new Map<string, number>();
    for (const i of data.items) qtyById.set(i.productId, (qtyById.get(i.productId) ?? 0) + i.quantity);

    const lineItems = [...qtyById].map(([productId, quantity]) => {
      const s = byId.get(productId);
      const name = data.items.find((i) => i.productId === productId)?.name ?? "Un producto";
      if (!s)
        throw new OrderValidationError(
          `"${name}" ya no está disponible en esta sucursal. Quítalo de tu carrito e inténtalo de nuevo.`
        );
      if (s.stock < quantity)
        throw new OrderValidationError(
          s.stock <= 0
            ? `"${s.product.name}" está agotado en esta sucursal. Quítalo de tu carrito.`
            : `Solo quedan ${s.stock} de "${s.product.name}" en esta sucursal. Baja la cantidad.`
        );
      return { productId: s.product.id, name: s.product.name, price: Number(s.product.price), quantity };
    });

    let subtotal = lineItems.reduce((s, i) => s + i.price * i.quantity, 0);
    // Shipping rules come from the branch (falling back to store-wide settings).
    const settings = await getStoreSettings();
    const branchView = {
      flatFee: branch.flatFee == null ? null : Number(branch.flatFee),
      freeThreshold: branch.freeThreshold == null ? null : Number(branch.freeThreshold),
    };
    const calcShipping = (base: number) =>
      isPickup ? 0 : shippingFor(base, shippingForBranch(branchView, settings));
    let shipping = calcShipping(subtotal);
    let total = subtotal + shipping;
    const email = data.email.trim().toLowerCase();

    // Only attach a customerId that actually exists — a stale session cookie
    // pointing at a deleted account would otherwise cause a foreign-key error.
    let safeCustomerId: string | null = null;
    if (customerId) {
      const customer = await prisma.customer.findUnique({
        where: { id: customerId },
        select: { id: true },
      });
      safeCustomerId = customer?.id ?? null;
    }

    // ---- Club Camba -------------------------------------------------------
    // A full stamp card makes one unit of *that same product* free. The free
    // unit is priced at 0 as its own line instead of discounting the total, so
    // stock, the receipt and the confirmation email all agree.
    const rules = settings.loyalty;
    let ownedStamps: Record<string, number> = {};
    let redeemed: { productId: string; name: string } | null = null;
    if (rules.enabled && safeCustomerId && data.redeemProductId) {
      const target = lineItems.find((i) => i.productId === data.redeemProductId);
      if (!target)
        throw new OrderValidationError("Elige un producto de tu carrito para usar tus sellos.");
      const balances = await getBalances(safeCustomerId, rules);
      ownedStamps = balances.stampsByProduct;
      const card = stampCard(ownedStamps[target.productId] ?? 0, rules);
      if (!card.full)
        throw new OrderValidationError(
          `Aún te faltan ${card.remaining} sellos de "${target.name}" para canjearla gratis.`
        );
      redeemed = { productId: target.productId, name: target.name };
      ownedStamps[target.productId] = Math.max(0, (ownedStamps[target.productId] ?? 0) - rules.stampsToFree);
      target.quantity -= 1;
      if (target.quantity === 0) lineItems.splice(lineItems.indexOf(target), 1);
      lineItems.push({ productId: target.productId, name: target.name, price: 0, quantity: 1 });
      subtotal = lineItems.reduce((s, i) => s + i.price * i.quantity, 0);
      shipping = calcShipping(subtotal);
      total = subtotal + shipping;
    }

    // Free units never earn stamps, hence the price filter.
    const loyaltyLines: LoyaltyLine[] = lineItems
      .filter((i) => i.price > 0)
      .map((i) => {
        const p = byId.get(i.productId)?.product;
        return {
          productId: i.productId,
          productSlug: p?.slug ?? "",
          categorySlug: p?.category.slug ?? "",
          quantity: i.quantity,
        };
      });
    const noLoyalty = { stamps: 0, points: 0, redeemedProduct: null as string | null };
    let earned = noLoyalty;

    // Decrement stock *conditionally* inside the transaction so two concurrent
    // checkouts can never oversell: the update only matches while enough stock
    // remains at that branch, otherwise the whole order rolls back.
    let orderNumber = "";
    let createdOrder: { id: string; createdAt: Date } | null = null;
    for (let attempt = 0; attempt < 3 && !createdOrder; attempt++) {
      orderNumber = generateOrderNumber(branch.code);
      try {
        createdOrder = await prisma.$transaction(async (tx) => {
          for (const i of lineItems) {
            const res = await tx.branchStock.updateMany({
              where: {
                branchId: branch.id,
                productId: i.productId,
                active: true,
                stock: { gte: i.quantity },
              },
              data: { stock: { decrement: i.quantity } },
            });
            if (res.count !== 1)
              throw new OrderValidationError(
                `"${i.name}" se agotó o quedan menos unidades en esta sucursal. Actualiza tu carrito.`
              );
          }
          const created = await tx.order.create({
            data: {
              orderNumber,
              branchId: branch.id,
              fulfillment: data.fulfillment,
              customerName: data.customerName.trim(),
              email,
              phone: data.phone.trim(),
              address,
              city,
              postalCode: data.postalCode?.trim() || null,
              notes: data.notes?.trim() || null,
              paymentMethod: data.paymentMethod,
              customerId: safeCustomerId,
              subtotal,
              shipping,
              total,
              items: { create: lineItems },
            },
            select: { id: true, createdAt: true },
          });

          // Rewards ride on the same transaction: if the order doesn't commit,
          // neither do its stamps, and a spend can't be half-applied.
          if (safeCustomerId) {
            if (redeemed)
              await redeemStamps(tx, {
                customerId: safeCustomerId,
                productId: redeemed.productId,
                orderId: created.id,
                rules,
              });
            const gained = await accrueOrder(tx, {
              orderId: created.id,
              customerId: safeCustomerId,
              lines: loyaltyLines,
              amounts: { subtotal, shipping },
              rules,
              ownedStamps,
            });
            earned = { ...gained, redeemedProduct: redeemed?.name ?? null };
          }
          return created;
        });
      } catch (err) {
        // Retry only on an (astronomically unlikely) order-number collision.
        const msg = err instanceof Error ? err.message : "";
        if (!(err instanceof OrderValidationError) && /P2002|Unique constraint/i.test(msg) && /orderNumber/.test(msg)) continue;
        throw err;
      }
    }
    if (!createdOrder) throw new Error("Could not allocate an order number");
    refreshCatalog(); // stock changed

    // (Admins see new orders via the dashboard bell, which polls /api/admin/orders/latest.)

    // Order is safely saved. Email is best-effort — never fail a saved order
    // just because SMTP is unavailable — and it goes out after the reply, so
    // the shopper reaches the confirmation page without waiting on SMTP.
    after(async () => {
      try {
        await sendOrderEmails({
          orderNumber,
          customerName: data.customerName,
          email,
          phone: data.phone,
          address: address ?? `Retiro en ${branch.name}`,
          city: city ?? branch.city,
          branchName: branch.name,
          fulfillment: data.fulfillment,
          paymentMethod: data.paymentMethod,
          items: lineItems.map((i) => ({ name: i.name, quantity: i.quantity, price: i.price })),
          subtotal,
          shipping,
          total,
        });
      } catch (emailErr) {
        console.error("[order] email send failed (order still saved):", emailErr);
      }
    });

    return { ok: true, orderNumber, total, loyalty: earned };
  } catch (err) {
    // Cart/stock problems are safe to show to the customer verbatim.
    if (err instanceof OrderValidationError) {
      return { ok: false, error: err.message };
    }
    // Anything else is an unexpected server/database error. Log the real
    // cause for us, show the customer a clear (non-fake) failure — never a
    // fake success that silently loses the order.
    console.error("[order] failed to create order:", err);
    return {
      ok: false,
      error: "Lo sentimos, no pudimos registrar tu pedido ahora. Inténtalo de nuevo en un momento.",
    };
  }
}
import { createHmac, randomInt, timingSafeEqual } from "node:crypto";
import { cookies } from "next/headers";
import { prisma } from "./prisma";
import { createToken, readToken, derivedKey } from "./session-token";
import { sendOtpEmail } from "./email";
import type { Prisma } from "@prisma/client";

// Email one-time codes (OTP) for sign-up and email verification.
//  - 6 digits from a CSPRNG, stored only as an HMAC (keyed from AUTH_SECRET).
//  - Expires after 10 minutes; 5 wrong attempts burn the code.
//  - Resend: 60 s cooldown, at most 5 codes per hour per email+purpose.
//  - The pending flow is tied to the browser with a short-lived signed,
//    httpOnly cookie, so the email never has to travel in the URL.

export type OtpPurpose = "register" | "verify";

export const OTP_LENGTH = 6;
const CODE_TTL_MS = 10 * 60_000;
const MAX_ATTEMPTS = 5;
export const RESEND_COOLDOWN_S = 60;
const MAX_SENDS_PER_HOUR = 5;
const PENDING_COOKIE = "inbramet_verify";
const PENDING_TTL_S = 30 * 60;

type Pending = { email: string; purpose: OtpPurpose; exp: number };

function hashCode(email: string, purpose: OtpPurpose, code: string): string {
  return createHmac("sha256", derivedKey("otp")).update(`${purpose}:${email}:${code}`).digest("hex");
}

export function maskEmail(email: string): string {
  const [user, domain] = email.split("@");
  if (!domain) return email;
  const shown = user.length <= 2 ? user[0] : user.slice(0, 2);
  return `${shown}${"•".repeat(Math.max(2, Math.min(6, user.length - shown.length)))}@${domain}`;
}

// ---------- pending cookie ----------

export async function setPending(email: string, purpose: OtpPurpose) {
  const store = await cookies();
  store.set(PENDING_COOKIE, createToken<Pending>("verify", { email, purpose, exp: Math.floor(Date.now() / 1000) + PENDING_TTL_S }), {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
    maxAge: PENDING_TTL_S,
  });
}

export async function getPending(purpose: OtpPurpose): Promise<Pending | null> {
  const store = await cookies();
  const token = store.get(PENDING_COOKIE)?.value;
  const p = token ? readToken<Pending>("verify", token) : null;
  return p && p.purpose === purpose ? p : null;
}

export async function clearPending() {
  const store = await cookies();
  store.delete(PENDING_COOKIE);
}

// ---------- issue / verify ----------

export type IssueResult = { ok: true } | { ok: false; error: string; retryAfter?: number };

/** Creates (or replaces) a code for email+purpose and emails it. */
export async function issueCode(
  email: string,
  purpose: OtpPurpose,
  payload?: Prisma.InputJsonValue
): Promise<IssueResult> {
  const now = Date.now();
  const existing = await prisma.emailVerification.findUnique({ where: { email_purpose: { email, purpose } } });

  if (existing) {
    const since = (now - existing.lastSentAt.getTime()) / 1000;
    if (since < RESEND_COOLDOWN_S) {
      const wait = Math.ceil(RESEND_COOLDOWN_S - since);
      return { ok: false, error: `Espera ${wait}s antes de pedir un nuevo código.`, retryAfter: wait };
    }
    const withinHour = now - existing.createdAt.getTime() < 60 * 60_000;
    if (withinHour && existing.sendCount >= MAX_SENDS_PER_HOUR) {
      return { ok: false, error: "Pediste demasiados códigos. Inténtalo de nuevo en una hora." };
    }
  }

  const code = String(randomInt(0, 10 ** OTP_LENGTH)).padStart(OTP_LENGTH, "0");
  const data = {
    codeHash: hashCode(email, purpose, code),
    attempts: 0,
    lastSentAt: new Date(now),
    expiresAt: new Date(now + CODE_TTL_MS),
    ...(payload !== undefined ? { payload } : {}),
  };

  const sent = await sendOtpEmail(email, code, purpose);
  if (!sent.ok) return { ok: false, error: sent.error };

  const resetWindow = !existing || now - existing.createdAt.getTime() >= 60 * 60_000;
  await prisma.emailVerification.upsert({
    where: { email_purpose: { email, purpose } },
    create: { email, purpose, ...data },
    update: resetWindow
      ? { ...data, sendCount: 1, createdAt: new Date(now) }
      : { ...data, sendCount: { increment: 1 } },
  });
  return { ok: true };
}

export type VerifyResult =
  | { ok: true; payload: Prisma.JsonValue | null }
  | { ok: false; error: string; reason: "invalid" | "expired" | "locked" | "missing" };

/** Checks a code. On success the code is consumed and its payload returned. */
export async function verifyCode(email: string, purpose: OtpPurpose, code: string): Promise<VerifyResult> {
  const rec = await prisma.emailVerification.findUnique({ where: { email_purpose: { email, purpose } } });
  if (!rec) return { ok: false, reason: "missing", error: "No encontramos un código: pide uno nuevo." };
  if (rec.expiresAt.getTime() < Date.now())
    return { ok: false, reason: "expired", error: "El código expiró. Toca “Reenviar código” para obtener uno nuevo." };
  if (rec.attempts >= MAX_ATTEMPTS)
    return { ok: false, reason: "locked", error: "Demasiados intentos incorrectos. Toca “Reenviar código” para obtener uno nuevo." };

  const clean = code.replace(/\D/g, "");
  const a = Buffer.from(hashCode(email, purpose, clean));
  const b = Buffer.from(rec.codeHash);
  const match = clean.length === OTP_LENGTH && a.length === b.length && timingSafeEqual(a, b);

  if (!match) {
    const updated = await prisma.emailVerification.update({
      where: { id: rec.id },
      data: { attempts: { increment: 1 } },
      select: { attempts: true },
    });
    const left = MAX_ATTEMPTS - updated.attempts;
    return left > 0
      ? { ok: false, reason: "invalid", error: `Código incorrecto. ${left === 1 ? "Queda 1 intento." : `Quedan ${left} intentos.`}` }
      : { ok: false, reason: "locked", error: "Demasiados intentos incorrectos. Toca “Reenviar código” para obtener uno nuevo." };
  }

  await prisma.emailVerification.delete({ where: { id: rec.id } });
  return { ok: true, payload: rec.payload };
}

/** Seconds until "Resend" is allowed (for the countdown on the page). */
export async function resendWaitSeconds(email: string, purpose: OtpPurpose): Promise<number> {
  const rec = await prisma.emailVerification.findUnique({
    where: { email_purpose: { email, purpose } },
    select: { lastSentAt: true },
  });
  if (!rec) return 0;
  return Math.max(0, Math.ceil(RESEND_COOLDOWN_S - (Date.now() - rec.lastSentAt.getTime()) / 1000));
}
import { scryptSync, randomBytes, timingSafeEqual } from "node:crypto";

// Password hashing with scrypt (salted). Kept dependency-free and free of any
// Next.js imports so it can be used from standalone scripts (e.g. create-admin)
// as well as from the app.

// Minimum length for customer passwords (register, checkout sign-up, reset).
export { MIN_PASSWORD } from "./auth-rules";

export function hashPassword(password: string): string {
  const salt = randomBytes(16).toString("hex");
  const hash = scryptSync(password, salt, 64).toString("hex");
  return `${salt}:${hash}`;
}

export function verifyPassword(password: string, stored: string): boolean {
  const [salt, hash] = stored.split(":");
  if (!salt || !hash) return false;
  const hashBuf = Buffer.from(hash, "hex");
  const test = scryptSync(password, salt, 64);
  return hashBuf.length === test.length && timingSafeEqual(hashBuf, test);
}
// Payment gateway integration — PayFast (Brasil) & Safepay.
//
// Both require a merchant account (arranged by the client). Until the relevant
// env vars are set, `configured` is false and checkout falls back to placing a
// pending order (preview mode). Once credentials are added, the online methods
// initiate a real gateway redirect.
//
// NOTE: Endpoint URLs and field names follow each gateway's public docs and may
// need small adjustments to match the client's specific account / API version.
// Callbacks are verified server-side before an order is marked PAID:
//   PayFast  → validation_hash = sha256(basket_id|SECURED_KEY|MERCHANT_ID|err_code)
//   Safepay  → X-SFPY-SIGNATURE = HMAC-SHA512(webhook body, SAFEPAY_WEBHOOK_SECRET)
// Confirm both formulas against the client's merchant documentation at go-live.

import { createHash, createHmac, randomBytes, timingSafeEqual } from "node:crypto";

export type PaymentMethod = "COD" | "PAYFAST" | "SAFEPAY";

export type PaymentInitInput = {
  orderNumber: string;
  amount: number; // BOB
  customer: { name: string; email: string; phone: string };
  returnUrl: string; // where the gateway sends the buyer back on success
  cancelUrl: string; // ... and on failure / cancel
  notifyUrl: string; // server-to-server notification (IPN / webhook)
};

export type PaymentInitResult =
  | { configured: false }
  | { configured: true; ok: true; redirectUrl: string; reference?: string }
  | { configured: true; ok: false; error: string };

// ---------- Config ----------

export function payfastConfigured(): boolean {
  return Boolean(process.env.PAYFAST_MERCHANT_ID && process.env.PAYFAST_SECURED_KEY);
}

export function safepayConfigured(): boolean {
  // The webhook secret is required too — without it payments can't be verified.
  return Boolean(process.env.SAFEPAY_API_KEY && process.env.SAFEPAY_WEBHOOK_SECRET);
}

export function isOnlineConfigured(method: PaymentMethod): boolean {
  if (method === "PAYFAST") return payfastConfigured();
  if (method === "SAFEPAY") return safepayConfigured();
  return false;
}

// ---------- PayFast ----------

async function initiatePayfast(input: PaymentInitInput): Promise<PaymentInitResult> {
  if (!payfastConfigured()) return { configured: false };

  const sandbox = process.env.PAYFAST_SANDBOX !== "false";
  const base = sandbox
    ? "https://ipguat.apps.net.pk/Ecommerce/api/Transaction"
    : "https://ipg1.apps.net.pk/Ecommerce/api/Transaction";

  try {
    // 1) Get an access token
    const tokenBody = new URLSearchParams({
      MERCHANT_ID: process.env.PAYFAST_MERCHANT_ID!,
      SECURED_KEY: process.env.PAYFAST_SECURED_KEY!,
      BASKET_ID: input.orderNumber,
      TXNAMT: input.amount.toFixed(2),
      CURRENCY_CODE: "BOB",
    });
    const tokenRes = await fetch(`${base}/GetAccessToken`, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: tokenBody,
      signal: AbortSignal.timeout(15000),
    });
    const tokenJson = (await tokenRes.json()) as { ACCESS_TOKEN?: string };
    const token = tokenJson.ACCESS_TOKEN;
    if (!token) return { configured: true, ok: false, error: "PayFast token error" };

    // 2) Build the hosted-checkout redirect (buyer completes payment there)
    const params = new URLSearchParams({
      MERCHANT_ID: process.env.PAYFAST_MERCHANT_ID!,
      MERCHANT_NAME: "Inbramet",
      TOKEN: token,
      PROCCODE: "00",
      TXNAMT: input.amount.toFixed(2),
      CUSTOMER_MOBILE_NO: input.customer.phone,
      CUSTOMER_EMAIL_ADDRESS: input.customer.email,
      SIGNATURE: randomBytes(12).toString("hex"),
      VERSION: "Inbramet-1.0",
      TXNDESC: `Inbramet order ${input.orderNumber}`,
      SUCCESS_URL: input.returnUrl,
      FAILURE_URL: input.cancelUrl,
      CHECKOUT_URL: input.notifyUrl,
      BASKET_ID: input.orderNumber,
      ORDER_DATE: new Date().toISOString(),
      CURRENCY_CODE: "BOB",
    });
    return {
      configured: true,
      ok: true,
      redirectUrl: `${base}/PostTransaction?${params.toString()}`,
    };
  } catch (err) {
    return {
      configured: true,
      ok: false,
      error: err instanceof Error ? err.message : "PayFast error",
    };
  }
}

// ---------- Safepay ----------

async function initiateSafepay(input: PaymentInitInput): Promise<PaymentInitResult> {
  if (!safepayConfigured()) return { configured: false };

  const sandbox = process.env.SAFEPAY_SANDBOX !== "false";
  const apiBase = sandbox
    ? "https://sandbox.api.getsafepay.com"
    : "https://api.getsafepay.com";
  const environment = sandbox ? "sandbox" : "production";

  try {
    // 1) Initialize an order — returns a tracker token
    const initRes = await fetch(`${apiBase}/order/v1/init`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        client: process.env.SAFEPAY_API_KEY,
        amount: input.amount,
        currency: "BOB",
        environment,
      }),
      signal: AbortSignal.timeout(15000),
    });
    const initJson = (await initRes.json()) as { data?: { token?: string } };
    const token = initJson.data?.token;
    if (!token) return { configured: true, ok: false, error: "Safepay init error" };

    // 2) Redirect the buyer to Safepay's hosted checkout
    const params = new URLSearchParams({
      beacon: token,
      env: environment,
      source: "custom",
      order_id: input.orderNumber,
      redirect_url: input.returnUrl,
      cancel_url: input.cancelUrl,
    });
    return {
      configured: true,
      ok: true,
      redirectUrl: `${apiBase}/checkout/pay?${params.toString()}`,
      reference: token, // tracker — the webhook identifies the payment by it
    };
  } catch (err) {
    return {
      configured: true,
      ok: false,
      error: err instanceof Error ? err.message : "Safepay error",
    };
  }
}

// ---------- Dispatch ----------

export async function initiatePayment(
  method: PaymentMethod,
  input: PaymentInitInput
): Promise<PaymentInitResult> {
  if (method === "PAYFAST") return initiatePayfast(input);
  if (method === "SAFEPAY") return initiateSafepay(input);
  return { configured: false }; // COD needs no gateway
}

// ---------- Callback verification ----------

function safeEqual(a: string, b: string): boolean {
  const x = Buffer.from(a);
  const y = Buffer.from(b);
  return x.length === y.length && timingSafeEqual(x, y);
}

export function verifyPayfastHash(basketId: string, errCode: string, hash: string): boolean {
  const merchant = process.env.PAYFAST_MERCHANT_ID;
  const key = process.env.PAYFAST_SECURED_KEY;
  if (!merchant || !key || !hash) return false;
  const expected = createHash("sha256")
    .update(`${basketId}|${key}|${merchant}|${errCode}`)
    .digest("hex");
  return safeEqual(expected.toLowerCase(), hash.trim().toLowerCase());
}

export function verifySafepaySignature(rawBody: string, dataJson: string, signature: string): boolean {
  const secret = process.env.SAFEPAY_WEBHOOK_SECRET;
  if (!secret || !signature) return false;
  const sig = signature.trim().toLowerCase();
  // Safepay signs the event's `data` object; accept the raw body form as well.
  return [dataJson, rawBody].some((body) =>
    safeEqual(createHmac("sha512", secret).update(body).digest("hex"), sig)
  );
}
import { PrismaClient } from "@prisma/client";

// Reuse a single PrismaClient across hot reloads in development
// to avoid exhausting the database connection pool.
const globalForPrisma = globalThis as unknown as {
  prisma: PrismaClient | undefined;
};

export const prisma =
  globalForPrisma.prisma ??
  new PrismaClient({
    log: process.env.NODE_ENV === "development" ? ["error", "warn"] : ["error"],
  });

if (process.env.NODE_ENV !== "production") {
  globalForPrisma.prisma = prisma;
}
import { headers } from "next/headers";

// Minimal fixed-window rate limiter (in-memory, per process). Good enough for the
// single-instance VPS deployment this store targets; swap for Redis if the app is
// ever scaled to multiple instances.

type Bucket = { count: number; resetAt: number };
const buckets = new Map<string, Bucket>();

export async function clientIp(): Promise<string> {
  const h = await headers();
  const fwd = h.get("x-forwarded-for");
  return (fwd ? fwd.split(",")[0] : h.get("x-real-ip"))?.trim() || "unknown";
}

// Returns true when the action is allowed, false when the limit is exceeded.
export function rateLimit(key: string, limit: number, windowMs: number): boolean {
  const now = Date.now();
  const b = buckets.get(key);
  if (!b || b.resetAt <= now) {
    buckets.set(key, { count: 1, resetAt: now + windowMs });
    if (buckets.size > 10_000) {
      for (const [k, v] of buckets) if (v.resetAt <= now) buckets.delete(k);
    }
    return true;
  }
  b.count += 1;
  return b.count <= limit;
}

